(window.GIM_TS=window.GIM_TS||{})["Gittin.4"]={"from":96,"a":[["ומאידך גיסא, מי שהיה ערב \u0003קבלן\u0004 של \u0003בעל חוב\u0004 — \u0003דברי הכל משתעבד\u0004 וחייב לפרוע את החוב של הלווה, ואולם \u0003ערב\u0004 סתם של \u0003בעל חוב ו\u0004ערב \u0003קבלן\u0004 של \u0003כתובה פליגי\u0004 \u0005[נחלקו\u0006 בכך\u0005],\u0006 \u0003איכא למאן דאמר\u0004 \u0005[יש למי שאומר]:\u0006 \u0003אף על גב דלית ליה נכסי\u0004 \u0005[אף על פי שאין לו נכסים]\u0006 \u0003ללוה\u0004 בשעת ההלוואה — \u0003משתעבד\u0004 הערב, \u0003ואיכא למאן דאמר\u0004 \u0005[ויש למי שאומר]:\u0006 \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 ללווה נכסים — \u0003משתעבד\u0004 הערב, \u0003אי לית ליה\u0004 \u0005[אם אין לו]\u0006 — \u0003לא משתעבד.\u0004","\u0003והילכתא\u0004 \u0005[ו\u0006פסק \u0005הלכה\u0006 הוא\u0005]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם],\u0006 \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 ללווה נכסים — \u0003משתעבד\u0004 הערב, בר \u0005[חוץ]\u0006 \u0003מערב\u0004 של \u0003כתובה, דאף על גב דאית ליה\u0004 \u0005[שאף על פי שיש לו]\u0006 לבעל נכסים כאשר הוא כותב את הכתובה — \u0003לא מש\u0004 \u0003תעבד\u0004 הערב.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003מצוה\u0004 \u0003הוא דעבד\u0004 \u0005[שעשה]\u0006 שעל ידי זה הסכימה האשה להינשא, \u0003ו\u0004עוד, \u0003לא מידי חסרה\u0004 \u0005[אין\u0006 האשה \u0005חסרה\u0006 דבר\u0005]\u0006 שעבורו הוא משתעבד, שהרי אין הבעל לווה כסף מן האשה, ולכן תיקנו חכמים שאין הערב משתעבד.","\u0003אמר ר\u0004 \u0003בינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ביחס לגביית הכתובה מן הזיבורית — האם דווקא ביתומים הדברים אמורים, \u0003מעיקרא דתקנתין\u0004 \u0005[מעיקר תקנתנו]\u0006 שאמרו: מפני מה אמרו כתובת אשה בזיבורית — ש\u0003יותר ממה שהאיש רוצה לישא אשה רוצה לינשא. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שמדובר פה בגובה דווקא \u0003מיתמי\u0004 \u0005[מיתומים],\u0006 אם כן \u0003האי\u0004 \u0005[\u0006טעמו של דין \u0005זה]\u0006 \u0003משום דיתמי\u0004 \u0005[ש\u0006רכוש \u0005יתומים]\u0006 \u0003הוא\u0004 ולא בגלל האשה. ומטעם זה של המשנה משמע כי הוא הדין גם כשגובה בחיי הבעל, ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003מר זוטרא\u0004 שהעמיד את דין משנתנו ביתומים! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","כיון שהובאו דברי מר זוטרא בנו של רב נחמן, מביאים בשמו הלכה אחרת בנושא דומה: \u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: שטר חוב\u0004 של האב \u0003היוצא על היתומין\u0004 לפורעו, \u0003אף על פי שכתוב בו שבח\u0004 שהוסכם ביניהם שיגבה המלווה ממיטב הקרקעות, מן העידית — \u0003אינו גובה אלא מן הזיבורית.\u0004","\u0003אמר אביי: תדע\u0004 שכן הוא, שהרי בכלל \u0003בעל חוב דיניה\u0004 \u0005[דינו]\u0006 לגבות \u0003בבינונית, ו\u0004בכל זאת \u0003מיתמי\u0004 \u0005[מיתומים]\u0006 \u0003בזיבורית.\u0004 משמע שאף שכך הוא עיקר הדין, במקום יתומים אין מקיימים אותו, אלא מגבים מן הזיבורית, וכל שכן שתקנת יתומים חשובה יותר מתנאי פרטי הכתוב בשטר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בעל חוב\u0004 באמת \u0003דיניה מדאורייתא\u0004 \u0005[דינו מן התורה]\u0006 \u0003בזיבורית, כ\u0004דברי \u0003עולא,\u0004 ש\u0003אמר עולא:\u0004 \u0003דבר תורה בעל חוב\u0004 גובה \u0003בזיבורית, שנאמר: \"בחוץ תעמד והאיש\u0004 אשר אתה נושה בו יוציא אליך את העבוט החוצה\u0003\"\u0004 (דברים כד, יא), \u0003מה דרכו של איש להוציא\u0004 כמשכון — \u0003פחות שבכלים,\u0004 ומכאן נלמד שאין המלווה זכאי ליותר מן הפחות שבכלים, ולכן אף בקרקעות הוא מקבל בפרעון חובו את הפחותה שבקרקעותיו של הלווה, \u0003ומה טעם אמרו\u0004 חכמים ש\u0003בעל חוב\u0004 גובה \u0003בבינונית? כדי שלא תנעול דלת בפני לוין,\u0004 שלא יימנעו מלהלוות לאנשים, \u0003וגבי יתמי אוקמוה רבנן אדאורייתא\u0004 \u0005[ואצל יתומים העמידו אותה חכמים על\u0006 דין \u0005תורה].\u0006","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 כשהיה כתוב תנאי בשטר, \u0003כיון דדיניה מדאורייתא\u0004 \u0005[שדינו מן התורה]\u0006 \u0003בעידית,\u0004 שהרי כך התנה בחוזה — \u0003אפילו מיתמי נמי\u0004 \u0005[מיתומים גם כן]\u0006 דינו \u0003בעידית.\u0004","ושואלים: \u0003ול\u0004הסבר זה של \u0003רבא, והתני\u0004 \u0005[והרי שנה]\u0006 החכם \u0003אברם חוזאה: אין נפרעין מנכסי יתומין אלא מן הזיבורית, ואפילו הן\u0004 נגבים לצורך \u0003ניזקין.\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ניזקין דינן מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003בעידית,\u0004 משמע שתיקנו חכמים שמיתומים גובים בכל מקרה רק זיבורית!","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא ששנה אברם חוזאה, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 — \u0003כגון שהיתה עידית\u0004 של ה\u0003ניזק\u0004 שווה \u0003כזיבורית\u0004 של ה\u0003מזיק,\u0004 כלומר של היתומים,","\u0003ו\u0004כל זה שיטת \u0003ר' ישמעאל היא,\u0004 ש\u0003אמר: מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003ב\u0004עידית של \u0003ניזק שיימינן\u0004 \u0005[אנו מעריכים\u0006 וגובים\u0005],\u0006 \u0003ומפני תיקון העולם תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 \u0003ב\u0004עידית של \u0003מזיק, וגבי יתמי אוקמוה רבנן אדאורייתא\u0004 \u0005[ואצל יתומים העמידו חכמים\u0006 את הדבר \u0005על\u0006 דין \u0005תורה]\u0006 והם משלמים מזיבורית שלהם, שהיא כעידית של הניזק. אבל במקרה רגיל אין גובים לניזקין מן היתומים אלא מעידית, והוא הדין לשטר חוב שנכתב בו שיגבה מן העידית.","ומקשים: \u0003איני\u0004 \u0005[האמנם\u0006 כן הוא\u0005]?!\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' אליעזר ניותאה: אין נפרעין\u0004 לבעל חוב \u0003מנכסי יתומים אלא מן הזיבורית, ואפילו הן עידית.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אפילו הן עידית\"? לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא כך: \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שכתוב]\u0006 \u0003עידית בשטרא\u0004 \u0005[בשטר],\u0006 בכל זאת הם גובים מן הזיבורית?","ודוחים: \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עידית\"?\u0004 שהיתומים יכולים לפרוע אף \u0003שפאי עידית,\u0004 קרקע הנמצאת במקום שאינו ניתן לעיבוד ושמירה, וערכה בשוק פחות מזיבורית.","\u0003ו\u0004שזאת הכוונה ב\"שפאי עידית\" אנו למדים מדברי \u0003רבא,\u0004 שאמר רבא: אם \u0003הזיק זיבורית\u0004 — \u0003גובה מן העידית,\u0004 אם הזיק מ\u0003שפאי עידית — גובה מן הבינונית,\u0004 שקנסו את הניזק לשלם דבר המשובח הרבה ממה שהזיק, ולפיכך אם הזיק שדה פחותה מזיבורית די בגבייה מבינונית. ומדוע שנה ר' אליעזר ניותאה שיתומים פורעים חוב אף מן הקרקע הגרועה ביותר — שכן \u0003גבי יתמי אוקמוה רבנן אדאורייתא\u0004 \u0005[אצל יתומים העמידו חכמים\u0006 את הדבר \u0005על\u0006 דין \u0005תורה],\u0006 שדינו של בעל חוב בזיבורית.","שנינו במשנה: \u0003אין נפרעין מנכסי יתומין אלא מן הזיבורית. בעי\u0004 \u0005[שאל]\u0006 \u0003רב אחדבוי בר אמי\u0004 בבירור כוונת הדברים: \u0003\"יתומין\" שאמרו,\u0004 האם הכוונה דווקא יתומים \u0003קטנים, או אפילו גדולים?\u0004 והשאלה היא זו: האם \u0003תקנתא\u0004 \u0005[תקנה]\u0006 \u0003היא דעבוד רבנן גבי יתמי\u0004 \u0005[שעשו חכמים אצל יתומים],\u0006 \u0003לקטנים עבוד רבנן\u0004 \u0005[עשו חכמים]\u0006 תקנה זו, \u0003לגדולים לא עבוד רבנן\u0004 \u0005[עשו חכמים]\u0006 תקנה זו.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 הטעם הוא אחר: \u0003משום\u0004 ש\u0003לא מסיק אדעתא\u0004 \u0005[עולה על דעתו]\u0006 של ה\u0003מלוה דמית לוה ונפלי נכסי קמי יתמי\u0004 \u0005[שימות הלווה ויפלו הנכסים לפני היתומים],\u0006 \u0003דהוה ליה\u0004 \u0005[שהיה לו]\u0006 משום כך טעם להיות \u0003נועל דלת\u0004 בפני לווים, ונמצא שעיקר התקנה שיגבה בעל חוב מן הבינונית לא תוקנה אלא במקרים הרגילים, ולא חששו לתקן תקנה זו לגבי יורשים בכלל, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003אפילו גדולים נמי\u0004 \u0005[גם כן]\u0006 פורעים מן הזיבורית?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003אביי קשישא\u0004 \u0005[הזקן]\u0006 (ולא אביי החכם המפורסם): \u0003יתומין שאמרו\u0004 בכל מקום — \u0003גדולים, ואין צריך לומר קטנים.\u0004","ודוחים: \u0003ודלמא הני מילי\u0004 \u0005[ושמא דברים אלה\u0006 אמורים\u0005]\u0006 \u0003לענין שבועה,\u0004 שמה שאמרו שאין נפרעים מנכסי יתומים אלא בשבועה, דין זה אמור גם ביתומים גדולים, ומדוע? שגם בן \u0003גדול במילי דאבוה\u0004 \u0005[בדברים,\u0006 בעסקים של אביו\u0005]\u0006 \u0003כקטן דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 משום שאינו יודע בפרטי עסקי אביו, ושמא פרע אביו בינתיים את החוב, \u0003אבל לענין זיבורית\u0004 — \u0003לא,\u0004 ואין הדברים אמורים אלא בקטנים.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006"],["\u0003יתומין שאמרו\u0004 — \u0003גדולים, ואין צריך לומר קטנים\u0004, \u0003בין ל\u0004ענין \u0003שבועה\u0004 שאין נפרעים מהם אלא בשבועה, \u0003בין ל\u0004ענין \u0003זיבורית\u0004 שאין נפרעים מהם אלא זיבורית.","שנינו במשנה: \u0003אין נפרעין מנכסים משועבדים במקום שיש בני חורין.\u0004 אף כאן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אחדבוי בר אמי:\u0004 קרקע שנתן החייב \u0003במתנה\u0004 לחבירו \u0003היאך\u0004 הדין? האם גם במקרה זה אין נפרעים מנכסים משועבדים כשישנם נכסים בני חורין?","וצדדי השאלה: האם \u0003תקנתא הוא דעבוד רבנן\u0004 \u0005[תקנה היא שעשו חכמים]\u0006 \u0003משום פסידא\u0004 \u0005[הפסד]\u0006 של ה\u0003לקוחות\u0004 ששילמו עבור הקרקעות שקנו, \u0003אבל מתנה, דליכא פסידא\u0004 \u0005[שאין הפסד]\u0006 של \u0003לקוחות\u0004 — \u0003לא,\u0004 שהרי גם אם תילקח המתנה מן המקבל לא הפסיד דבר, שהרי לא השקיע בכך. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מתנה נמי\u0004 \u0005[גם כן],\u0006 \u0003אי לאו דאית ליה\u0004 \u0005[אם לא שיש לו]\u0006 לנותן מתנה \u0003הנאה מיניה\u0004 \u0005[ממנו]\u0006 ממקבל המתנה — \u0003לא יהיב ליה\u0004 \u0005[היה נותן לו]\u0006 \u0003מתנה,\u0004 \u0003והלכך\u0004 (ועל כן) \u0003כי פסידא\u0004 \u0005[כמו הפסד]\u0006 של \u0003לקוחות דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 ואין נפרעים מהם במקום שיש נכסים בני חורין בידיו של נותן המתנה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003שכיב מרע שאמר: \"תנו מאתים זוז לפלוני ושלש מאות לפלוני וארבע מאות לפלוני\"\u0004 — \u0003אין אומרים\u0004 במקרה זה: \u0003כל הקודם בשטר\u0004 הצוואה \u0003זכה.\u0004 \u0003לפיכך\u0004 אם \u0003יצא עליו,\u0004 על נותן המתנה \u0003שטר חוב\u0004 ומתברר שהנכסים היו משועבדים לאדם אחר, הרי אותו אדם \u0003גובה מכולן.\u0004","\u0003אבל אם אמר\u0004 השכיב מרע: \u0003\"תנו מאתים זוז לפלוני ואחריו לפלוני ואחריו לפלוני\"\u0004 — \u0003אומרים: כל הקודם בשטר זכה. לפיכך\u0004 אם \u0003יצא עליו שטר חוב\u0004 — \u0003גובה\u0004 תחילה קרקע \u0003מן האחרון\u0004 שבהם, ואם \u0003אין לו,\u0004 שאין בקרקע שנתן לו האחרון כדי לשלם את החוב — \u0003גובה משלפניו, אין לו\u0004 — \u0003גובה משלפני פניו.\u0004","\u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שייתכן כי \u0003דקמא\u0004 \u0005[של הראשון]\u0006 היא \u0003בינונית ובתרא\u0004 \u0005[ו\u0006של \u0005האחרון]\u0006 היא \u0003זיבורית,\u0004 ודינו של בעל חוב בבינונית, מכל מקום \u0003מזיבורית, גבי\u0004 \u0005[\u0006הוא \u0005גובה]\u0006 שהרי הוא גובה מן האחרון, \u0003מבינונית לא גבי\u0004 \u0005[גובה].\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003במתנה נמי עבוד רבנן תקנתא\u0004 \u0005[גם כן עשו חכמים תקנה\u0006 זו\u0005]\u0006 שאין גובים ממשועבדים במקום שיש בני חורין, שהמתנה השניה נחשבת בת חורין לגבי המתנה הראשונה, שהרי כך היתה בזמן שכבר ניתנה המתנה הראשונה.","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בבעל חוב.\u0004 שאין מדובר פה בשכיב מרע שנותן כספים במתנה, אלא שמחלק אותם בין בעלי חובותיו. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"תנו\" קאמר\u0004 \u0005[אמר]\u0006 שהיא לשון מתנה! ומשיבים: הכוונה היא \u0003\"תנו בחובי\".\u0004","ושואלים: אם כן, לשם מה לדון בדבר לפי מה שאמר המצוה? \u0003וליחזי שטרא דמאן קדים\u0004 \u0005[ונראה שטרו של מי קודם]\u0006 והוא זה שזכויותיו קודמות! ומשיבים: מדובר כאן \u0003דליכא שטרא\u0004 \u0005[שאין שטר],\u0006 וכגון שאיבדו בעלי החובות את השטרות. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"כל הקודם בשטר\" קאמר\u0004 \u0005[אומר הוא],\u0006 משמע שיש שטר! ומשיבים: הכוונה היא כל המוקדם \u0003בשטר פקדתא\u0004 \u0005[הצוואה],\u0006 ושטר זה קיים לפנינו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אפילו מתנה נמי\u0004 \u0005[גם כן]\u0006 הדין כן, שגובה מן האחרון, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]\u0006 אם אין תקנת המשנה חלה על מתנה, מדוע גובה מן האחרון אף אם לראשון יש בינונית, שכן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"גובה מן האחרון\"?\u0004 הכוונה: \u0003אין נפסד אלא אחרון,\u0004 שבעצם בעל החוב גובה מבינונית בכל מקום שהיא (אפילו מן המקבל הראשון), אבל אחר כך חוזרים המקבלים ומחלקים ביניהם את הקרקעות לפי הסדר שבצוואה, ונמצא תמיד שיפסיד האחרון ולא אחר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 בברייתא מדובר \u0003דשוו כולהו להדדי\u0004 \u0005[ש\u0006הקרקעות \u0005שוות כולן זו לזו],\u0006 שאין סיבה לגבות דווקא מן הראשון משום שיש לו בינונית ולאחרון אין, ואז אפשר לעשות קדימה ואיחור באלה. ועל כל פנים ראיה גמורה אין מכאן שאף במתנה נתקנה תקנת המשנה.","שנינו במשנה ש\u0003אין מוציאין לאכילת פירות\u0004 מן המשועבדים. שאם גזל אדם שדה ומכרה והחזירו את השדה לבעליה, אין הקונה מן הגזלן מפוצה מנכסים משועבדים של הגזלן על פירות השדה שגידל. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר עולא אמר ריש לקיש: לפי שאין כתובין\u0004 בנוסח האחריות שקיבל עליו הגזלן כשמכר את השדה, ולכן הם נחשבים כמילווה בעל פה, שאינו ידוע ברבים, ואין מחייבים את הקונים קרקע אחרת מאותו גזלן לשלם עבור חובות שלא ידוע לרבים על קיומם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לעולא: והא\u0004 \u0005[והרי]\u0006 \u0003מזון האשה והבנות דכמאן דכתיבי דמו\u0004 \u0005[שכמו שכתובים\u0006 הם \u0005נחשבים],\u0006 שאפילו אם לא כתב אותם, הם מן התנאים הקבועים בכתובה, שהם תנאי בית דין, וידוע לכל שחייבים בהם, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]:\u0006 \u0003אין מוציאין\u0004 להם מנכסים משועבדים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003התם\u0004 \u0005[שם],\u0006 בענין מזון האשה והבנות, \u0003מעיקרא הכי אתקון\u0004 \u0005[מתחילה כך תיקנו]\u0006 חכמים, שנחשבים \u0003כתובין הן אצל בני חורין\u0004 לגבות מהם, \u0003ואין כתובין הן אצל משועבדין.\u0004","\u0003וכן אמר ר' אסי אמר ר' יוחנן\u0004 בענין משנתנו: מדוע אין מוציאים לאכילת פירות מנכסים משועבדים — \u0003לפי שאין כתובין.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב אסי: והא\u0004 \u0005[והרי]\u0006 \u0003מזון האשה והבנות דכמאן דכתיבי דמו\u0004 \u0005[שכמו שכתובים\u0006 הם \u0005נחשבים],\u0006 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אין מוציאין! אמר ליה\u0004 \u0005[לו]\u0006 רב אסי: \u0003מעיקרא הכי אתקון\u0004 \u0005[מתחילה כך תיקנו]:\u0006 \u0003כתובין הן אצל בני חורין, ואין כתובין הן אצל משועבדין.\u0004 עד כאן ניתן טעם אחד לדין המשנה.","\u0003ר' חנינא אמר\u0004 טעם אחר: \u0003לפי שאין\u0004 הפירות \u0003קצובין,\u0004 שאין ידוע מראש כמה יהיו ומה יהיה שווים. ובכל התחייבות שאינה קצובה תיקנו שלא יוציא מנכסים משועבדים, לפי שאין הקונים האחרים מאת מוכר שדה זו (ולענייננו — הגזלן) יכולים להעריך מה שיעור הסיכון שהם נוטלים על עצמם במקרה ותוחזר השדה לבעליה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 \u0003ל\u0004שיטת \u0003ר' חנינא,\u0004 האם גם \u0003קצובין ו\u0004גם \u0003כתובין בעי\u0004 \u0005[צריך]\u0006 על מנת לגבות ממשועבדים, ובא להוסיף על דברי ר' יוחנן,"],["\u0003או דלמא\u0004 \u0005[שמא]\u0006 די כשהם \u0003קצובין\u0004 על מנת לגבות עבורם ממשועבדים, \u0003ואף על פי שאינן כתובים?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שחלקו אמוראים בשאלה הבאה: \u0003מי שמת והניח שתי בנות ובן, וקדמה הראשונה\u0004 בחיי האב \u0003ונטלה עישור נכסים,\u0004 שכך היא הדרך שהאב נותן עשירית מנכסיו לבנותיו לצורך הנדוניה שלהן, \u0003ולא הספיקה שניה לגבות\u0004 עישור נכסים עבור עצמה \u0003עד שמת הבן,\u0004 ונפלה איפוא הירושה לשתיהן והן מתחלקות בה.","\u0003אמר ר' יוחנן: שניה ויתרה,\u0004 כלומר, השניה הפסידה את עישור הנכסים, ואינה זכאית לדרוש שקודם תיטול עישור נכסים, כמו אחותה, ורק אחר כך תחלוקנה שתיהן בשווה בנשאר. \u0003ואמר לו ר' חנינא:\u0004 הלא \u0003גדולה מזו אמרו:\u0004 שגם אם מכר האב את הנכסים \u0003מוציאין\u0004 מן הקונה \u0003ל\u0004צורך \u0003פרנסה\u0004 (נדוניה) של הבנות \u0003ו\u0004אף ש\u0003אין מוציאין למזונות,\u0004 ונמצא שאף לגבי לקוחות זרים נחשבים הנכסים כמשועבדים לפרנסת הבת, ואם כן בוודאי חל שיעבוד זה גם לגבי ירושת הבת האחרת, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כי ה\u0003שניה ויתרה?\u0004","ולענייננו נלמד מכאן: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003פרנסה\u0004 שהזכיר ר' חנינא \u0003דמיקץ קייצא\u0004 \u0005[ש\u0006היא \u0005קצובה],\u0006 שיש לה שיעור מסויים, \u0003מיכתב לא כתיבא\u0004 \u0005[\u0006ו\u0005אינה כתובה],\u0006 \u0003וקא\u0004 \u0005[והריהי]\u0006 \u0003מוציאה\u0004 מנכסים משועבדים!","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרנסה, כיון דאית\u0004 \u0005[שיש]\u0006 \u0003לה קלא\u0004 \u0005[קול,\u0006 פירסום\u0005],\u0006 שאם מת אדם והניח אחריו בנות, הכל יודעים שחלק מנכסיו משועבד לפרנסת הבנות, \u0003כמאן דכתיבא דמי\u0004 \u0005[כמו שהיתה כתובה\u0006 \u0005נחשב\u0006 הדבר \u0005].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר מנוח:\u0004 שנינו שאם נישאה אשה לאיש, והתנתה עימו שיפרנס את בתה מנישואין קודמים, ונתגרשה ונישאה לאיש אחר והתנתה עימו תנאי זהה, כך שאותה בת חורגת מקבלת את פרנסתה משני הבעלים, אם \u0003מתו\u0004 הבעלים — \u0003בנותיהן\u0004 שלהם, אף מאותה אשה, \u0003נזונות\u0004 רק \u0003מנכסים בני חורין\u0004 שהותירו אחריהם, וכפי ששנינו במשנתנו, ואילו היא, הבת החורגת,","\u0003נזונת מנכסים משועבדים, מפני שהיא כבעלת חוב.\u0004 ומכאן קשה לשתי השיטות, שהרי מוציאים למזונותיה של אותה בת, אף שאינם כתובים ושאינם קצובים.","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003בשקנו מידו,\u0004 שעשו קנין על תנאי זה, והרי זה כאילו נכתב הדבר ונתפרסם, ונשתעבד הרכוש למזונות הבת.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדובר במשנה, שעשו קנין, אם כן \u0003בנות נמי\u0004 \u0005[גם כן],\u0006 הואיל ועשו קנין — הרכוש משועבד אף למזונותיהן! ודוחים: מדובר \u0003ב\u0004אופן \u0003שקנו לזו,\u0004 לבת החורגת, \u0003ולא קנו לזו\u0004 לבתו שלו.","ושואלים: \u0003מאי פסקא\u0004 \u0005[מה הפסק]\u0006 מדוע ראית לחתוך את הדברים ולפרש שדווקא כך היה מעשה? ומסבירים: \u0003בת אשתו דהואי\u0004 \u0005[שהיתה]\u0006 \u0003בשעת קנין\u0004 — \u0003מהני\u0004 \u0005[מועיל]\u0006 \u0003לה קנין, בתו שלא הואי\u0004 \u0005[היתה]\u0006 \u0003בשעת קנין\u0004 אלא נולדה לו מאשה זו לאחר מכן — \u0003לא מהני\u0004 \u0005[מועיל]\u0006 \u0003לה קנין.\u0004","ומקשים: \u0003מי לא עסקינן דהוו תרוייהו\u0004 \u0005[האם אין אנו עוסקים\u0006 אפילו במקרה \u0005שהיו שתיהן\u0006 קיימות\u0005]\u0006 \u0003בשעת קנין, והיכי דמי\u0004 \u0005[וכיצד היה דבר זה]\u0006 — כגון שלאחר שנישאה לו ובתה עימה, \u0003גרשה ואהדרה\u0004 \u0005[והחזירה,\u0006 נשאה בשנית\u0005]\u0006 וכבר יש לה בת אחת (או יותר) ממנו. וכיון שגם בתו שלו כבר קיימת מדוע אין קנין מועיל למזונות בתו כפי שמועיל לגבי הבת החורגת?","\u0003אלא,\u0004 כך צריך לומר, מהו ההבדל שביניהן: \u0003בתו\u0004 ש\u0003בתנאי בית דין קאכלה\u0004 \u0005[\u0006היא \u0005אוכלת]\u0006 שחיוב מזונותיה הוא חלק בלתי נפרד מתנאי הכתובה — \u0003לא מהני\u0004 \u0005[מועיל]\u0006 \u0003לה קנין,\u0004 כיון שזכותה נובעת ממקור אחר, מתנאי בית דין. \u0003בת אשתו דלאו\u0004 \u0005[שלא]\u0006 \u0003בתנאי בית דין קאכלה\u0004 \u0005[\u0006היא \u0005אוכלת],\u0006 אלא מכוח ההסכם — \u0003מהני\u0004 \u0005[מועיל]\u0006 \u0003לה קנין.\u0004","ושואלים על כך: \u0003וכי מיגרע גרעה\u0004 \u0005[גרועה]\u0006 היא יותר בת זו שיש גם תנאי בית דין לטובתה?! ומדוע לא יועיל לה הקנין לגבות מנכסים משועבדים למזונותיה? \u0003אלא\u0004 זהו ההבדל שביניהן: \u0003בתו כיון\u0004 ש\u0003בתנאי בית דין קאכלה\u0004 \u0005[\u0006היא \u0005אוכלת],\u0006 \u0003אימר צררי אתפסה\u0004 \u0005[אמור\u0006 שמא \u0005כספים\u0006 בעין \u0005נתן לה]\u0006 עוד בחייו לצורך מזונותיה, וכיון שיש ספק בדבר — אין אנו מוציאים לה מנכסים משועבדים, ואף שעשו קנין על הדבר. אבל בבתו החורגת אין חוששים כלל שנתן לה כספים בחייו, והואיל ועשו קנין על הדבר — ניזונת מנכסים משועבדים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר ר' נתן: אימתי\u0004 אמרו שאין הקונה שדה מגזלן והוחזרה לנגזל גובה שבח שהשביחה השדה אצלו מנכסים משועבדים של הגזלן — \u0003בזמן שקדם מקחו\u0004 (קניינו) \u0003של\u0004 הקונה ה\u0003שני\u0004, האחר, מן הגזלן, \u0003לשבחו של\u0004 הקונה ה\u0003ראשון\u0004 מהגזלן.","\u0003אבל\u0004 אם \u0003קדם שבחו של ראשון למקחו של שני\u0004 — \u0003גובה\u0004 את השבח \u0003מנכסים משועבדים. אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 שהטעם שאינו גובה שבח \u0003משום\u0004 ש\u0003לא\u0004 \u0003קדים\u0004 \u0005[קדם]\u0006 למכירת השדה האחרת \u0003הוא,\u0004 ולא משום שאין השבח קצוב או שאינו כתוב בשטר!","ומשיבים: אין להקשות על שיטה זו או אחרת מן הברייתות, כי בעיה זו עצמה \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מוציאין לאכילת פירות ולשבח קרקעות ולמזון אשה והבנות מנכסים משועבדים, מפני תיקון העולם, לפי שאין כתובין.\u0004","\u0003אמר ר' יוסי: וכי מה תיקון העולם יש בזו\u0004 אם כתובים או אינם כתובים? \u0003והלא\u0004 הטעם האמיתי הוא ש\u0003אין קצובין!\u0004 הרי שבעיה זו כבר נשנתה כמחלוקת תנאים.","שנינו במשנה: \u0003והמוצא מציאה לא ישבע\u0004 מפני תיקון העולם. \u0003אמר ר' יצחק:\u0004 אם בעל האבידה טוען למוצא: \u0003שני כיסין\u0004 (ארנקים) \u0003קשורין\u0004 זה בזה \u0003מצאת לי\u0004 (משלי), \u0003והלה אומר: לא מצאתי אלא אחד\u0004 — הרי המוצא \u0003נשבע,\u0004 ככל מודה במקצת. ואם טוען: \u0003שני שוורים קשורין מצאת לי, והלה אומר: לא היה אלא אחד — אינו\u0004 \u0003נשבע. \u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בדין? — \u0003שוורין מנתחי מהדדי\u0004 \u0005[מתנתקים זה מזה],\u0006 וייתכן שאמנם כשאבדו היו שניהם קשורים זה לזה, אך לאחר מכן נפרדו זה מזה, והוא מצא רק אחד מהם, \u0003כיסין לא מנתחי מהדדי\u0004 \u0005[אינם מתנתקים זה מזה],\u0006 וכיון שהוא מודה שאחד מהם מצא, מסתבר שאת שניהם מצא.","ועוד אמר ר' יצחק, אם אמר למוצא: \u0003שני שוורין קשורין מצאת, והלה אומר: מצאתי והחזרתי לך אחד מהן — הרי זה נשבע.\u0004","ויש לשאול על הלכות אלה של ר' יצחק: \u0003ו\u0004כי \u0003ר' יצחק לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 הלכה זו שבמשנתנו ש\u0003המוצא מציאה לא ישבע מפני תיקון העולם?\u0004"],["ומשיבים: \u0003הוא\u0004 ר' יצחק, \u0003דאמר\u0004 \u0005[שאומר,\u0006 סבור\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר בן יעקב. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: פעמים שאדם נשבע על טענת עצמו, כיצד?\u0004 — אומר אדם לחבירו: \u0003מנה לאביך\u0004 שמת \u0003בידי\u0004 שהייתי חייב לו, \u0003והאכלתיו פרס\u0004 (חצי ממנו) ועדיין אני חייב לך חצי מנה — \u0003הרי זה נשבע\u0004 שפרע מחצית, כדרך שנשבע כל מודה במקצת הטענה, \u0003וזה הוא\u0004 המקרה \u0003שנשבע\u0004 אדם \u0003על טענת עצמו,\u0004 שאף על פי שאחר לא תבע ממנו — הוא נשבע על סמך מה שאמר בעצמו.","\u0003וחכמים אומרים: אינו אלא כמשיב אבידה, ופטור.\u0004 וכעין שיטת ר' אליעזר בן יעקב כך שיטת ר' יצחק, שכיון שאמר שמצא רק מחצית — הרי זה כמודה במקצת.","ושואלים: \u0003ו\u0004כי \u0003ר' אליעזר בן יעקב לית ליה\u0004 \u0005[אין לו]\u0006 סברה זו ש\u0003משיב אבידה פטור? אמר רב:\u0004 כאן מדובר לא במקרה שהאיש בא והודה מעצמו, אלא \u0003בטוענו קטן.\u0004 שהיה זה בן קטן של המת שתבעו, ואמר שהוא יודע שהלה חייב ממון לאביו, והנתבע הודה במקצתה של טענה זו, ואם כן, יש פה כפירה במקצת הטענה.","ותוהים: וכי \u0003קטן מידי מששא אית ביה\u0004 \u0005[כלום ממש יש בו],\u0006 בטענתו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין נשבעין על טענת חרש, שוטה וקטן,\u0004 שאין מתחשבים כלל בטענה של מי שאינו בר דעת! ולפי זה אם טוענו קטן הרי זה כאילו לא היתה טענה כלל, אלא הודאה מפי עצמו בלבד!","ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קטן\"\u0004 שאמר רב — \u0003גדול, ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"קטן\"?\u0004 ש\u0003לגבי מילי\u0004 \u0005[דברים]\u0006 של \u0003אביו, קטן הוא,\u0004 שאינו יודע בוודאות, ואומר: אני סבור שאתה חייב לאבי יותר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, כיצד אומר ר' אליעזר בן יעקב ש\"אדם נשבע על טענת עצמו\"? וכי \u0003טענת עצמו\u0004 היא? הלא \u0003טענת אחרים הוא!\u0004 ומשיבים: אמנם \u0003טענת אחרים,\u0004 ואולם \u0003הודאת עצמו.\u0004","על כך תוהים: \u0003כולהו טענתא נמי\u0004 \u0005[כל הטענות גם כן]\u0006 של מודה במקצת \u0003טענת אחרים והודאת עצמו נינהו\u0004 \u0005[הן]!\u0006 \u0003אלא\u0004 ר' אליעזר בן יעקב וחכמים \u0003בד\u0004ברי \u0003רבה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ש\u0003אמר רבה: מפני מה אמרה תורה\u0004 ש\u0003מודה\u0004 ב\u0003מקצת הטענה\u0004 — \u0003ישבע,\u0004 ואילו זה הכופר בכל — לא ישבע? — הטעם הוא שעומדים על דעתו של אדם; \u0003חזקה, אין אדם מעיז פניו בפני בעל חובו\u0004 לכפור ולהכחיש הכל כאשר בעל החוב יודע שהוא משקר.","\u0003והאי\u0004 \u0005[וזה]\u0006 המודה במקצת, \u0003בכוליה בעי למכפריה ליה\u0004 \u0005[בכל היה רוצה לכפור לו],\u0006 \u0003והאי דלא כפריה\u0004 \u0005[וזה שלא כפר לו\u0006 בכל\u0005]\u0006 — \u0003משום\u0004 ש\u0003אין אדם מעיז פניו בפני בעל חובו,\u0004 \u0003ו\u0004בעצם \u0003בכוליה בעי דלודי ליה\u0004 \u0005[בכל היה רוצה להודות לו],\u0006 \u0003והאי דלא אודי ליה\u0004 \u0005[וזה שלא הודה לו]\u0006 ולא אמר שהוא באמת חייב הכל — \u0003אישתמוטי הוא דקא משתמיט ליה\u0004 \u0005[משתמט הוא לו],\u0006 \u0003סבר\u0004 \u0005[חושב\u0006 הוא\u0005]:\u0006 \u0003עד דהוו\u0004 \u0005[שיהיו]\u0006 \u0003לי זוזי ופרענא ליה\u0004 \u0005[מעות ואפרע לו]\u0006 את השאר שלא הודיתי עליו, \u0003ו\u0004על כן \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003רמי שבועה עילויה כי היכי דלודי ליה בכוליה\u0004 \u0005[הטל שבועה עליו כדי שיודה לו בכל].\u0006","ובהשלכה המעשית של דבר זה למקרה שהבן תובע חוב של אביו נחלקו; \u0003ר' אליעזר בן יעקב סבר: לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בו\u0004 עצמו, במלווה, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003בבנו\u0004 של המלווה — \u0003אינו מעיז\u0004 הלווה פניו, \u0003והילכך\u0004 (ומשום כך) \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משיב אבידה הוא\u0004 משום שאנו אומרים שבעצם היה רוצה לכפור הכל, אלא מכיון שאינו יכול להעיז פנים כופר רק במקצת, ולכן צריך להישבע. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003בו הוא\u0004 ש\u0003אינו מעיז,\u0004 \u0003אבל בבנו\u0004 הריהו \u0003מעיז, ומ\u0004ש\u0003לא מעיז\u0004 ולא כפר הכל, הרי כ\u0003משיב אבידה הוא,\u0004 ואין להשביעו."],["\u0003יתומין שסמכו,\u0004 שנמצאו \u0003אצל בעל הבית,\u0004 והוא מטפל בצרכיהם ובעסקיהם, אף על פי שלא היה לו מינוי רשמי לכך, לא מאביהם ולא מבית דין, \u0003או שמינה להן אביהן אפוטרופוס\u0004 — \u0003חייב\u0004 אותו אדם \u0003לעשר פירותיהם.\u0004","\u0003אפוטרופוס שמינהו אבי יתומים\u0004 להיות אפוטרופוס לבניו אחר מותו, כשהוא מחזיר את כל הנכסים ליתומים כאשר הם גדלים — \u0003ישבע\u0004 שלא נטל לעצמו משלהם כלום. אבל אם \u0003מינוהו בית דין\u0004 להיות להם אפוטרופוס — \u0003לא ישבע.\u0004 \u0003אבא שאול אומר: חילוף הדברים,\u0004 שאפוטרופוס שמינוהו בית דין — הוא שישבע, ולא זה שמינהו אבי יתומים.","על מה שאמרו במשנה שהאפוטרופוס חייב לעשר את פירותיהם של היתומים, \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005],\u0006 ממה ששנינו, נאמר: \"כן תרימו גם אתם תרומת ה'\" (במדבר יח, כח), ומן ההדגשה \"אתם\" למדו בברייתא: \u0003\"אתם\"\u0004 — \u0003ולא שותפין,\u0004 שאין שותף יכול לתרום עבור שותפו, \u0003\"אתם\"\u0004 — \u0003ולא אריסין, \"אתם\" — ולא אפוטרופין,\u0004 \"אתם\" — \u0003ולא התורם את שאינו שלו.\u0004 וכיצד אמרו במשנה שאפוטרופוס יכול לעשר את פירותיהם של היתומים, הרי אין הפירות שלו!","\u0003אמר רב חסדא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 במשנתנו מדובר שהאפוטרופוס מעשר כדי \u0003להאכיל\u0004 את היתומים מפירות אלה, שכיון שאינו רשאי להאכיל אותם טבל, התירו לו לעשר מה שהוא נותן להם לאכול. \u0003כאן\u0004 בברייתא מדובר שאינו צריך את התבואה למזונם אלא רק כדי \u0003להניח\u0004 את הפירות המעושרים במקומם, ומכיון שאינו בעל התבואה אין לו רשות לעשר.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]\u0006 המבחינה גם היא בין פעולות האפוטרופוס הנעשות לצורך אכילה לבין אלה הנעשות לצורך הנחה: \u0003האפוטרופין תורמין\u0004 (מפרישים תרומה) \u0003ומעשרין\u0004 בנכסי היתומים, \u0003להאכיל ולא להניח. ומוכרין להן\u0004 (עבורם) \u0003בהמה, עבדים ושפחות, בתים, שדות וכרמים\u0004 שבבעלות היתומים, כל זה כדי \u0003להאכיל,\u0004 כלומר, כדי שיהיה ליתומים מייד מה לאכול, \u0003אבל לא להניח\u0004 את דמיהם. \u0003ומוכרין להן\u0004 גם \u0003פירות, יינות, שמנים וסלתות, להאכיל אבל לא להניח.\u0004","\u0003ועושין להן,\u0004 ליתומים, מנכסי היתומים, צרכי מצוה; \u0003לולב וערבה וסוכה וציצית, וכל דבר\u0004 מצוה \u0003שיש לו קצבה,\u0004 כלומר, כל מצוה שיש לה סכום קצוב. ומעירים שהכוונה בכלל זה (\"כל דבר\") היא \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003שופר\u0004 שעושים להם לתקוע בו. \u0003ולוקחין\u0004 (קונים) \u0003להם ספר תורה, תפילין ומזוזות, וכל דבר שיש לו קצבה.\u0004 ומעירים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003מגילה\u0004 (מגילת אסתר).","\u0003ו\u0004אולם \u0003אין פוסקין עליהם,\u0004 כלומר, אין מתחייבים בשבילם \u0003צדקה, ואין פודין עליהן\u0004 (בשבילם, ומכספם) \u0003את השבויין, ולא\u0004 נותנים מנכסיהם \u0003כל דבר שאין לו קצבה,\u0004 ומעירים: כלל זה (\"כל דבר\") בא \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 מה שמביאים בזמן \u0003תנחומי אבלים,\u0004 שאף בזה אין האפוטרופסים מוציאים מכספי היתומים.","\u0003ואין אפוטרופין רשאין לדון\u0004 (לבוא לדין) על מנת \u0003לחוב ולזכות בנכסי יתומים.\u0004 ושואלים: \u0003לזכות אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 ומשיבים: \u0003אלא, לחוב על מנת לזכות בנכסי יתומים.\u0004 כלומר, אסור להם להיכנס לדיון שבו מתחייבים היתומים אף על פי שהם חושבים שעל ידי כך עשוי לצאת ליתומים רווח יותר גדול מצד אחר.","\u0003ואין אפוטרופין רשאין למכור\u0004 שדה שהיא \u0003ב\u0004מקום \u0003רחוק ולגאול\u0004 בתמורתה קרקע של אביהם שנמכרה \u0003ב\u0004מקום \u0003קרוב\u0004 יותר, אף על פי שהוא כרגיל רווח, שיש לאדם שדות קרובות זו לזו, וכן אסור להם למכור \u0003ב\u0004שדה \u0003רעה ו\u0004במקומה \u0003לגאול ביפה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דדלמא משתדפין\u0004 \u0005[שמא ישתדפו,\u0006 יתקלקלו\u0005]\u0006 השדות שהם קונים, ונמצא שהפסידו ליתומים במה שקנו להם, ואין להם רשות לכך.","\u0003ואין אפוטרופין רשאין למכור שדות\u0004 של יתומים \u0003וליקח\u0004 (לקנות) בכסף המכירה \u0003עבדים, אבל מוכרין עבדים ולוקחין בהן שדות,\u0004 שזהו רכוש יציב יותר. \u0003רבן שמעון בן גמליאל אומר: אף לא למכור עבדים וליקח שדות.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דלמא לא משפיין\u0004 \u0005[שמא אינן בריאות],\u0006 כלומר, שמא קשורות בשדות הללו בעיות משפטיות, ונמצא שהאפוטרופסים מסבכים את היתומים.","\u0003ואין אפוטרופין רשאין להוציא עבדים לחירות\u0004 גם אם צריך מאיזה טעם לעשות זאת, \u0003אבל מוכרין אותן לאחרים, ואחרים מוציאין אותן לחירות.\u0004 \u0003רבי אומר, אומר אני: אף הוא,\u0004 העבד, \u0003נותן דמי עצמו ויוצא,\u0004 \u0003מפני שהוא,\u0004 האפוטרופוס, \u0003כמוכרו לו\u0004 את העבד לעצמו. אם כן, אין הבדל אם אדם אחר, או שהעבד עצמו משלם את מחירו.","\u0003וצריך\u0004 האפוטרופוס \u0003לחשב עמהן,\u0004 עם היתומים \u0003באחרונה,\u0004 שכאשר יגדלו ויחזיר להם את נכסיהם, צריך לעשות איתם חשבון של הוצאות והכנסות של הנכסים הללו במשך הזמן בו שימש כאפוטרופוס להם. \u0003רבן שמעון בן גמליאל אומר: אינו צריך,\u0004 אלא אנו סומכים על יושרו. \u0003אין עושין אפוטרופין נשים ועבדים וקטנים, ואם מינן אבי יתומין\u0004 דווקא לאלה — \u0003הרשות בידו.\u0004","מסופר: \u0003ההוא אפוטרופוס דהוה בשבבותיה\u0004 \u0005[אפוטרופוס אחד\u0006 של יתומים \u0005שהיה בשכנותו]\u0006 של \u0003ר' מאיר, דהוה קא מזבין ארעתא וזבין עבדי\u0004 \u0005[שהיה מוכר קרקעות וקונה עבדים],\u0006 \u0003ולא שבקיה\u0004 \u0005[הניחו]\u0006 \u0003ר' מאיר\u0004 לעשות זאת, שהרי אינו כדין. \u0003אחוו ליה בחלמיה\u0004 \u0005[הראו לו בחלומו]\u0006 \u0003\"אני להרוס ואתה לבנות\"\u0004 (ראה מלאכי א, ד)?! שמשמים רוצים שהנכסים הללו יתמוטטו, ואם כן, מוטב לו שיניח להם לנהוג כך. \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא אשגח\u0004 \u0005[השגיח]\u0006 בחלום, \u0003אמר: דברי חלומות לא מעלין ולא מורידין,\u0004 ואין שמים לב לזה.","כיון שסיפרנו על ר' מאיר, מסופר עליו עוד: \u0003הנהו בי תרי דאיגרי בהו\u0004 \u0005[היו שניים שהיה מתגרה בהם]\u0006 ה\u0003שטן,\u0004 ש\u0003כל בי שמשי\u0004 \u0005[בין השמשות]\u0006 של ערב שבת \u0003הוו קא מינצו בהדי הדדי\u0004 \u0005[היו מתקוטטים זה עם זה].\u0006 \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ר' מאיר להתם\u0004 \u0005[לשם],\u0006 לאותו מקום, \u0003עכבינהו תלתא בי שמשי\u0004 \u0005[עיכב אותם שלושה בין השמשות\u0006 של לילי שבת\u0005]\u0006 שלא יריבו \u0003עד דעבד להו שלמא\u0004 \u0005[שעשה ביניהם שלום].\u0006 \u0003שמעיה דקאמר\u0004 \u0005[שמע אותו\u0006 את השטן \u0005שאומר]:\u0006 \u0003ווי, דאפקיה\u0004 \u0005[אוי, שהוציאו]\u0006 \u0003ר' מאיר לההוא גברא מביתיה\u0004 \u0005[את האיש הזה,\u0006 כלומר את השטן, \u0005מביתו]\u0006 שהיה גר שם על ידי הקטטה.","מסופר: \u0003ההוא אפוטרופוס דהוה בשבבותיה\u0004 \u0005[אפוטרופוס אחד\u0006 של יתומים \u0005שהיה בשכנותו]\u0006 של \u0003ר' יהושע בן לוי, דהוה קא מזבין ארעא וזבין תורי\u0004 \u0005[שהיה מוכר קרקע וקונה שוורים]\u0006 עבור היתומים, \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]\u0006 על כך, שאין הוא נוהג כראוי. ומסבירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 ר' יהושע בן לוי \u0003כ\u0004דעת \u0003ר' יוסי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: מימי לא קריתי\u0004 (קראתי) \u0003לאשתי \"אשתי\" ולשורי \"שורי\", אלא לאשתי\u0004 קראתי \u0003\"ביתי\",\u0004 שהיא עקרת הבית, ולשורי קראתי \u0003\"שדי\",\u0004 שסבר שעיקר הטבת השדה היא על ידי השור החורש בו. וכמו כן סבר ר' יהושע בן לוי שהקונה שוורים לעבודה, הרי זה כקונה קרקעות ולכן אין למחות באותו אפוטרופוס שמכר שדות יתומים וקנה שוורים.","מסופר: \u0003הנהו יתמי דהוו סמיכי גבי ההיא סבתא\u0004 \u0005[היו יתומים שהיו סמוכים,\u0006 נמצאים ומושגחים \u0005אצל זקנה\u0006 אחת\u0005],\u0006 \u0003הוה להו תורתא\u0004 \u0005[היתה להם פרה],\u0006 \u0003שקלה וזבינתה ניהלייהו\u0004 \u0005[לקחה ומכרה אותה להם,\u0006 עבורם\u0005].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003קרובים\u0004 של אותם יתומים \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, אמרו ליה\u0004 \u0005[לו]\u0006 הקרובים: \u0003מאי עבידתה דזבנא\u0004 \u0005[מה מעשיה\u0006 שהיא \u0005מכרה]?\u0006 מה רשותה למכור את הנכסים של היתומים? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"יתומים שסמכו אצל בעל הבית\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 ואין צורך שיהיה מינוי רשמי לאפוטרופוס, אלא כיון שהם חיים אצלה והיא מטפלת בהם, די בכך.","ואמרו לו הקרובים: \u0003והא אייקר\u0004 \u0005[והרי התייקר]\u0006 אחר כך הבשר, והם לא נהנו מכך! והשיב להם: \u0003ברשותא\u0004 \u0005[ברשות]\u0006 ה\u0003לוקח אייקר\u0004 \u0005[התייקר\u0006 הבשר\u0005]\u0006 ואין זה הפסד. אמרו לו: \u0003והא\u0004 \u0005[והרי]\u0006 עדיין \u0003לא נקיטי דמי\u0004 \u0005[קיבלו כסף]\u0006 ואם כן, לא היתה זו מכירה גמורה!","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אם כן\u0004 עשתה, \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב חנילאי בר אידי אמר שמואל,\u0004 ש\u0003אמר\u0004 \u0003רב חנילאי בר אידי אמר שמואל:\u0004 \u0003נכסי יתומין הרי הן כהקדש, ולא מקני\u0004 \u0005[נקנים]\u0006 \u0003אלא בכספא\u0004 \u0005[בכסף],\u0006 ולכן, כיון שלא קיבלו כסף יכולים הם לדרוש את הסכום הגבוה, או לחזור בהם.","ומסופר כעין זה: \u0003חמריה\u0004 \u0005[יינו]\u0006 של \u0003רבנא עוקבא יתמא\u0004 \u0005[היתום]\u0006 \u0003משכוה\u0004 \u0005[משכוהו]\u0006 הקונים את היין לקנותו \u0003ב\u0004מחיר של \u0003ארבעה ארבעה\u0004 דינרים לכל חבית, \u0003ו\u0004לפני ששילמו עבור היין \u0003אייקר\u0004 \u0005[התייקר]\u0006 \u0003וקם בשיתא שיתא\u0004 \u0005[ועמד בשישה שישה],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב נחמן\u0004 לדין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב חנילאי בר אידי,\u0004 ש\u0003אמר\u0004 \u0003רב חנילאי בר אידי אמר שמואל: נכסי יתומין הרי הן כהקדש, ולא מקני\u0004 \u0005[נקנים]\u0006 \u0003אלא בכספא\u0004 \u0005[בכסף],\u0006 ולכן ישלמו לו כמחיר הגבוה של עכשיו, או שייבטל המיקח.","וכמה דינים בנושא זה: \u0003משוך פירי מיתמי\u0004 \u0005[\u0006אם \u0005משכו\u0006 הקונים \u0005פירות מן היתומים]\u0006 ואחר כך \u0003אייקור\u0004 \u0005[התייקרו]\u0006 הפירות — \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב חנילאי בר אידי\u0004 שאין קונים מן היתומים אלא בכסף, וזכותם של היתומים לחזור בהם מן המיקח שנעשה. אם \u0003זול\u0004 \u0005[הוזלו]\u0006 הפירות אחר כך והקונים רוצים לחזור בהם, אומרים אנו: כשם שאמרו \u0003לא יהא כח הדיוט חמור מהקדש,\u0004 כך אין כוח יתומים גרוע משל אדם אחר, וכיון שהיתה משיכה — הקנין קיים.","\u0003אמשיכו להו פירי ליתמי\u0004 \u0005[משכו להם\u0006 האפוטרופסים \u0005פירות ליתומים],\u0006 אם \u0003אייקר\u0004 \u0005[התייקר]\u0006 אחר כך מחיר הפירות — \u0003לא יהא כח הדיוט חמור מהקדש,\u0004 שזכו בהם היתומים ומחירם כשעת המשיכה. אם \u0003זול\u0004 \u0005[הוזלו]\u0006 הפירות — \u0003סבור מינה\u0004 \u0005[חשבו\u0006 הלומדים לומר \u0005ממנה]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב חנילאי בר אידי,\u0004 שאין קניינם אלא בכסף, וייבטל המיקח, ויקנו בשער הזול.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: הא\u0004 \u0005[זו]\u0006 \u0003רעה היא לדידהו\u0004 \u0005[להם]\u0006 אם ינהגו בהם כך, \u0003דזמנין דמצטרכי לפירי\u0004 \u0005[שפעמים ש\u0006היתומים \u0005יצטרכו לפירות],\u0006 \u0003וליכא דיהיב להו עד דיהבי זוזי\u0004 \u0005[ולא\u0006 יהיה מי \u0005שיתן להם עד שיתנו כסף]\u0006 מזומן, ולכן מוטב להם שבזמן שהם מושכים פירות שינהגו בהם כדרך קונים אחרים.","אם \u0003יהבי יתמי זוזי אפירי\u0004 \u0005[נתנו יתומים כסף\u0006 עבור \u0005פירות],\u0006 אם \u0003זול\u0004 \u0005[הוזלו]\u0006 אחר כך הפירות — \u0003לא יהא כח הדיוט,\u0004 המוכר, \u0003חמור מן הקדש,\u0004 ולכן יכולים היתומים לחזור בהם, הואיל ועדיין לא היתה כאן משיכה. אם \u0003אייקר\u0004 \u0005[התייקרו]\u0006 הפירות — \u0003סבור מינה\u0004 \u0005[חשבו\u0006 לומר \u0005ממנה]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב חנילאי בר אידי,\u0004 שהיתומים קונים בכסף, ומשלמים כאותה שעה ששילמו, בסכום הנמוך.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: הא\u0004 \u0005[זו]\u0006 \u0003רעה היא לדידהו\u0004 \u0005[עבורם]\u0006 עבור היתומים,"],["\u0003דאתו למימר להו\u0004 \u0005[שיבואו\u0006 המוכרים \u0005לומר להם]:\u0006 \u0003נשרפו חיטכם בעלייה,\u0004 שאם תארע שריפה לא ישתדלו המוכרים להציל את התבואה, שהרי כבר קיבלו את הכסף עבורה והיא מעתה קניינם של היתומים.","\u0003יהבי להו זוזי ליתמי אפירי\u0004 \u0005[נתנו להם\u0006 הקונים \u0005כסף ליתומים עבור פירות],\u0006 אם \u0003אייקר\u0004 \u0005[התייקרו]\u0006 הפירות — \u0003לא יהא כח הדיוט חמור מהקדש\u0004 ויכולים היתומים לחזור בהם, כיון שלא היתה משיכה, אם \u0003זול\u0004 \u0005[הוזלו]\u0006 הפירות — \u0003סבור מינה\u0004 \u0005[סברו,\u0006 רצו לומר\u0005]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב חנילאי בר אידי\u0004 שקנין היתומים בכסף, ואין הקונים יכולים לחזור בהם.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: הא\u0004 \u0005[זו]\u0006 \u0003רעה הוא לדידהו\u0004 \u0005[בשבילם],\u0006 \u0003דזמנין דמצטרכי לזוזי, וליכא דיהיב להו עד דיהבי להו פירי\u0004 \u0005[שפעמים ש\u0006הם \u0005צריכים לכסף ואין,\u0006 לא יהיה, מי \u0005שייתן להם עד שיתנו להם\u0006 בפועל \u0005פירות].\u0006","\u0003אמר רב אשי: אנא\u0004 \u0005[אני]\u0006 \u0003ורב כהנא חתמינן אשטרא דאימיה\u0004 \u0005[חתמנו על שטר של אימו]\u0006 של \u0003זעירא יתמא\u0004 \u0005[היתום],\u0006 שהיתה אפוטרופוס שלו, \u0003דמזבנא ארעא\u0004 \u0005[שמכרה קרקע]\u0006 \u0003ל\u0004צורך תשלום \u0003כרגא\u0004 (מס הקרקע) \u0003בלא\u0004 שקדמה לכך \u0003אכרזתא\u0004 \u0005[הכרזה].\u0006 והותר לה לעשות כן, משום \u0003דאמרי נהרדעי\u0004 \u0005[ש\u0006כך \u0005אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003לכרגא,\u0004 \u0003ולמזוני\u0004 \u0005[ולמזונות]\u0006 שמפרנסים את הבנים מנכסי המת, \u0003ולקבורה\u0004 של המת — \u0003מזבנינן\u0004 \u0005[מוכרים אנו]\u0006 את נכסי היתומים \u0003בלא אכרזתא\u0004 \u0005[הכרזה].\u0006 כי כרגיל נכסי יתומים נמכרים רק אחרי הכרזה פומבית מראש, כדי לקבל את המחיר הגבוה ביותר, ואילו כאן, שיש צורך דחוף במזומנים, התירו למכור אף בלא הכרזה.","מסופר: \u0003עמרם צבעא\u0004 \u0005[הצבע]\u0006 \u0003אפוטרופא דיתמי הוה\u0004 \u0005[אפוטרופוס של יתומים היה],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 ה\u0003קרובים\u0004 של היתומים \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003קא לביש ומכסי מיתמי\u0004 \u0005[הריהו לובש ומתכסה מ\u0006נכסי \u0005היתומים]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 שמא הוא עושה זאת \u0003כי היכי דלישתמען מיליה\u0004 \u0005[כדי שיישמעו דבריו]\u0006 שמתלבש יפה על חשבונם משום שהוא צריך לטפל בנכסיהם, ואם ייראה כאדם עני לא ישימו לב אליו.","אמרו לו: \u0003קאכיל ושתי מדידהו, ולא אמוד\u0004 \u0005[הריהו אוכל ושותה משלהם ואינו עשיר\u0006 מספיק\u0005]\u0006 שיכול להוציא סכומים כאלה משל עצמו! אמר להם: \u0003אימור\u0004 \u0005[אמור]\u0006 אולי \u0003מציאה אשכח\u0004 \u0005[מצא],\u0006 ומשום כך יכול להרשות לעצמו לחיות ברווחה. אמרו לו: \u0003והא קא\u0004 \u0005[והרי הוא]\u0006 \u0003מפסיד,\u0004 שגורם הפסדים לנכסי היתומים! \u0003אמר להו\u0004 \u0005[להם]\u0006 רב נחמן: \u0003אייתו\u0004 \u0005[הביאו]\u0006 \u0003לי סהדי\u0004 \u0005[עדים]\u0006 שהוא \u0003מפסיד ואיסלקיניה\u0004 \u0005[ואסלק אותו]\u0006 מאפוטרופסותו, שכך \u0003אמר רב הונא חברין\u0004 \u0005[חברנו]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אפוטרופוס\u0004 ש\u0003מפסיד\u0004 את נכסי היתומים \u0003מסלקינן ליה\u0004 \u0005[מסלקים אנו אותו].\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003אפוטרופא\u0004 \u0005[אפוטרופוס]\u0006 ש\u0003מפסיד,\u0004 \u0003רב הונא אמר\u0004 בשם \u0003רב: מסלקינן ליה\u0004 \u0005[מסלקים אנו אותו],\u0006 \u0003דבי\u0004 \u0005[\u0006החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא מסלקינן ליה\u0004 \u0005[אין אנו מסלקים אותו].\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003מסלקינן ליה\u0004 \u0005[מסלקים אנו אותו].\u0006","שנינו במשנה ש\u0003אפוטרופוס שמינהו אבי יתומים\u0004 — \u0003ישבע.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003אי לאו דאית ליה\u0004 \u0005[אם לא שהיתה לו],\u0006 לאפוטרופוס, \u0003הנאה מיניה\u0004 \u0005[ממנו],\u0006 מאביהם בחייו \u0003לא הוה ליה\u0004 \u0005[היה נעשה]\u0006 \u0003אפוטרופוס\u0004 לבניו, \u0003ומשום\u0004 חובת \u0003שבועה\u0004 שיטילו עליו בית דין בעתיד \u0003לא אתי לאמנועי\u0004 \u0005[יבוא להימנע]\u0006 מלהיות אפוטרופוס.","עוד שנינו במשנה: \u0003מינוהו בית דין\u0004 — \u0003לא ישבע.\u0004 וטעמו של דבר: \u0003מלתא בעלמא\u0004 \u0005[דבר,\u0006 טובה, \u0005בלבד]\u0006 \u0003הוא דעביד לבי דינא\u0004 \u0005[שעושה לבית הדין],\u0006 \u0003ואי רמית עליה\u0004 \u0005[ואם תטיל עליו]\u0006 גם חובת \u0003שבועה אתי לאמנועי\u0004 \u0005[יבוא להימנע]\u0006 מלהיות אפוטרופוס ואיש לא ירצה בזה, ונמצאים היתומים ניזוקים.","עוד שנינו במשנה: \u0003אבא שאול אומר: חילוף הדברים.\u0004 ומבררים את דעתו: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שאם \u0003מינוהו בית דין\u0004 — \u0003ישבע?\u0004 — \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה\u0004 שיש לו \u0003דקא נפיק עליה קלא דאיניש מהימנא\u0004 \u0005[\u0006\u0005שיוצא עליו קול,\u0006 שם, \u0005שאדם נאמן]\u0006 \u0003הוא,\u0004 \u0003דהא סמיך עליה בי דינא\u0004 \u0005[שהרי סומך עליו בית הדין]\u0006 ומינה אותו לתפקיד שיש בו אחריות, לכן \u0003משום שבועה\u0004 שמטילים עליו \u0003לא אתי לאמנועי\u0004 \u0005[יבוא להימנע]\u0006 מלקבל את האפוטרופסות.","ולעומת זאת, אם \u0003מינהו אבי יתומים\u0004 — \u0003לא ישבע,\u0004 ומדוע? — \u0003מילתא בעלמא הוא דעבדי להדדי\u0004 \u0005[דבר\u0006 של טובה בלבד \u0005הוא שעושים\u0006 האנשים \u0005זה לזה],\u0006 \u0003ואי רמית עליה\u0004 \u0005[ואם תטיל עליו]\u0006 \u0003שבועה אתי לאמנועי\u0004 \u0005[יבוא להימנע]\u0006 מלקבל עליו את האפוטרופסות. \u0003אמר רב חנן בר אמי אמר שמואל: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כאבא שאול.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: זה וזה ישבע,\u0004 כלומר, גם אפוטרופוס שמינוהו בית דין וגם זה שמינהו האב ישבעו, \u0003והלכה כדבריו.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא בר מערבא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו: אפוטרופוס שמינהו אבי יתומים\u0004 — \u0003ישבע, מפני שהוא נושא שכר,\u0004 מפני שתוך כדי התעסקותו בנכסיהם, יש לו רווח מסויים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את אייתת קבא וכיילת ליה\u0004 \u0005[אתה הבאת קב\u0006 של מידה \u0005ומדדת אותו]\u0006 כמה הרוויח בכך? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מפני שהוא כנושא שכר,\u0004 שמן הסתם עושה זאת בגלל הנאה שנהנה מאביהם בעבר, ונמצא שהיה לו שכר על אפוטרופסותו, ולכן צריך להישבע.","\u0003המטמא\u0004 טהרות של חבירו, \u0003והמדמע,\u0004 שמערב תרומה בחולין של חבירו, \u0003והמנסך\u0004 יין של חבירו לעבודה זרה, ובכל אלה, על ידי מעשיו גרם נזק כספי לחבירו, אם עשה זאת \u0003בשוגג\u0004 — \u0003פטור\u0004 מלשלם את מה שהזיק, ואם עשה זאת \u0003במזיד\u0004 — \u0003חייב\u0004 לשלם.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בפירוש \u0003\"מנסך\"\u0004 האמור במשנתנו, \u0003רב אמר: מנסך ממש,\u0004 כלומר, לוקח מן היין ומנסך ממנו לעבודה זרה, \u0003ושמואל אמר:\u0004 הכוונה היא \u0003מערב,\u0004 כלומר, מערב יין נסך ביין כשר, ועל ידי כך אוסר את כל היין בהנאה.","ושואלים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מערב, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מנסך\u0004 ממש? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003מנסך קם ליה בדרבה מיניה\u0004 \u0005[עומד לו ב\u0006עונש \u0005גדול ממנו],\u0006 שהרי הוא עובד עבודה זרה, שהיא עבירה שחייבים עליה מיתה, ולכן אינו נענש גם בעונש ממון.","\u0003ואידך\u0004 \u0005[והאחר],\u0006 רב, סבור \u0003כ\u0004דברי \u0003ר' ירמיה,\u0004 ש\u0003אמר ר' ירמיה:\u0004 כאשר אדם מנסך יין של חבירו, \u0003משעת הגבהה\u0004 שהגביה את היין כדי לקחת אותו לעצמו \u0003הוא\u0004 הזמן ש\u0003קנה\u0004 אותו להיות כנכסיו, והתחייב אז בעונש הממון, אבל \u0003מתחייב בנפשו\u0004 משום עבודה זרה \u0003לא הוי\u0004 \u0005[איננו]\u0006 \u0003עד שעת ניסוך\u0004 ממש, נמצא שתחילה חל עליו כבר חיוב ממון, ואינו פוקע ממנו אחר כך כאשר התחייב מיתה.","ושואלים: \u0003למאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003מנסך\u0004 ממש, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מערב?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: מערב\u0004"],["\u0003היינו\u0004 \u0005[זהו]\u0006 דינו של \u0003מדמע\u0004 הגורם איסור על ידי תערובת, ששנינו במשנה, ואין ביניהם הבדל.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 שמואל\u0005]\u0006 סבור שכיון שחיובו של המדמע \u0003קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא\u0004 מדברי חכמים, ולא מעיקר הדין, \u0003ומקנסא לא ילפינן\u0004 \u0005[ומקנס אין אנו למדים]\u0006 לחייב קנס בענין דומה, ולכן צריך לפרש בכל סוג של קנס בפני עצמו שחייבים עליו.","ושואלים: \u0003ולמאן דיליף קנסא מקנסא\u0004 \u0005[ול\u0006דעת \u0005מי שלומד קנס מקנס],\u0006 אם כן \u0003כל הני\u0004 \u0005[אלה],\u0006 מטמא, מדמע ומנסך, \u0003למה לי?\u0004","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו, \u0003דאי תנא\u0004 \u0005[שאם\u0006 היה \u0005שונה]\u0006 רק ב\u0003מטמא,\u0004 הרי \u0003אי\u0004 \u0005[אם]\u0006 מדובר במטמא \u0003תרומה\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהטעם שקנסוהו הוא \u0003משום דקא מפסיד לה\u0004 \u0005[שהוא מפסיד אותה]\u0006 \u0003לגמרי\u0004 על ידי מעשהו, שהרי מעתה אינה ראויה לאכילה כלל לשום אדם, \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר ב\u0003מטמא חולין\u0004 — הטעם לקנס הוא \u0003משום\u0004 ש\u0003אסור לגרום טומאה לחולין שבארץ ישראל\u0004 ולכן קנסוהו, \u0003אבל מדמע\u0004 שלא גרם להפסד מרובה, שהרי ניתן למכור את התערובות לכהן, ולא גרם לטומאה בארץ ישראל — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נקנוס אותו.","\u0003ו\u0004מצד שני \u0003אי אשמעינן\u0004 \u0005[אם\u0006 היה \u0005משמיע לנו]\u0006 \u0003מדמע,\u0004 הייתי סבור שדווקא בו יש לקנוס \u0003משום\u0004 שהוא \u0003שכיח\u0004 (מצוי) שיערבו אנשים דבר בדבר, \u0003אבל מטמא\u0004 שהוא \u0003לא שכיח\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 גזרו חכמים בדבר שאינו מצוי.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 גם \u0003מטמא ו\u0004גם \u0003מדמע\u0004 ולא היה משמיענו מנסך, הייתי אומר שהטעם שקנסוהו הוא \u0003משום\u0004 ש\u0003לא קים ליה בדרבה מיניה\u0004 \u0005[עומד\u0006 עונשו \u0005בגדול,\u0006 בחמור, \u0005ממנו],\u0006 כלומר, שלא עשה עבירה חמורה כל כך, שמפני שמתחייב בה בעונש חמור יותר פטור מתשלום ממון.","\u0003אבל מנסך דקים ליה בדרבה מיניה\u0004 \u0005[שעומד\u0006 \u0005ב\u0006עונש \u0005גדול ממנו]\u0006 שהרי הוא עובר עבירה שחייב עליה מיתה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 קנסוהו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב. וטעמו של דבר \u0003כ\u0004דברי \u0003ר' ירמיה,\u0004 שהואיל ומשעה שהגביהו קנאו — קודם חיוב הממון לחיוב המיתה, ולכן חייב בשניהם.","ושואלים: \u0003ולהא\u0004 \u0005[ו\u0006לפי ברייתא \u0005זו]\u0006 \u0003דתני אבוה\u0004 \u0005[ששנה אביו]\u0006 של \u0003ר' אבין: בראשונה היו אומרים\u0004 (שונים חכמים) \u0003המטמא והמנסך\u0004 קונסים אותם, \u0003חזרו לומר אף המדמע,\u0004 ולפי סדר זה של דבריהם \u0003כל הני\u0004 \u0005[אלה],\u0006 מטמא, מנסך ומדמע \u0003למה לי?\u0004","ומשיבים: \u0003צריכא\u0004 \u0005[צריכים]\u0006 כולם להיאמר; \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003מטמא,\u0004 הייתי אומר \u0003משום\u0004 ש\u0003לא קים ליה בדרבה מיניה\u0004 \u0005[עומד\u0006 \u0005ב\u0006עונש \u0005גדול ממנו],\u0006 \u0003אבל מנסך\u0004 לעבודה זרה \u0003דקים ליה בדרבה מיניה\u0004 \u0005[שעומד\u0006 \u0005ב\u0006עונש \u0005גדול ממנו]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 קנסוהו.","ומצד שני: \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 שקנסו \u0003מנסך,\u0004 הייתי אומר שקנסוהו \u0003משום דקא\u0004 \u0005[שהוא]\u0006 \u0003מפסיד ליה\u0004 \u0005[אותו]\u0006 \u0003לגמרי\u0004 שהרי היין נאסר בהנאה, \u0003אבל מטמא\u0004 ש\u0003לא\u0004 \u0003מפסיד ליה\u0004 \u0005[אותו]\u0006 \u0003לגמרי,\u0004 שאינו איסור הנאה, ומותר להשתמש בו בשעת שריפתו או להאכילו לבהמה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 קנסוהו.","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואם היה משמיע לנו\u0006 רק את \u0005שתי אלה],\u0006 הייתי אומר שקנסו \u0003משום\u0004 שמכל מקום יש פה \u0003הפסד מרובה, אבל מדמע,\u0004 שהפסד שגורם מועט שהרי יכול למכור את התערובת לכהנים בדמי תרומה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר ההלכה בכל פרטיה.","\u0003אמר חזקיה: דבר תורה\u0004 (מן התורה), \u0003אחד\u0004 (בין) \u0003שוגג ואחד\u0004 (ובין) \u0003מזיד\u0004 בכל אלה שנישנו במשנה: מטמא, מדמע ומנסך — \u0003חייב\u0004 לשלם מה שהזיק, ככל מזיק אחר. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — כי גם \u0003היזק שאינו ניכר, שמיה\u0004 \u0005[שמו,\u0006 נקרא, נחשב\u0005]\u0006 \u0003היזק,\u0004","\u0003ומה טעם אמרו\u0004 חכמים כי \u0003בשוגג פטור\u0004 — \u0003כדי שיודיעו\u0004 המזיק לניזק על מה שקרה. שאם היו קונסים אותו אף על השוגג — יש לחשוש שמא לא יודיע לניזק, כדי שלא ייקנס, והניזק שאינו יודע על מה שאירע (שהרי זה היזק שאינו ניכר לעין) ישתמש במה שטימא, או דימע, או ניסך, בשוגג שלא כדין.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם אנו חוששים לכך, \u0003אפילו במזיד נמי\u0004 \u0005[גם כן]\u0006 יפטרו אותו, כדי שיודיענו! ומשיבים: \u0003השתא לאוזוקי קא מכוין\u0004 \u0005[עכשיו,\u0006 הרי, \u0005להזיק הוא מתכוון],\u0006 \u0003אודועי\u0004 \u0005[להודיע]\u0006 \u0003לא מודע ליה\u0004 \u0005[יודיע לו]?\u0006 שהרי אם לא יודיע לו, לא ידע חבירו שהזיק לו! ובוודאי יודיענו שגרם לו איסור ונזק, ואין לחשוש שייכשל הבעלים בעבירה בשוגג. זוהי שיטת חזקיה.","\u0003ור' יוחנן אמר: דבר תורה, אחד שוגג ואחד מזיד\u0004 בדברים השנויים במשנתנו — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003היזק שאינו ניכר, לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003היזק,\u0004 ואינו נחשב מצד הדין להיזק, \u0003ומה טעם אמרו במזיד חייב\u0004 — כדי \u0003שלא יהא כל אחד ואחד\u0004 השונא את חבירו ומבקש להרע לו \u0003הולך ומטמא טהרותיו של חבירו, ואומר \"פטור אני\u0004 מלשלם\u0003\".\u0004","ומקשים על דברי חזקיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכהנים שפגלו במקדש,\u0004 שאמרו בשעת הקרבה שקרבן שבידם מיועד לאכול ממנו לאחר הזמן המותר באכילה, וקרבן זה נפסל, אם היו \u0003מזידים\u0004 בזאת — \u0003חייבין\u0004 לשלם את דמי הקרבן לבעליו, \u0003ותני עלה\u0004 \u0005[ושנויה עליה,\u0006 על משנה זאת\u0005]\u0006 שתיקנו דבר זה \u0003מפני תיקון העולם,\u0004 שלא יבואו הכהנים לעשות כן למי שהם רוצים להזיקו.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003היזק שאינו ניכר שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק, האי\u0004 \u0005[זה]\u0006 ש\u0003שוגגין פטורין מפני תיקון העולם מיבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 שהרי אילו עשו זאת במזיד חייבים לדעת חזקיה מדין תורה, ולא מפני תיקון העולם!","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר]\u0006 ואכן, כך יש להבין את המשנה: \u0003מזידין\u0004 — \u0003חייבין, הא\u0004 \u0005[הרי]\u0006 \u0003שוגגין\u0004 — \u0003פטורין,\u0004 וטעמו של דבר שפטורים — \u0003מפני תיקון העולם.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אלעזר\u0004 ממה ששנינו: \u0003העושה מלאכה במי חטאת\u0004 (מים שיש בהם אפר פרה אדומה, ומזים אותם כדי לטהר מטומאת המת), \u0003ובפרת חטאת\u0004 (פרה אדומה), ועל ידי עשיית מלאכה בהם פוסל אותם — \u0003פטור מדיני אדם וחייב בדיני שמים. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003היזק שאינו ניכר שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק,\u0004 אם כן \u0003בדיני אדם נמי לחייב\u0004 \u0005[גם כן שיתחייב]!\u0006","ומעירים: \u0003הוא,\u0004 ר' אלעזר \u0003מותיב לה\u0004 \u0005[מקשה אותה\u0006 קושיה\u0005],\u0006 \u0003והוא\u0004 זה ש\u0003מפרק לה\u0004 \u0005[מתרץ אותה];\u0006 מה שאמרנו לגבי \u0003פרה\u0004 אדומה שעשה בה מלאכה, הכוונה \u0003שהכניסה לרבקה\u0004 (לצמד הבקר) \u0003על מנת שתינק\u0004 מאימה \u0003ו\u0004דרך אגב \u0003תדוש,\u0004 שלא עשה מעשה של היזק ממש, ו\u0003מי חטאת\u0004 — \u0003ששקל בהן משקלות\u0004 כנגדן, ואף כאן הרי לא עשה מלאכה של ממש.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: מי חטאת\u0004"],["\u0003ששקל בהן משקלות — כשרה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 בברייתא מדובר שהוא שוקל \u0003בגופן\u0004 ממש ומשום כך הרי הוא פוסל אותם, \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא שכשרה, שהוא שוקל \u0003בכנגדן.\u0004","ושואלים: אם שוקל \u0003בגופן\u0004 אם כן \u0003מעשה\u0004 ממש \u0003קא עביד בהו\u0004 \u0005[הוא עושה בהם],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003היזק שאינו ניכר שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק,\u0004 אם כן \u0003בדיני אדם נמי לחייב\u0004 \u0005[גם כן יתחייב],\u0006 שהרי הוא עושה בה מעשה! \u0003אלא\u0004 צריכים לומר כך: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר שהוא שוקל \u0003בכנגדן, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה\u0006 בברייתא\u0005]\u0006 מדובר \u0003דאסח דעתיה\u0004 \u0005[שהסיח\u0006 \u0005דעתו]\u0006 משמירתם תוך כדי השקילה, ומשום הסחת הדעת נפסלו המים. \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא מדובר באופן ש\u0003לא אסח דעתיה\u0004 \u0005[הסיח דעתו]\u0006 וכיון שכך לא פסלם כלל.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב פפא\u0004 ממה ששנינו: \u0003גזל מטבע\u0004 מחבירו \u0003ו\u0004אחר כך \u0003נפסל\u0004 המטבע הזה על ידי המלכות, או גזל \u0003תרומה ונטמאת\u0004 התרומה, או גזל \u0003חמץ ועבר עליו הפסח, אומר לו\u0004 הגזלן לנגזל \u0003\"הרי שלך לפניך\",\u0004 והואיל והשיב מה שגזל אינו צריך לפצותו.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003היזק שאינו ניכר שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק,\u0004 אם כן \u0003האי\u0004 \u0005[זה]\u0006 \u0003גזלן הוא, ממונא מעליא בעי שלומי\u0004 \u0005[ממון טוב צריך\u0006 הוא \u0005לשלם\u0006 לו\u0005]\u0006 עבור מה שהזיקו! ואם כן, הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ונדחו דברי חזקיה.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שבעיה זו שנויה במחלוקת \u0005תנאים]\u0006 ששנינו: \u0003המטמא, והמדמע, והמנסך, אחד שוגג ואחד מזיד\u0004 — \u0003חייב\u0004 לשלם לחבירו על הנזק שגרם לו, אלו \u0003דברי ר' מאיר.\u0004 \u0003ר' יהודה אומר: בשוגג\u0004 — \u0003פטור, במזיד\u0004 — \u0003חייב.\u0004","ומציעים: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003היזק שאינו ניכר שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק\u0004 ולכן מחייב גם בשוגג, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק,\u0004 ומחייב רק במזיד ומשום קנס!","\u0003אמר רב נחמן בר יצחק\u0004 אפשר לדחות ולומר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003היזק שאינו ניכר לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003קנסו\u0004 גם \u0003שוגג אטו\u0004 \u0005[משום]\u0006 הקנס שקנסו ב\u0003מזיד קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד,\u0004 ולכן גם בשוגג הוא חייב, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבר]:\u0006 \u0003לא קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד.\u0004","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' מאיר אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003מאיר, ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יהודה אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המבשל בשבת,\u0004 אם עשה זאת \u0003בשוגג — יאכל\u0004 אם ירצה את מה שהתבשל, \u0003במזיד\u0004 — \u0003לא יאכל,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם בישל \u0003בשוגג — יאכל\u0004 ואולם רק \u0003ל\u0004כשיגיע \u0003מוצאי שבת,\u0004 \u0003במזיד\u0004 — \u0003לא יאכל עולמית.\u0004","\u0003ר' יוחנן הסנדלר אומר: בשוגג\u0004 — \u0003יאכל\u0004 הדבר הזה \u0003למוצאי שבת לאחרים ולא לו,\u0004 שהוא נאסר בכך לעולם, \u0003במזיד — לא יאכל עולמית לא לו ולא לאחרים.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' מאיר אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003מאיר\u0004 שהוא מחלק כאן בין שוגג ומזיד, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003יהודה\u0004 שאף בשוגג קונס!","ומתרצים: מדברי \u0003ר' מאיר אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003מאיר לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כי קניס\u0004 \u0005[כאשר\u0006 הוא \u0005קונס]\u0006 אף בשוגג, הרי זה \u0003בדרבנן\u0004 \u0005[בדברי סופרים]\u0006 כשעבר עבירה מדבריהם, ואולם \u0003בדאורייתא\u0004 \u0005[בדברי תורה]\u0006 כגון מבשל בשבת — \u0003לא קניס\u0004 \u0005[קונס],\u0006 שדברי תורה חמורים בעיני הבריות ואין צורך בקנס על השוגג כדי להרחיק מהם.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מנסך דאורייתא\u0004 \u0005[ש\u0006איסור \u0005מן התורה]\u0006 הוא, \u0003וקא קניס\u0004 \u0005[והוא קונס]!\u0006 ומשיבים: זהו יוצא מן הכלל, \u0003משום חומרא\u0004 \u0005[חומרת]\u0006 איסור \u0003עבודה זרה קנס ליה\u0004 \u0005[\u0006הוא \u0005קונס אותו].\u0006","ומדברי \u0003ר' יהודה אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003יהודה לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כי לא קניס\u0004 \u0005[כאשר אינו קונס]\u0006 — הרי זה בדבר שהוא \u0003בדרבנן\u0004 \u0005[ב\u0006עבירה \u0005שמדברי\u0006 \u0005סופרים],\u0006 ואולם \u0003בדאורייתא\u0004 \u0005[ב\u0006דברי \u0005תורה]\u0006 כגון מבשל בשבת — \u0003קניס\u0004 \u0005[\u0006הוא \u0005קונס].\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מנסך דאורייתא\u0004 \u0005[ש\u0006מן \u0005התורה\u0006 הוא\u0005],\u0006 \u0003ולא קניס\u0004 \u0005[קונס]!\u0006 ומשיבים: אותו נימוק יכול לשמש גם לצד האחר — \u0003משום חומרא\u0004 \u0005[חומרת]\u0006 איסור \u0003עבודה זרה מיבדל בדילי מיניה\u0004 \u0005[בדלים ממנו\u0006 אנשים\u0005]\u0006 ואין צורך בהרחקה נוספת לדבר.","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר ב\u0004דבר שהוא \u0003דאורייתא\u0004 \u0005[מדין תורה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנוטע בשבת,\u0004 אם עשה זאת \u0003בשוגג\u0004 — \u0003יקיים\u0004 את העץ, אם עשה זאת \u0003במזיד\u0004 — \u0003יעקר, ו\u0004אם נטע \u0003בשביעית, בין בשוגג בין במזיד — יעקר,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר: בשביעית, בשוגג\u0004 — \u0003יקיים, במזיד\u0004 — \u0003יעקר, ובשבת, בין בשוגג בין במזיד — יעקר.\u0004 הרי שבשביעית, למרות שהיא דבר שמן התורה, קונס ר' מאיר אף בשוגג, ואילו בברייתא לעיל לא קנס ר' מאיר מי שבישל בשבת בשוגג!","על הקושיה עצמה תמהים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה מקשה, \u0003תקשה לך היא\u0004 הברייתא \u0003גופה\u0004 \u0005[עצמה],\u0006 \u0003מכדי הא דאורייתא והא דאורייתא\u0004 \u0005[הואיל וזו מן התורה וזו מן התורה]\u0006 בין שבת בין שביעית, \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003שבת ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003שביעית?\u0004 שהרי רואים ששני החכמים מחלקים בין הדינים!","\u0003אלא התם כדקתני טעמא\u0004 \u0005[שם כפי ששנה\u0006 את \u0005הטעם\u0006 במפורש\u0005]:\u0006 \u0003אמר ר' מאיר, מפני מה אני אומר: בשבת בשוגג\u0004 — \u0003יקיים, במזיד\u0004 — \u0003יעקר, ובשביעית, בין בשוגג בין במזיד\u0004 — \u0003יעקר? מפני שישראל מונין לשביעית,\u0004 שמונים את שנות האילן (לחשבון ערלה ונטע רבעי) ועל ידי כך יודעים וזוכרים שאילן זה ניטע בשביעית, ויש טעם לעקירתו,"],["\u0003ואין מונין לשבתות\u0004 שאין משמעות לדבר באיזה יום מימות השבוע ניטע האילן, וממילא אין זוכרים שניטע האילן בשבת.","\u0003דבר אחר,\u0004 טעם אחר להבדל בין שבת לשביעית: \u0003נחשדו ישראל על השביעית\u0004 לחלל אותה, \u0003ולא נחשדו על השבתות.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"דבר אחר\",\u0004 כלומר, מפני מה הוצרך לתת עוד טעם בנוסף לטעם הראשון? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בטענה כנגד הטעם הראשון: \u0003שבת נמי\u0004 \u0005[גם כן]\u0006 מונים לה, וזוכרים שנטע בה אילן, שכן \u0003זימנין דמיקלע\u0004 \u0005[פעמים שמזדמן]\u0006 \u0003יום שלשים,\u0004 כלומר, שלושים יום לפני ראש השנה \u0003בשבת,\u0004 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003נטע ההוא יומא\u0004 \u0005[באותו יום]\u0006 \u0003הוא דסלקא ליה שתא\u0004 \u0005[שעולה לו שנה]\u0006 ונחשבת כשנה שלימה לענין שנות הערלה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 נטע ביום שלושים, אלא יום אחריו — \u0003לא סלקא ליה שתא\u0004 \u0005[עולה לו שנה],\u0006 ובמקרה זה יזכרו ששתל זאת בשבת, לכן מוסיפה הברייתא טעם אחר,","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003דבר אחר:\u0004 \u0003נחשדו ישראל על השביעית\u0004 ולכן יש לקנוס אותם, \u0003ולא נחשדו על השבתות.\u0004","ומדברי \u0003ר' יהודה,\u0004 שלא קנס בשביעית אף שהיא מן התורה, על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[קשה],\u0006 כי \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003ר' יהודה חמירא להו\u0004 \u0005[חמור היה להם]\u0006 איסור \u0003שביעית\u0004 ביותר.","ומביאים ראיה לדבר: מעשה \u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לחבירו\u0004 להעליבו: \u0003דייר בר דיירתא\u0004 \u0005[גר בן גיורת]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 כתשובה בכעס: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לא אכלי פירי\u0004 \u0005[אוכל פירות]\u0006 של \u0003שביעית כוותך\u0004 \u0005[כמותך].\u0006 משמע שהיה זה נחשב במקומם כאיסור חמור ביותר, ולא סבר ר' יהודה שיש לקנוס בכך. ומביאים עוד עניינים שיש בהם סתירה לכאורה בשיטת ר' מאיר בענין קנס למי שעבר בשוגג על דבר שמדברי חכמים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: אם \u0003אכל תרומה טמאה\u0004 שהיא ממון כהן — \u0003משלם\u0004 לכהן \u0003חולין טהורין.\u0004 אם \u0003שילם חולין טמאים, מהו? אמר סומכוס משום ר' מאיר:\u0004 אם \u0003בשוגג\u0004 אכל — \u0003תשלומיו תשלומין,\u0004 אם עשה זאת \u0003במזיד\u0004 — \u0003אין תשלומיו תשלומין, וחכמים אומרים: אחד זה ואחד זה — תשלומיו תשלומין,\u0004 אבל קנסוהו חכמים \u0003וחוזר ומשלם\u0004 נוסף לכך \u0003חולין טהורים.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה,\u0004 בשאלה זו: \u0003במזיד אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין תשלומיו תשלומין? תבא עליו ברכה, דאכיל מיניה מידי דלא חזי ליה\u0004 \u0005[ש\u0006הוא \u0005אוכל ממנו,\u0006 מן הכהן \u0005דבר שאינו ראוי לו]\u0006 אפילו \u0003בימי טומאתו,\u0004 שהרי תרומה טמאה אסור לכהן לאכול אותה בין כשהוא טהור ובין כשהוא טמא, \u0003וקא משלם ליה\u0004 \u0005[והוא משלם לו]\u0006 חולין טמאים שהם \u0003מידי דחזי ליה\u0004 \u0005[דבר שראוי לו]\u0006 לאכול \u0003בימי טומאתו!\u0004","\u0003ואמר רבא, ואמרי לה כדי\u0004 \u0005[ויש אומרים בלי שם]:\u0006 \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך היא שנויה]:\u0006 \u0003אכל תרומה טמאה\u0004 — \u0003משלם כל דהו\u0004 \u0005[כל\u0006 דבר \u0005שהוא]\u0006 ואף חולין טמאים, ואם \u0003אכל תרומה טהורה\u0004 — \u0003משלם חולין טהורים.\u0004 אם \u0003שילם חולין טמאין, מהו?\u0004 בזה נחלקו; \u0003סומכוס אומר משום ר' מאיר: בשוגג\u0004 — \u0003תשלומיו תשלומין, במזיד\u0004 — \u0003אין תשלומיו תשלומין, וחכמים אומרים: אחד זה ואחד זה\u0004 — \u0003תשלומיו תשלומין, וחוזר ומשלם חולין טהורין.\u0004","\u0003ואמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה של \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003לא קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד, וחכמים אומרים: קנסו,\u0004 ונמצא שר' מאיר אינו קונס בשוגג בדבר שהוא מדברי סופרים, שמן התורה יכול אדם לשלם בכל דבר אם אכל תרומה. והרי זה שלא כפי שהסברנו את שיטת ר' מאיר!","ומשיבים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003התם גברא לשלומי קא מיכוין\u0004 \u0005[שם האיש לשלם הוא מתכוון],\u0006 ולמצוה התכוון, \u0003אנן ניקום וליקנסיה\u0004 \u0005[אנו נעמוד ונקנסנו]?\u0006 ולכן, דווקא במקרה זה סבור ר' מאיר שאין מקום לקנוס אותו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003דם\u0004 קרבן \u0003שנטמא וזרקו\u0004 הכהן כאילו היה זה דם טהור, אם זרקו \u0003בשוגג\u0004 — \u0003הורצה\u0004 ונתכפר לבעלים בקרבן זה, ואם זרקו \u0003במזיד\u0004 — \u0003לא הורצה.\u0004 ומכל מקום לא קנסו בשוגג משום מזיד, אף שזריקה זו של הדם אסורה רק מדברי סופרים!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003ר' מאיר:\u0004 \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם גברא לכפורי קא מכוין, אנן ניקום ונקנסיה\u0004 \u0005[שם האדם לכפר הוא מתכוון ואנו נעמוד ונקנסנו]?\u0006 ולכן בזה אין קונסים שוגג משום מזיד.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003המעשר בשבת,\u0004 שאסרו חכמים לעשר בשבת משום שנראה בכך כמתקן דבר בשבת, אם עישר \u0003בשוגג\u0004 — \u0003יאכל\u0004 את המאכל, שהרי עישר אותו והוא ראוי לאכילה, ואם עשה זאת \u0003במזיד\u0004 — \u0003לא יאכל.\u0004 והרי לא קנסו שוגג משום מזיד בדבר שאסור מדברי סופרים! ומשיבים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם גברא לתקוני קא מיכוין\u0004 \u0005[שם האיש לתקן הוא מתכוון]\u0006 שהוא רוצה לעשר, \u0003אנן ליקום וליקנסיה\u0004 \u0005[אנו נעמוד ונקנסנו]?\u0006","ומביאים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003המטביל כלים בשבת,\u0004 שאסרו חכמים להטבילם משום שנראה כמתקן כלי בשבת, אם טבלם \u0003בשוגג\u0004 — \u0003ישתמש בהן,\u0004 אם \u0003במזיד\u0004 — \u0003לא ישתמש בהן,\u0004 ולא קנסו שוגג משום מזיד! ומשיבים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם גברא לטהורי מאני קא מיכוין\u0004 \u0005[שם האיש לטהר את הכלים\u0006 הוא \u0005מתכוון],\u0006 \u0003אנן ליקום וליקנסיה\u0004 \u0005[אנו נעמוד ונקנסנו]?\u0006","\u0003ורמי\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 בדברים שאיסורם הוא רק \u0003בדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003דתניא\u0004 \u0005[\u0006שכן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["אם \u0003נפלו\u0004 אגוזי פרך של ערלה לתוך תערובת של אגוזים אחרים הרי הם אוסרים את התערובת כולה, אף שהם מעטים מאוד, משום שהם חשובים כשהם שלמים ולכן אינם בטלים. \u0003ו\u0004אם \u0003נתפצעו\u0004 (נשברו) אחר כך, ואז שוב אינם חשובים והיו צריכים להתבטל, מכל מקום \u0003אחד\u0004 שנתפצעו ב\u0003שוגג ואחד\u0004 ב\u0003מזיד\u0004 — \u0003לא יעלו\u0004 (יתבטלו), אלו \u0003דברי ר' מאיר ור' יהודה. ר' יוסי ור' שמעון אומרים:\u0004 אם נתפצעו \u0003בשוגג\u0004 — \u0003יעלו, במזיד\u0004 — \u0003לא יעלו.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003דמדאורייתא חד בתרי בטל\u0004 \u0005[שמן התורה\u0006 תערובת של \u0005אחד בשנים בטל\u0006 האחד\u0005],\u0006 כלומר, כל דבר בטל ברוב, \u0003ורבנן הוא דגזור\u0004 \u0005[וחכמים הם שגזרו]\u0006 שדברים חשובים אין להם ביטול, \u0003וקא קניס\u0004 \u0005[וקונס]\u0006 \u0003ר' יהודה\u0004 שוגג משום מזיד בדבר שהוא מדברי חכמים! ומשיבים: \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 של \u0003ר' יהודה, משום\u0004 החשש \u0003דאתי לאיערומי\u0004 \u0005[שיבוא להערים]\u0006 ולשבור אותם במזיד כדי לבטל את האיסור.","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי \u0003ר' יוסי\u0004 שבאותה משנה. \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003נטיעה של ערלה ושל כלאי הכרם שנתערבו בנטיעות אחרות\u0004 של היתר, ואינו יודע איזו מהן היא נטיעת הערלה האסורה — \u0003הרי זה לא ילקט\u0004 מפירות אותן נטיעות, \u0003ואם ליקט\u0004 — \u0003יעלו\u0004 \u0003ב\u0004זמן שהיחס המספרי בין האסור למותר הוא \u0003אחד ומאתים,\u0004 ובלבד שלא יתכוין במזיד ללקט. \u0003ר' יוסי אומר:\u0004","\u0003ר' יוסי אומר: אף המתכוין ללקט\u0004 — \u0003יעלו באחד ומאתים.\u0004 משמע שאפילו במזיד הוא בטל!","ומשיבים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 בהסברת שיטת ר' יוסי, \u0003אמר רבא: חזקה אין אדם אוסר את כרמו ב\u0004שביל \u0003נטיעה אחת,\u0004 ולכן מן הסתם לא נטע שם נטיעה זו של ערלה בכוונה, ואם עשה כן — הרי זה דבר שאינו שכיח, ולא גזרו בו. \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: חזקה אין אדם אוסר את כרמו בנטיעה אחת,\u0004 ואין גוזרים בכך.","\u0003הכהנים שפגלו במקדש,\u0004 שאמרו בזמן שחיטת הקרבן שיזרק דמו או שתיעשה בו עבודה אחרת על מנת לאוכלו לאחר הזמן המותר, ועל ידי כך פוסלים את הקרבן לגמרי והבעלים צריך להביא קרבן חדש, אם היו \u0003מזידין\u0004 — \u0003חייבין\u0004 לשלם לבעל הקרבן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003היה עושה\u0004 (מתעסק) \u0003עמו,\u0004 עם חבירו, \u0003בטהרות, ואמר לו\u0004 לחבירו: \u0003טהרות שעשיתי עמך נטמאו,\u0004 או ש\u0003היה עושה עמו בזבחים, ואמר לו: זבחים שעשיתי עמך נתפגלו\u0004 — הרי זה \u0003נאמן\u0004 על כך. \u0003אבל\u0004 אם \u0003אמר לו: טהרות שעשיתי עמך ביום פלוני נטמאו,\u0004 או \u0003זבחים שעשיתי עמך ביום פלוני נתפגלו\u0004 — \u0003אינו נאמן.\u0004","ושואלים: \u0003מאי שנא רישא, ומאי שנא סיפא\u0004 \u0005[מה שונה ההתחלה ומה שונה הסוף],\u0006 שבמקרה הראשון נאמן ובשני לא? \u0003אמר אביי,\u0004 הכלל הוא: \u0003כל שבידו\u0004 עדיין לעשות זאת — \u0003נאמן,\u0004 ולכן כשאומר בשעת מעשה, כיון שיכול לעשות פסול זה גם כעת — הרי הוא נאמן, אבל על העבר אינו נאמן.","\u0003רבא אמר:\u0004 בשני המקרים מדובר בעדות על העבר, אלא שבמקרה השני מדובר \u0003כגון דאשכחיה\u0004 \u0005[שמצא אותו]\u0006 לאחר מעשה \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 \u0003ולבתר הכי אשכחיה\u0004 \u0005[ואחר כך מצא אותו]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 שאז יש מקום לחשוד בו שמשקר, שכן, אם אמת הדבר שנפסלו — היה אומר לו בשעתו, וכיון שלא אמר לו אז, ואומר לו כעת לאחר זמן, מן הסתם משקר, מפני שרוצה לקלקל לו.","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003טהרות שעשיתי עמך ביום פלוני נטמאו, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003שורת הדין\u0004 (מעיקר הדין) \u0003אינו נאמן\u0004 על כך. \u0003אמר לפניו ר' אסי: רבי, אתה אומר כן? הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן משום ר' יוסי: מה אעשה שהתורה האמינתו\u0004 בכגון זה.","ושואלים: \u0003היכן האמינתו? אמר ר' יצחק בר ביסנא: כהן גדול ביום הכיפורים יוכיח, דכי אמר\u0004 \u0005[שכאשר\u0006 הוא \u0005אומר]\u0006 שהיה שם \u0003פגול\u0004 — \u0003מהימן\u0004 \u0005[נאמן],\u0006 \u0003ומנא ידעינן\u0004 \u0005[ומנין אנו יודעים]\u0006 שכך באמת היה? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וכל אדם לא יהיה באהל מועד\u0004 בבואו לכפר בקודש\u0003\"\u0004 (ויקרא טז, יז). \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דמהימן\u0004 \u0005[שנאמן]\u0006 להעיד על כך, גם אם אין הדבר עוד בידו, לאחר שעבד עבודה?","ודוחים: \u0003ודלמא דשמעניה דפגיל\u0004 \u0005[ושמא ששמענו אותו שפיגל],\u0006 שאמר דבר זה בקול רם בשעת עבודתו ושמעו אותו מבחוץ! ומשיבים: \u0003אי לאו דמהימן\u0004 \u0005[אם לא ש\u0006הוא \u0005נאמן]\u0006 בדבר זה, \u0003אף על גב דשמעניה נמי לא מהימן\u0004 \u0005[אף על פי ששמענו אותו, גם כן אינו נאמן],\u0006 ומדוע? — \u0003דדלמא לבתר הכי קאמר\u0004 \u0005[ששמא אחר כך אמר].\u0006 שבאמת זרק את הדם כדינו, ולאחר הזריקה אמר מה שאמר, ובאותה שעה אינו עושה פיגול. אלא בוודאי משום שמאמינים לו.","וחוזרים ומקשים: \u0003ודלמא דחזיניה\u0004 \u0005[ושמא ראינו אותו]\u0006 \u0003בפישפש\u0004 (דלת קטנה) שיש שם, שאפשר לראות מה עושה הכהן גם בפנים וראו שבשעת הזריקה פיגל? ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]\u0006 שבאמת אין מכאן הוכחה גמורה.","מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003ר' אמי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ספר תורה שכתבתי לפלוני, אזכרות\u0004 (שמות השם) \u0003שלו לא כתבתים לשמן,\u0004 והספר פסול. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003ספר תורה\u0004 זה מצוי כעת \u0003ביד מי? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ביד לוקח\u0004 (הקונה), \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נאמן אתה להפסיד שכרך,\u0004 שהרי אתה מודה שלא כתבת את הספר כראוי, ויכול הקונה שלא לשלם לך שכר על כתיבת ספר תורה, \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה נאמן להפסיד ספר תורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה: נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003הפסיד שכר אזכרות\u0004 שכתבן שלא כראוי, \u0003שכר של ספר תורה\u0004 \u0003כוליה\u0004 \u0005[כולו]\u0006 שכתבו כהלכתו \u0003מי\u0004 \u0005[האם]\u0006 \u0003הפסיד?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003שכל ספר תורה שאין אזכרות שלו כתובות לשמן\u0004 — \u0003אינו שוה כלום.\u0004","ושואלים: \u0003וליעבר עלייהו\u0004 \u0005[ושיעבור עליהן],\u0006 על האזכרות ב\u0003קולמוס\u0004 לשמן \u0003וליקדשיה\u0004 \u0005[ויקדש אותן]!\u0006 וכיון שאין משתמשים בדרך זו של תיקון \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 הולכים? \u0003נימא\u0004 \u0005[האם לומר]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' יהודה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הרי שהיה\u0004 הסופר \u0003צריך לכתוב את השם\u0004 (שם הויה, י \u0003־\u0004 ה־ו־ה), והוא עצמו טעה בכך ו\u0003נתכוון לכתוב \"יהודה\", וטעה ולא הטיל בו\u0004 את האות \u0003דלת,\u0004 ונמצא שאמנם כתב את השם, אבל לא התכוון לשם קדושת השם — \u0003מעביר עליו,\u0004 על מה שכתב, \u0003קולמוס,\u0004 שכותב שנית על הכתוב \u0003ומקדשו,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים: אין השם מן המובחר.\u0004 וכיון שלא הציעו לתקן כך את הספר, משמע שסבורים כדעת חכמים, ולא כר' יהודה!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שבכלל הלכה כשיטת \u0003ר' יהודה, עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה\u0004 שאפשר להעביר קולמוס ולקדש את האזכרות — \u0003אלא בחדא\u0004 \u0005[באחת]\u0006 \u0003אזכרה\u0004 שקרה בה מקרה זה, \u0003אבל\u0004 באזכרות \u0003דכולי\u0004 \u0005[של כל]\u0006 \u0003ספר תורה\u0004 — \u0003לא.\u0004 ומדוע אין עושים כן — \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 ספר התורה \u0003כמנומר,\u0004 שהרי על ידי העברת הקולמוס עליהן האזכרות כתובות בדיו אחרת ונבדלות משאר הכתיבה.","ועוד מסופר, \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003ר' אבהו, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ספר תורה שכתבתי לפלוני, גוילין שלו לא עיבדתים לשמן, אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003ספר תורה ביד מי? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ביד לוקח, אמר לו: מתוך שאתה נאמן להפסיד שכרך\u0004 שהודית שהספר פסול, \u0003אתה נאמן להפסיד ספר תורה.\u0004"],["ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 דבר זה \u0003מ\u0004הדבר שאמר \u0003ר' אמי,\u0004 שאמר לסופר שאינו נאמן להפסיד את ספר התורה? ומשיבים: \u0003התם איכא למימר\u0004 \u0005[שם יש לומר]\u0006 שבאמת התכוון להקניט ולא כך היה, והוא טען כך כי \u0003טעי\u0004 \u0005[טעה]\u0006 \u0003ב\u0004דברי \u0003ר' ירמיה,\u0004 שחשב שלא יפסיד בטעות זו אלא את שכר האזכרות, אבל יקבל שכר עבור שאר הספר. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דקא מפסיד כוליה אגריה\u0004 \u0005[\u0006שיודע \u0005שהוא מפסיד\u0006 את \u0005כל שכרו]\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ואמר, אימור קושטא קאמר\u0004 \u0005[אמור\u0006 ש\u0005אמת הוא אומר]\u0006 ויש להאמין לו. וכיון שאנו מאמינים לו ואין חוששים שעשה להקניט, אם כן ספר התורה פסול.","\u0003העיד ר' יוחנן בן גודגדא\u0004 לפני חכמים על הלכות אלו: \u0003על החרשת שהשיאה אביה\u0004 כשהיא קטנה, שנישואיה תופסים מדין תורה — \u0003שהיא יוצאה בגט\u0004 אפילו כשהיא גדולה, ואף שנחשבת כמי שאין לה דעת, לפי שבגט אין צורך בדעתה של האשה,","\u0003ועל קטנה בת ישראל שנשאת לכהן\u0004 כשהשיאוה לו אמה או אחיה, אף שהנישואין הללו תקפים רק מדברי סופרים, ומדין תורה אסור לזר לאכול תרומה, \u0003ש\u0004מכל מקום \u0003אוכלת בתרומה, ואם מתה\u0004 קטנה כזו — \u0003בעלה יורשה,\u0004 ואין אומרים שכיון שהיו הנישואין רק מדברי סופרים אינו זוכה בירושתה.","\u0003ו\u0004עוד העיד \u0003על המריש\u0004 (קורה) \u0003הגזול שבנאו בבירה\u0004 (בבנין) שהגזלן השתמש בקורה זו כחלק מן הבנין, שאף שמצד הדין צריך להחזיר לנגזל את הגזילה עצמה — \u0003שיטול\u0004 הנגזל רק \u0003את דמיו, מפני תקנת השבים,\u0004 שתיקנו כך כדי להקל על החוזרים בתשובה, שאם יצטרך הגזלן להרוס את הבנין כולו כדי להשיב לנגזל את הקורה שגזל, יהא קשה לגזלן לשוב.","\u0003ו\u0004עוד העיד \u0003על\u0004 קרבן \u0003חטאת הגזולה שלא נודעה לרבים\u0004 שלא ידעו רבים שהיא גזולה — \u0003ש\u0004בכל זאת \u0003היא מכפרת\u0004 על הגזלן שהביאה, \u0003מפני תיקון המזבח.\u0004","\u0003אמר רבא: מעדותו של ר' יוחנן בן גודגדא\u0004 במשנתנו נלמד: \u0003אמר\u0004 הבעל \u0003לעדים \"ראו גט זה שאני נותן לה\u0004 לאשתי \u0003\",\u0004 \u0003וחזר ואמר לה\u0004 לאותה אשה עצמה: \u0003\"כנסי\u0004 (קחי) \u0003שטר חוב זה\"\u0004 — \u0003הרי זו מגורשת,\u0004 אף שהיא עצמה אינה יודעת שהוא גט. ומנין? \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' יוחנן בן גודגדא\u0004 ש\u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 את \u0003דעתה\u0004 של האשה בגט, שאפילו היא חרשת שאינה בת דעת הגירושין חלים, \u0003הכי נמי לא בעינן\u0004 \u0005[כך גם כן אין אנו צריכים]\u0006 את \u0003דעתה\u0004 בענין זה.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003כיון\u0004 שחזר ו\u0003אמר\u0004 אחרי כן: \u0003\"כנסי שטר חוב זה\" בטולי בטליה\u0004 \u0005[ביטל]\u0006 את הגט בדבריו אלה, ולא יהא זה אלא כשטר בלבד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא ש\u0003אם איתא דבטליה\u0004 \u0005[כן הוא שביטל אותו]\u0006 — \u0003לעדים הוה אמר להו\u0004 \u0005[היה אומר להם]\u0006 שהוא מבטל את הגט, וכיון שלא אמר להם — ודאי לא ביטלו, \u0003והאי דקאמר הכי\u0004 \u0005[וזה שאומר\u0006 לה \u0005כך]\u0006 שהוא שטר חוב הרי זה \u0003משום כיסופא\u0004 \u0005[בושה]\u0006 שהוא מתבייש ממנה שהוא נותן לה גט, ולכן נותן לה את הגט בלא שתדע בזמן הגירושין שמגרשה בכך.","שנינו במשנה שהעיד ר' יוחנן בן גודגדא \u0003על קטנה בת ישראל\u0004 שאוכלת בתרומה. ומדייקים: \u0003ואילו חרשת לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 בתרומה אצל בעלה הכהן. ומסבירים \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003גזירה שמא\u0004 מתוך שיתירו לחרשת שנישאה לכהן לאכול תרומה מפני נישואיה לכהן, יאכיל כהן \u0003חרש\u0004 שנשא \u0003חרשת בתרומה,\u0004 שכן מצוי שחרש נושא חרשת.","ושואלים: ומה בכך? \u0003וליכול\u0004 \u0005[ושיאכיל],\u0006 הלא \u0003קטן אוכל נבלות הוא!\u0004 כיון שהחרשת אינה בתדעת ואינה חייבת במצוות, גם אם אכלה אין בכך איסור, שקטן שאוכל נבלות מדעתו אין מצווים להפריש אותו!","ומשיבים: אלא, הטעם שחרשת שנישאה לכהן אינה אוכלת בתרומה היא \u0003גזרה שמא יאכיל\u0004 כהן \u0003חרש בפיקחת.\u0004 שנישואיו אינם אלא מדברי סופרים, ואסור לה לאכול בתרומה. ויש לחשוש שלא יבחינו בין נישואי פיקח וחרשת (שאוכלת מן הדין בתרומה) לבין נישואי חרש ופיקחת (שאינה אוכלת בתרומה), ונמצא שמאכיל אותה דבר האסור לה.","ושואלים: \u0003ולאכול\u0004 \u0005[ושיאכיל]\u0006 \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 שכשם שהנישואין מדברי סופרים, כך התרומה מדברי סופרים! ומשיבים: \u0003גזירה\u0004 היא \u0003שמא אתי לאכולי\u0004 \u0005[שמא יבוא להאכיל אותה]\u0006 \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה]\u0006 ומשום כך אסרו עליה לאכול כל תרומה.","שנינו במשנה שר' יוחנן בן גודגדא העיד \u0003על המריש\u0004 (קורה) \u0003הגזול שבנאו\u0004 בבירה (בנין) שנותן את דמיו בלבד. ושנינו באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גזל מריש\u0004 \u0003ובנאו בבירה\u0004 — \u0003בית שמאי אומרים: מקעקע\u0004 (שובר) את \u0003כל הבירה כולה ומחזיר מריש לבעליו, ובית הלל אומרים: אין לו אלא דמי מריש בלבד, משום תקנת השבין,\u0004 שתיקנו כן כדי להקל על העבריינים לחזור בהם בתשובה. ומשנתנו כדברי בית הלל.","שנינו עוד שהעיד ר' יוחנן בן גודגדא \u0003על חטאת הגזולה\u0004 שלא נודעה לרבים שהיא גזולה, שהיא מכפרת. \u0003אמר עולא:\u0004 מ\u0003דבר תורה\u0004 ההלכה היא: \u0003בין נודעה ובין לא נודעה\u0004 — \u0003אינה מכפרת,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003יאוש כדי\u0004 \u0005[בלבד]\u0006 \u0003לא קני\u0004 \u0005[קונה],\u0006 שעצם יאושם של הבעלים אינו מקנה את גוף הגזילה לגזלן, וכיון שגזל את הבהמה מבעליה ולא עשה בה שינוי, נמצא שלא היתה הגזילה שייכת לו ואינו יכול להקריבה, ולהתכפר בה. \u0003ומה טעם אמרו\u0004 שאם \u0003לא נודעה מכפרת?\u0004 — \u0003שלא יהו כהנים עצבין,\u0004 שהקריבו דבר שאינו ראוי למזבח.","\u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לעולא:\u0004 כיצד אתה מפרש כך, \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"מפני תיקון המזבח\" תנן\u0004 \u0005[שנינו]?\u0006 משמע שאין זה תיקון לכהנים אלא תיקון למזבח! \u0003אמר להם: כיון\u0004 שה\u0003כהנים עצבין, נמצא מזבח בטל,\u0004 שאין מקריבין די קרבנות.","זהו הסבר אחד, \u0003ו\u0004אילו \u0003רב יהודה אמר: דבר תורה, בין נודעה\u0004 הגזילה \u0003בין לא נודעה\u0004 — החטאת הזו \u0003מכפרת, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003יאוש כדי\u0004 \u0005[בלבד]\u0006 \u0003קני\u0004 \u0005[קונה]\u0006 ונעשית הגזילה לאחר יאוש רכוש הגזלן, ויכול להקדישה, ונמצא שהקרבן היה קרבן ראוי, ומתכפר בה."],["\u0003ומה טעם אמרו\u0004 שאם \u0003נודעה\u0004 הגזילה \u0003אינה מכפרת\u0004 כדי \u0003שלא יאמרו\u0004 האנשים \u0003מזבח אוכל גזילות\u0004 ולכן כדי שלא להוציא שם רע על המזבח תיקנו תקנה זו.","ומעתה מבררים את השיטות \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003עולא\u0004 שהחשש נובע מכך שהכהנים יהיו עצבים \u0003היינו דקתני\u0004 \u0005[זהו ששנה\u0006 במשנה\u0005]\u0006 \u0003חטאת,\u0004 שהכהנים אוכלים אותה ובסוף מתברר להם שאכלו דבר האסור ומתעצבים על כך. \u0003אלא לרב יהודה\u0004 שלדעתו החשש הוא משום כבוד המזבח \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 דווקא \u0003חטאת אפילו עולה נמי\u0004 \u0005[גם כן]\u0006 יהיה בה אותו דין!","ומשיבים בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר];\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003עולה\u0004 ש\u0003כליל היא,\u0004 שוודאי יש בכך לעז למזבח, תיקנו שאינה קריבה, \u0003אלא אפילו חטאת נמי\u0004 \u0005[גם כן]\u0006 ש\u0003חלב ודם\u0004 בלבד \u0003הוא דסליק\u0004 \u0005[שעולה]\u0006 \u0003לגבי מזבח ואידך\u0004 \u0005[והשאר]\u0006 ה\u0003כהנים אכלי ליה\u0004 \u0005[אוכלים אותו]\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003גזור\u0004 \u0005[גזרו]\u0006 כדי \u0003שלא יאמרו מזבח אוכל גזילות.\u0004","ומבררים עוד: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003על חטאת הגזולה שלא נודעה לרבים —\u0004 \u0003שהיא מכפרת מפני תיקון המזבח. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003עולא\u0004 הרי זה \u0003ניחא\u0004 \u0005[נוח]\u0006 שהתקנה היא שתהא החטאת שלא נודעה מכפרת \u0003אלא ל\u0004שיטת \u0003רב יהודה\u0004 הלא \u0003איפכא מיבעי ליה\u0004 \u0005[ההיפך היה צריך לו\u0006 לומר \u0005],\u0006 שהיה צריך לומר שהתקנה היא שחטאת שנודעה אינה מכפרת!","ומשיבים \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 שכך צריך להבין את המשנה: אם \u0003לא נודעה\u0004 — \u0003מכפרת,\u0004 ואם \u0003נודעה\u0004 — \u0003אינה מכפרת מפני תיקון המזבח.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003גנב\u0004 בהמה \u0003והקדיש\u0004 אותה \u0003ואחר כך טבח\u0004 אותה או \u0003מכר\u0004 אותה — \u0003משלם תשלומי כפל\u0004 כגנב \u0003ואינו משלם תשלומי ארבעה וחמשה\u0004 כדין טובח ומוכר מה שגנב מחבירו. \u0003ותני עלה\u0004 \u0005[ושנינו עליה]:\u0006 אם שחט את הבהמה הזו \u0003בחוץ,\u0004 מחוץ למקדש — \u0003כי האי גוונא\u0004 \u0005[ב\u0006מקרה \u0005כגון זה]\u0006 \u0003ענוש כרת\u0004 משום מקריב קדשים בחוץ \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003יאוש כדי\u0004 \u0005[בלבד]\u0006 \u0003לא קני\u0004 \u0005[קונה],\u0006 אם כן \u0003כרת מאי עבידתיה\u0004 \u0005[מה מעשיו\u0006 מה עניינו\u0005],\u0006 הרי אין בכך חיוב כרת שהרי לא היתה לו כל יכולת להקדיש את הבהמה שאינה שלו!","\u0003אמר רב שיזבי:\u0004 הכוונה היא שחייב \u0003כרת מדבריהם,\u0004 מדברי סופרים. \u0003אחיכו עליה\u0004 \u0005[צחקו עליו]\u0006 השומעים; \u0003כרת מדבריהם מי איכא\u0004 \u0005[האם יש]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא: גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003אמר מילתא\u0004 \u0005[דבר]\u0006 \u0003לא תחוכו עלה\u0004 \u0005[אל תצחקו עליו],\u0006 מדובר פה ב\u0003כרת שעל ידי דבריהן\u0004 של חכמים שגזרו שיחול על כך הקדש \u0003באתה\u0004 (באה) \u0003לו\u0004 שכן \u0003אוקמוה רבנן ברשותיה כי היכי דליחייב עלה\u0004 \u0005[העמידו חכמים\u0006 את הבהמה \u0005ברשותו כדי שיתחייב עליה].\u0006","\u0003אמר רבא:\u0004 אף שאני מסכים לדבריו של רב שיזבי, \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003וודאי קא מיבעיא לי\u0004 \u0005[מסופק לי];\u0006 \u0003כי אוקמוה רבנן ברשותיה\u0004 \u0005[כאשר העמידוה חכמים\u0006 את הבהמה \u0005ברשותו],\u0006 האם \u0003משעת גניבה או משעת הקדישה\u0004 העמידוה ברשותו? ומבררים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מאיזו שעה היא ברשותו — \u0003לגיזותיה\u0004 (צמרה) \u0003וולדותיה,\u0004 שאם הקנוה לו משעת הגניבה ואחר כך גדל צמרה וילדה — אין הגזלן צריך להחזיר את גיזותיה וולדותיה ואם רק לאחר מכן משעה שהקדישה — חייב להחזיר אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא\u0004 שמצא פתרון לדבר: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 שהעמידו חכמים ברשותו את הבהמה \u0003משעת הקדישה.\u0004 וטעמו של דבר — \u0003שלא יהא חוטא נשכר.\u0004 שלולא כן נמצא שבגלל תקנת חכמים הוא מרויח את פירות הגזילה במשך הזמן","\u0003לא היה\u0004 דין \u0003סיקריקון\u0004 נוהג \u0003ב\u0004ארץ \u0003יהודה ב\u0004זמן \u0003הרוגי\u0004 \u0003מלחמה,\u0004 כלומר, בזמן תוקף המלחמה. \u0003מהרוגי המלחמה ואילך יש בה\u0004 דין \u0003סיקריקון. כיצד\u0004 הוא דין זה? — מי ש\u0003לקח\u0004 (קנה) שדה \u0003מסיקריקון,\u0004 מן הגוי שנטל את השדה מבעליו על ידי איומים \u0003ו\u0004אחרי כן \u0003חזר\u0004 אותו אדם \u0003ולקח\u0004 אותו שדה עצמו \u0003מבעל הבית,\u0004 בעל השדה הראשון — \u0003מקחו בטל,\u0004 שיכול לומר בעל השדה כי לא התכוון באמת שתיקנה לו השדה\u0003.\u0004 אבל אם קנה תחילה \u0003מבעל הבית וחזר ולקח מסיקריקון\u0004 — \u0003מקחו קיים.\u0004","וכיוצא בזה אם תחילה \u0003לקח מן האיש\u0004 קרקע השייכת או המשועבדת לאשתו \u0003ו\u0004אחרי כן \u0003חזר ולקח\u0004 אותה קרקע \u0003מן האשה\u0004 — \u0003מקחו בטל,\u0004 שיכולה האשה לטעון שלא רצתה להסתכסך עם בעלה ולמחות ביד הקונה לאחר שכבר נמכר השדה אבל באמת לא הסכימה למכירה. ואולם אם קנה קודם \u0003מן האשה וחזר ולקח מן האיש\u0004 — \u0003מקחו קיים. זו\u0004 שיטת \u0003משנה ראשונה\u0004 בסיקריקון.","ואילו \u0003בית דין של אחריהם אמרו: הלוקח מסיקריקון נותן לבעלים רביע\u0004 (רבע) ממחיר השדה. \u0003אימתי\u0004 אמרו דבר זה — \u0003בזמן שאין בידן\u0004 של הבעלים \u0003ליקח, אבל\u0004 אם \u0003יש בידן ליקח\u0004 — \u0003הן קודמין לכל אדם.\u0004","\u0003רבי הושיב\u0004 לאחר זמן \u0003בית דין ונמנו\u0004 (הצביעו) והגיעו להחלטה זו: \u0003שאם שהתה\u0004 השדה \u0003בפני סיקריקון שנים עשר חדש\u0004 ולא יצאה מידם — \u0003כל הקודם ליקח\u0004 (לקנות) שדה זו \u0003זכה\u0004 בה, בגוף השדה, \u0003אבל נותן לבעלים רביע\u0004 מן המחיר","על דברי המשנה שלא היה סיקריקון ביהודה בהרוגי מלחמה תוהים: \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 \u0003בהרוגי המלחמה לא היה בה סיקריקון,\u0004 שלא היו גוזלים, \u0003מהרוגי מלחמה ואילך,\u0004 אחר המלחמה, \u0003יש בה סיקריקון!\u0004","\u0003אמר רב יהודה:\u0004 הכוונה היא ש\u0003לא דנו בה\u0004 בזמן הרוגי המלחמה \u0003דין סיקריקון קאמר\u0004 \u0005[אמר],\u0006 והיו מאשרים את הקנין שקנה אדם מן הסיקריקון. וטעמו של דבר הוא על פי מה ש\u0003אמר ר' אסי: שלש גזירות גזרו\u0004 הגויים בזמן המלחמה שבה נחרב הבית. \u0003גזרתא קמייתא\u0004 \u0005[גזירה ראשונה]\u0006 היתה: \u0003כל\u0004 מי ש\u0003לא קטיל\u0004 \u0005[הורג]\u0006 מן היהודים — \u0003ליקטלוהו\u0004 \u0005[יהרגו אותו].\u0006 גזירה \u0003מציעתא\u0004 \u0005[אמצעית,\u0006 שניה\u0005]\u0006 היתה: \u0003כל\u0004 מי \u0003דקטיל\u0004 \u0005[שהורג]\u0006 יהודי — \u0003לייתי ארבע זוזי\u0004 \u0005[שיתן ארבעה זוז\u0006 כקנס\u0005].\u0006 גזירה \u0003בתרייתא\u0004 \u0005[אחרונה]\u0006 היתה: \u0003כל\u0004 מי \u0003דקטיל\u0004 \u0005[שהורג]\u0006 יהודי — \u0003ליקטלוהו\u0004 \u0005[יהרגו אותו].\u0006 \u0003הלכך\u0004 \u0005[לכן]\u0006 בזמן הגזירות \u0003קמייתא ומציעתא\u0004 \u0005[הראשונה והאמצעית],\u0006 \u0003כיון דקטלי\u0004 \u0005[ש\u0006הגויים \u0005היו הורגים]\u0006 — \u0003אגב אונסיה\u0004 \u0005[אונסו]\u0006 של מוות שיש בדבר \u0003גמר ומקני\u0004 \u0005[היה\u0006 בעל השדה \u0005גומר\u0006 בלבו \u0005ומקנה]\u0006 קנין גמור למי שלקח ממנו ונעשה השדה קנוי לסיקריקון לגמרי, וזהו בהרוגי מלחמה בזמן הגזירה.","\u0003בתרייתא\u0004 \u0005[האחרונה],\u0006 מהרוגי מלחמה ואילך, \u0003אמרי\u0004 \u0005[אומרים]\u0006 הנגזלים לעצמם \u0003האידנא לישקול\u0004 \u0005[עכשיו שיקח]\u0006 את השדה, \u0003למחר תבענא ליה בדינא\u0004 \u0005[אתבע אותו בדין],\u0006 שאף שהיתה יד הגוי תקיפה בשעתו והכריח את הבעלים לתת לו את שדהו, מכל מקום אנו אומרים שלא גמרו בליבם להקנות לו מפני שבעל השדה סבור שיוכל אחר כך להוציא את הדבר מידיו במשפט","כיון שהוזכר ענין מלחמת החורבן באים לדבר על פרטים שונים שהיו בה. \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אשרי אדם מפחד תמיד ומקשה לבו יפול ברעה\"\u0004 (משלי כח יד) — \u0003אקמצא\u0004 \u0005[על\u0006 \u0005קמצא]\u0006 \u0003ובר קמצא\u0004 \u0003חרוב\u0004 \u0005[נחרבה]\u0006 \u0003ירושלים, אתרנגולא ותרנגולתא חרוב טור מלכא\u0004 \u0005[על תרנגול ותרנגולת נחרבה\u0006 המקום ששמו \u0005הר המלך],\u0006 \u0003אשקא דריספק חרוב\u0004 \u0005[על יתד של מרכבה חרבה]\u0006 העיר \u0003ביתר.\u0004","ומפרש: \u0003אקמצא\u0004 \u0005[על קמצא]\u0006 \u0003ובר קמצא חרוב\u0004 \u0005[נחרבה]\u0006 \u0003ירושלים,\u0004 וכך היה מעשה: \u0003דההוא גברא דרחמיה\u0004 \u0005[אדם אחד שאוהבו]\u0006 היה נקרא \u0003קמצא, ובעל דבביה\u0004 \u0005[ושונאו]\u0006 היה נקרא \u0003בר קמצא\u0004. \u0003עבד סעודתא\u0004 \u0005[עשה סעודה],\u0006 משתה גדול, \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי\u0004 את \u0003קמצא\u0004 (אוהבו). \u0003אזל אייתי ליה\u0004 \u0005[הלך\u0006 ו\u0005הביא לו]\u0006 בטעות את \u0003בר קמצא\u0004 (שונאו).","\u0003אתא אשכחיה דהוה יתיב\u0004 \u0005[בא\u0006 בעל הבית \u0005מצא אותו,\u0006 את בר קמצא, \u0005שהוא יושב\u0006 בסעודה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לבר קמצא: \u0003מכדי ההוא גברא בעל דבבא דההוא גברא\u0004 \u0005[הרי אדם זה,\u0006 כלומר, אתה, \u0005שונא של אותו אדם,\u0006 שלי\u0005]\u0006 \u0003הוא,\u0004 ואם כן \u0003מאי בעית הכא\u0004 \u0005[מה אתה רוצה כאן]?\u0006 \u0003קום פוק\u0004 \u0005[צא]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קמצא: \u0003הואיל ואתאי\u0004 \u0005[ו\u0006כבר \u0005באתי],\u0006 \u0003שבקן ויהיבנא\u0004 \u0005[הנח לי ואתן]\u0006 \u0003לך דמי\u0004 כל \u0003מה דאכילנא ושתינא\u0004 \u0005[שאני אוכל ושותה],\u0006 ואל תביישני בזה שאתה מגרש אותי מן הסעודה"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבית: \u0003לא. אמר ליה\u0004 \u0005[לו]\u0006 בר קמצא: \u0003יהיבנא\u0004 \u0005[אתן]\u0006 \u0003לך דמי פלגא דסעודתיך\u0004 \u0005[חצי סעודתך]\u0006 ובלבד שלא תוציאני! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יהיבנא\u0004 \u0005[אתן]\u0006 \u0003לך דמי כולא סעודתיך\u0004 \u0005[כל סעודתך]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 ולבסוף \u0003נקטיה בידיה ואוקמיה ואפקיה\u0004 \u0005[אחזו בידו והעמידו והוציאו\u0006 החוצה\u0005].\u0006","\u0003אמר\u0004 בר קמצא: \u0003הואיל והוו יתבי רבנן\u0004 \u0005[והיו יושבים\u0006 שם \u0005חכמים]\u0006 \u0003ולא מחו ביה\u0004 \u0005[בו]\u0006 אף על פי שראו כיצד הוא מביישני, \u0003שמע מינה קא ניחא להו\u0004 \u0005[למד אתה מכאן שנוח להם]\u0006 בדבר כזה. \u0003איזיל איכול בהו קורצא בי מלכא\u0004 \u0005[אלך,\u0006 ו\u0005אלשין עליהם בבית המלך].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 למלכות \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לקיסר: מרדו בך יהודאי\u0004 \u0005[היהודים]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי יימר\u0004 \u0005[יאמר,\u0006 יוכיח\u0005]\u0006 שכן הוא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 נסה אותם בכך, \u0003שדר להו קורבנא, חזית אי מקרבין ליה\u0004 \u0005[שלח להם קרבן\u0006 לכבוד המלכות, ו\u0005תראה אם מקריבים אותו].\u0006","\u0003אזל שדר בידיה עגלא תלתא\u0004 \u0005[הלך\u0006 הקיסר, \u0005שלח בידו\u0006 \u0005עגל משולש\u0006 מובחר\u0005].\u0006 \u0003בהדי דקאתי\u0004 \u0005[בזמן שבא]\u0006 בר קמצא משם \u0003שדא ביה מומא\u0004 \u0005[הטיל בו מום]\u0006 \u0003בניב שפתים,\u0004 בשפתיו של העגל, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003בדוקין\u0004 (בעפעפיים) \u0003שבעין,\u0004 \u0003דוכתא דלדידן הוה מומא\u0004 \u0005[מקום שבשבילנו הוא\u0006 נחשב ל\u0005מום]\u0006 \u0003ולדידהו לאו מומא הוא\u0004 \u0005[ולהם,\u0006 לדעת הגויים, \u0005אינו מום]\u0006 ולכן כשהביא אותו לא יכלו להקריב אותו במקדש, משום שהוא בעל מום, ולא יכלו להסביר למלכות שהוא בעל מום מפני שבעיני הגויים הוא לא נחשב למום.","\u0003סבור רבנן לקרוביה\u0004 \u0005[חשבו חכמים להקריב אותו]\u0006 בכל זאת \u0003משום שלום מלכות. אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' זכריה בן אבקולס,\u0004 אם כך, \u0003י אמרו\u0004 האנשים מעתה: \u0003בעלי מומין קריבין לגבי מזבח!\u0004 אמרו החכמים: אם כן, אם לא נקריב אותו, צריך לעשות משהו ביחס לבר קמצא, \u0003סבור\u0004 \u0005[[חשבו]\u0006 חכמים \u0003למיקטליה\u0004 \u0005[להרוג אותו]\u0006 כדי ש\u0003לא ליזיל ולימא\u0004 \u0005[ילך ויאמר]\u0006 למלכות. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' זכריה, י אמרו\u0004 האנשים מעתה שמי ש\u0003מטיל מום בקדשים יהרג!\u0004 וכיון שכך, לא עשו דבר, ונתקבלה ההלשנה על ידי המלכות, והתחילה המלחמה.","\u0003אמר ר' יוחנן: ענוותנותו\u0004 (יראת השמים, צדקותו) \u0003של ר' זכריה בן אבקולס,\u0004 היא ש\u0003החריבה את ביתנו, ושרפה את היכלנו, והגליתנו מארצנו.\u0004","\u0003שדר עלוייהו\u0004 \u0005[שלח עליהם]\u0006 את \u0003נירון קיסר. כי קאתי\u0004 \u0005[כאשר בא]\u0006 לירושלים רצה לנסות בגורל, \u0003שדא גירא\u0004 \u0005[זרק חץ]\u0006 \u0003למזרח\u0004 — \u0003אתא\u0004 \u0005[בא]\u0006 החץ ו\u0003נפל ב\u0004כיוון \u0003ירושלים,\u0004 זרק \u0003למערב\u0004 — \u0003אתא\u0004 \u0005[בא]\u0006 \u0003נפל בירושלים,\u0004 וכך עשה \u0003ל\u0004כל \u0003ארבע רוחות השמים\u0004 — ובכל פעם \u0003אתא\u0004 \u0005[בא]\u0006 ו\u0003נפל\u0004 החץ \u0003בירושלים.\u0004","ניסה עוד גורל: \u0003אמר ליה לינוקא\u0004 \u0005[אמר לו לתינוק]:\u0006 \u0003פסוק לי פסוקיך\u0004 שלמדת היום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 את הפסוק: \u0003\"ונתתי את נקמתי באדם ביד עמי ישראל\"\u0004 (יחזקאל כה, יד). \u0003אמר\u0004 נירון: \u0003קודשא בריך הוא בעי לחרובי ביתיה\u0004 \u0005[הקדוש ברוך הוא רוצה להחריב\u0006 את \u0005ביתו],\u0006 \u0003ובעי לכפורי ידיה בההוא גברא\u0004 \u0005[ו\u0006הוא \u0005רוצה לקנח\u0006 את \u0005ידיו באיש הזה,\u0006 בי\u0005],\u0006 שלבסוף איענש על שהייתי השליח לעשות זאת. \u0003ערק ואזל ואיגייר\u0004 \u0005[ברח והלך והתגייר],\u0006 \u0003ונפק מיניה\u0004 \u0005[ויצא ממנו]\u0006 לבסוף \u0003ר' מאיר.\u0004","\u0003שדריה עילוייהו\u0004 \u0005[שלח עליהם]\u0006 את \u0003אספסיינוס קיסר. אתא, צר עלה תלת שני\u0004 \u0005[בא, צר עליה\u0006 על ירושלים \u0005שלוש שנים].\u0006 \u0003הוו\u0004 \u0005[היו]\u0006 \u0003בה,\u0004 בירושלים, \u0003הנהו תלתא עתירי\u0004 \u0005[שלושה עשירים אלה]:\u0006 \u0003נקדימון בן גוריון, ובן כלבא שבוע, ובן ציצית הכסת.\u0004 ומסבירים את שמותיהם: \u0003נקדימון בן גוריון\u0004 — \u0003שנקדה לו חמה בעבורו,\u0004 כמסופר, שזרחה לו השמש שלא בזמנה כדי להצילו מהפסד גדול. \u0003בן כלבא שבוע\u0004 — כך קראו לו, \u0003שכל הנכנס לביתו כשהוא רעב ככלב, יוצא כשהוא שבע. בן ציצית הכסת\u0004 — \u0003שהיתה ציצתו נגררת על גבי כסתות,\u0004 שלא היה הולך ברחוב על הארץ אלא היו שמים לפניו כסתות. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003שהיתה כסתו מוטלת בין גדולי רומי,\u0004 שהיה יושב ביניהם.","ועשירים אלה התנדבו לעזור, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא זיינא להו בחיטי ושערי\u0004 \u0005[אני אזון אותם,\u0006 את בני העיר, \u0005בחיטים ושעורים],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 אני אזון אותם \u0003בדחמרא ובדמלחא ומשחא\u0004 \u0005[ביין ובמלח ובשמן],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בדציבי\u0004 \u0005[בעצים]\u0006 שאספק לכולם. ומעירים: \u0003ושבחו רבנן לדציבי\u0004 \u0005[ושיבחו חכמים את\u0006 זה שנתן \u0005עצים]\u0006 שזו הוצאה גדולה מאד. ש\u0003רב חסדא כל אקלידי הוה מסר לשמעיה\u0004 \u0005[כל המפתחות של ביתו היה מוסר לשמשו],\u0006 \u0003בר מדציבי\u0004 \u0005[חוץ מ\u0006המפתח \u0005של\u0006 מחסן \u0005העצים]\u0006 שחשב שהוא חשוב ביותר. \u0003דאמר\u0004 [שכן היה \u0005אומר]\u0006 \u0003רב חסדא\u0004: \u0003אכלבא דחיטי בעי שיתין אכלבי דציבי\u0004 \u0005[מחסן אחד של חיטים צריך ששים מחסנים של עצים]\u0006 כדי לאפות אותם כראוי. \u0003הוה להו למיזן עשרים וחד שתא\u0004 \u0005[היה להם\u0006 במחסניהם מזון \u0005כדי לזון את הנצורים עשרים ואחת שנים].\u0006","\u0003הוו בהו הנהו בריוני\u0004 \u0005[היו בהם,\u0006 באנשי ירושלים, \u0005בריונים],\u0006 \u0003אמרו להו רבנן\u0004 \u0005[להם חכמים]:\u0006 \u0003ניפוק ונעביד שלמא בהדייהו\u0004 \u0005[נצא ונעשה שלום איתם,\u0006 עם הרומאים\u0005].\u0006 \u0003לא שבקינהו\u0004 \u0005[הניחו להם].\u0006 \u0003אמרו להו\u0004 \u0005[להם]\u0006 הבריונים: \u0003ניפוק ונעביד קרבא בהדייהו\u0004 \u0005[נצא ונעשה מלחמה איתם],\u0006 \u0003אמרו להו רבנן\u0004 \u0005[להם חכמים]:\u0006 \u0003לא מסתייעא מילתא\u0004 \u0005[יסתייע הדבר]\u0006 ומוטב שנחכה עד שיסור המצור. \u0003קמו קלנהו להנהו אמברי דחיטי ושערי, והוה כפנא\u0004 \u0005[עמדו\u0006 הבריונים \u0005שרפו את המחסנים הללו של החיטים והשעורים, ונהיה רעב]\u0006 ועשו זאת כדי להכריח את האנשים לצאת למלחמה.","ועל רעב זה מסופר: אשה אחת ושמה \u0003מרתא בת בייתוס עתירתא\u0004 \u0005[עשירה]\u0006 שב\u0003ירושלים הויא\u0004 \u0005[היתה].\u0006 \u0003שדרתה\u0004 \u0005[שלחה]\u0006 \u0003לשלוחה ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי סמידא\u0004 \u0005[סולת].\u0006 \u0003אדאזל איזדבן\u0004 \u0005[עד שהלך נמכרה\u0006 הסולת\u0005].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אמר לה: סמידא ליכא, חיורתא איכא\u0004 \u0005[סולת אין, קמח יש],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי\u0004 קמח. \u0003אדאזל אזדבן\u0004 \u0005[עד שהלך נמכר\u0006 הקמח\u0005].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ואמר לה: חיורתא ליכא, גושקרא איכא\u0004 \u0005[קמח אין, סובין יש].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי.\u0004 \u0003אדאזל אזדבן\u0004 \u0005[עד שהלך נמכר]\u0006 גם זה. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ואמר לה: גושקרא ליכא, קימחא דשערי איכא\u0004 \u0005[סובין אין, קמח שעורים יש].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי\u0004 קמח שעורים. \u0003אדאזל איזדבן\u0004 \u0005[עד שהלך נמכר]\u0006 גם זה.","\u0003הוה שליפא מסאנא\u0004 \u0005[היתה חלוצת נעל,\u0006 יחפה\u0005]\u0006 באותה שעה, \u0003אמרה: איפוק ואחזי אי משכחנא מידי למיכל\u0004 \u0005[אצא ואראה אם אמצא דבר\u0006 מה \u0005לאכול],\u0006 \u0003איתיב לה פרתא בכרעא\u0004 \u0005[התיישב לה גלל ברגלה]\u0006 \u0003ומתה,\u0004 מכיון שהיתה כל כך מפונקת והגועל גרם לה למות.","\u0003קרי עלה\u0004 \u0005[קרא עליה]\u0006 \u0003רבן יוחנן בן זכאי\u0004 כתוב זה שבפרשת הקללות שבתורה: \u0003\"הרכה בך והענגה אשר לא נסתה כף רגלה\u0004 הצג על הארץ מהתענג ומרוך\u0003\"\u0004 (דברים כח, נו). \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 לא גלל היה זה, אלא \u0003גרוגרות\u0004 של \u0003ר' צדוק אכלה, ואיתניסא\u0004 \u0005[ונאנסה,\u0006 חלתה\u0005]\u0006 \u0003ו\u0004מחמת גועל \u0003מתה.\u0004 ומה הן הגרוגרות הללו? — ש\u0003ר' צדוק יתיב ארבעין שנין בתעניתא\u0004 \u0005[ישב ארבעים שנים בתענית]\u0006 ובתפילה ש\u0003לא ליחרב\u0004 \u0005[תחרב]\u0006 \u0003ירושלים,\u0004 וכל כך רזה גופו מן התעניות \u0003כי הוה אכיל מידי הוה מיתחזי מאבראי\u0004 \u0005[שכאשר היה אוכל דבר היה נראה\u0006 בולט \u0005מבחוץ].\u0006 \u0003וכי הוה בריא, מייתי ליה\u0004 \u0005[וכאשר היה אוכל\u0006 לאחר הצום, היו \u0005מביאים לו]\u0006 \u0003גרוגרות, מייץ מייהו ושדי להו\u0004 \u0005[\u0006היה \u0005מוצץ\u0006 את \u0005מימיהן וזורק אותן],\u0006 וזוהי הגרוגרת שמצאה מרתא בת בייתוס.","מספרים: \u0003כי הוה קאי ניחא נפשה\u0004 \u0005[כאשר מתה],\u0006 \u0003אפיקתא לכל דהבא וכספא\u0004 \u0005[הוציאה את כל הזהב והכסף]\u0006 שלה \u0003שדיתיה בשוקא\u0004 \u0005[זרקה אותו בשוק],\u0006 \u0003אמרה: האי למאי מיבעי לי\u0004 \u0005[זה למה אני צריכה]!\u0006 \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"כספם בחוצות ישליכו\u0004... לא יוכל להצילם ביום עברת ה', נפשם לא ישבעו ומעיהם לא ימלאו\u0003\"\u0004 (יחזקאל ז, יט).","מסופר: \u0003אבא סקרא ריש בריוני\u0004 \u0005[ראש הבריונים]\u0006 של \u0003ירושלים, בר אחתיה\u0004 \u0005[בן אחותו]\u0006 של \u0003רבן יוחנן בן זכאי הוה\u0004 \u0005[היה],\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 רבן יוחנן בן זכאי: \u0003תא בצינעא לגבאי\u0004 \u0005[בוא בחשאי אלי].\u0006 \u0003אתא\u0004 \u0005[בא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן יוחנן בן זכאי: \u0003עד אימת עבדיתו הכי, וקטליתו ליה לעלמא בכפנא\u0004 \u0005[עד מתי אתם עושים כך, והורגים את העולם ברעב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבא סיקרא: \u0003מאי איעביד\u0004 \u0005[מה אעשה],\u0006 \u0003דאי אמינא להו מידי קטלו לי\u0004 \u0005[שאם אומר להם דבר יהרגו אותי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי לי תקנתא לדידי דאיפוק\u0004 \u0005[ראה\u0006 איזו \u0005תקנה בשבילי שאני אצא]\u0006 מחוץ לעיר, \u0003אפשר\u0004 על ידי כך \u0003דהוי\u0004 \u0005[שתהא]\u0006 \u0003הצלה פורתא\u0004 \u0005[מעטה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אבא סיקרא: כך תעשה ותצא מן העיר: \u0003נקוט נפשך בקצירי\u0004 \u0005[עשה עצמך חולה],\u0006 \u0003וליתי כולי עלמא ולישיילו\u0004 \u0005[ויבואו הכל וישאלו]\u0006 \u0003בך\u0004 לשלומך, כבחולה, שיתפרסם הדבר, \u0003ו\u0004אחר כך \u0003אייתי מידי סריא ואגני גבך\u0004 \u0005[הבא דבר מסריח והשכב לידך],\u0006 \u0003ולימרו דנח נפשך\u0004 \u0005[ושיאמרו שמתת]\u0006 ומסריח כבר, \u0003וליעיילו בך תלמידך\u0004 \u0005[ויכנסו אצלך,\u0006 להוציאך, \u0005תלמידיך]\u0006 \u0003ולא ליעול בך איניש אחרינא\u0004 \u0005[יכנס אצלך איש אחר]\u0006 כדי ש\u0003לא לרגשן\u0004 \u0005[ירגישו]\u0006 \u0003בך דקליל את\u0004 \u0005[שאתה קל],\u0006 \u0003דאינהו ידעי דחייא קליל ממיתא\u0004 \u0005[שהם,\u0006 הבריונים \u0005יודעים ש\u0006אדם \u0005חי קל ממת].\u0006","\u0003עביד הכי\u0004 \u0005[עשה\u0006 רבן יוחנן \u0005כך],\u0006 \u0003נכנס בו\u0004 מתחת למיטתו כדי לנושאה \u0003ר' אליעזר מצד אחד ור' יהושע מצד אחר, כי מטו לפיתחא\u0004 \u0005[כאשר באו לפתח\u0006 העיר\u0005]\u0006 \u0003בעו למדקריה\u0004 \u0005[רצו\u0006 השומרים \u0005לדקור אותו]\u0006 כדי לבדוק אם באמת מת הוא, שכן היו עושים. \u0003אמר להו\u0004 \u0005[להם]\u0006 אבא סיקרא: \u0003יאמרו\u0004 הרומאים: \u0003רבן דקרו,\u0004 כלומר, אפילו את רבם הם דוקרים! \u0003בעו למדחפיה\u0004 \u0005[רצו לדחוף אותו]\u0006 לבדוק אולי חי הוא ויצעק מחמת הדחיפה. \u0003אמר להו\u0004 \u0005[להם]\u0006 אבא סיקרא: \u0003יאמרו: רבן דחפו! פתחו ליה בבא, נפק\u0004 \u0005[פתחו לו\u0006 את \u0005השער, יצא],\u0006 כלומר, הוציאו אותו.","\u0003כי מטא להתם\u0004 \u0005[כאשר הגיע רבן יוחנן לשם]\u0006 למחנה הרומאים, \u0003אמר\u0004 לאספסיינוס: \u0003\"שלמא עלך מלכא, שלמא עלך מלכא\"\u0004 \u0005[שלום עליך המלך, שלום עליך המלך]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אספסיינוס: \u0003מיחייבת תרי קטלא\u0004 \u0005[מחויב אתה שתי מיתות],\u0006 \u0003חדא, דלאו מלכא אנא וקא קרית לי מלכא\u0004 \u0005[אחת, שאין אני מלך ואתה קורא לי מלך]!\u0006 \u0003ותו, אי מלכא אנא, עד האידנא אמאי לא אתית לגבאי\u0004 \u0005[ועוד, אם מלך אני, עד עכשיו מדוע לא באת אלי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן יוחנן בתשובה לשאלותיו: \u0003דקאמרת \"לאו מלכא אנא\"\u0004 \u0005[מה שאמרת \"אין אני מלך\"]\u0006 —"],["\u0003איברא מלכא את\u0004 \u0005[אמנם מלך אתה]\u0006 ואם לא עכשיו, תהיה מלך בעתיד, \u0003דאי לאו מלכא את\u0004 \u0005[שאם לא מלך אתה]\u0006 \u0003לא מימסרא\u0004 \u0005[נמסרת]\u0006 \u0003ירושלים בידך,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והלבנון באדיר יפול\"\u0004 (ישעיה י, לד), \u0003ואין \"אדיר\" אלא מלך, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה אדירו ממנו\u0004 ומושלו מקרבו יצא\u0003\"\u0004 (ירמיה ל, כא), הרי ש\"אדיר\" מקביל למושל. \u0003ואין \"לבנון\" אלא בית המקדש, שנאמר: \"ההר הטוב הזה והלבנון\"\u0004 (דברים ג, כה). \u0003ודקאמרת\u0004 \u0005[ומה שאתה אומר\u0006 בשאלתך השניה\u0005]:\u0006 \u0003אי מלכא אנא, אמאי\u0004 \u0005[אם מלך אני, מדוע]\u0006 \u0003לא קאתית לגבאי\u0004 \u0005[באת אלי]\u0006 \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 — \u0003בריוני דאית בן\u0004 \u0005[הבריונים שיש בנו]\u0006 \u0003לא שבקינן\u0004 \u0005[הניחו לנו]\u0006 לעשות כן.","הבין אספסיינוס כי רבן יוחנן מבקש ממנו שלא להחריב את ירושלים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אספסיינוס לרבן יוחנן: \u0003אילו\u0004 יש לאנשים \u0003חבית של דבש ודרקון\u0004 (נחש) \u0003כרוך עליה, לא היו שוברין את החבית בשביל\u0004 (בגלל) \u0003דרקון\u0004 כדי להמיתו? כך צריך אני להחריב את העיר על מנת להרוג את הבריונים שבתוכה. \u0003אישתיק\u0004 \u0005[שתק]\u0006 רבן יוחנן ולא ענה. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רב יוסף, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' עקיבא,\u0004 שנתקיים בו ברבן יוחנן הכתוב: \u0003\"משיב חכמים אחור ודעתם יסכל\"\u0004 (ישעיה מד, כה), שכן \u0003איבעי ליה למימר ליה\u0004 \u0005[היה צריך לומר לו]\u0006 כך בתשובה: \u0003שקלינן צבתא ושקלינן ליה לדרקון וקטלינן ליה, וחביתא שבקינן לה\u0004 \u0005[לוקחים אנו צבת, ונוטלים אנו אותו, את הדרקון, והורגים אותו, ואת החבית משאירים אותה\u0006 שלימה\u0005]\u0006 וכך צריך היה לעשות, להרוג את המורדים ולהשאיר את העיר.","\u0003אדהכי\u0004 \u0005[בינתיים,\u0006 בתוך כדי שיחתם\u0005]\u0006 \u0003אתי פריסתקא עליה\u0004 \u0005[בא שליח עליו]\u0006 \u0003מרומי,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 השליח: \u0003קום, דמית ליה\u0004 \u0005[שמת לו]\u0006 ה\u0003קיסר, ואמרי הנהו חשיבי דרומי לאותיבך ברישא\u0004 \u0005[ואומרים,\u0006 מתכוונים, \u0005אותם חשובי רומי להושיבך בראש]\u0006 ולעשותך קיסר. באותה שעה \u0003הוה סיים חד מסאני\u0004 \u0005[היה\u0006 אספסיינוס \u0005נעול נעל אחת],\u0006 \u0003בעא למסיימא לאחרינא\u0004 \u0005[רצה לנעול את האחרת]\u0006 \u0003לא עייל\u0004 \u0005[נכנסה]\u0006 לרגלו. \u0003בעא למשלפא לאידך\u0004 \u0005[רצה לחלוץ את\u0006 הנעל \u0005האחרת]\u0006 שהיה נעול בה, \u0003לא נפק\u0004 \u0005[יצאה].\u0006 \u0003אמר: מאי האי\u0004 \u0005[מה זאת]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן יוחנן: \u0003לא תצטער\u0004 ותתמה, כי \u0003שמועה טובה אתיא\u0004 \u0005[באה]\u0006 \u0003לך,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שמועה טובה תדשן עצם\"\u0004 (משלי טו, ל) ושמנת מחמת נחת. ושאל: \u0003אלא מאי תקנתיה\u0004 \u0005[מה תקנתו],\u0006 מה אני צריך לעשות כדי לחלוץ את הנעל? אמר לו: \u0003ליתי איניש\u0004 \u0005[שיבוא אדם]\u0006 ש\u0003לא מיתבא\u0004 \u0005[נוחה]\u0006 \u0003דעתך מיניה\u0004 \u0005[ממנו]\u0006 \u0003ולחליף קמך\u0004 \u0005[ויעבור לפניך],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ורוח נכאה תיבש גרם\u0004 (עצם)\u0003\"\u0004 (משלי יז, כב). \u0003עבד הכי, עייל\u0004 \u0005[עשה כן, ונכנסה\u0006 רגלו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אספסיינוס: \u0003ומאחר דחכמיתו כולי האי\u0004 \u0005[שאתם חכמים כל כך],\u0006 \u0003עד האידנא אמאי\u0004 \u0005[עד עכשיו מדוע]\u0006 \u0003לא אתיתו לגבאי\u0004 \u0005[באתם אלי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן יוחנן: \u0003ו\u0004כי \u0003לא אמרי\u0004 \u0005[אמרתי]\u0006 \u0003לך\u0004 כבר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא נמי אמרי\u0004 \u0005[אני גם כן אמרתי]\u0006 לך מה שיש בידי לומר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אספסיינוס: \u0003מיזל אזילנא\u0004 \u0005[הולך אני]\u0006 לרומי לקבלת תפקיד הקיסר, \u0003ואינש אחרינא משדרנא\u0004 \u0005[ואדם אחר אשלח\u0006 במקומי\u0005]\u0006 להמשיך במצור על העיר והמלחמה בה, \u0003אלא בעי מינאי מידי\u0004 \u0005[בקש ממני דבר]\u0006 ש\u0003אתן לך.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תן לי יבנה וחכמיה,\u0004 שלא תחריב אותה, \u0003ושושילתא\u0004 \u0005[ו\u0006את \u0005שושלת]\u0006 \u0003רבן גמליאל\u0004 שתשאירם חיים ולא תהרגם כדין מורדים, \u0003ו\u0004עוד תן לי \u0003אסוותא דמסיין ליה\u0004 \u0005[רופאים שירפאו אותו],\u0006 את \u0003ר' צדוק. קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רב יוסף, ואתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' עקיבא,\u0004 את הפסוק: \u0003\"משיב חכמים אחור ודעתם יסכל\"\u0004 (ישעיה מד, כה), שכן \u0003איבעי למימר ליה לשבקינהו הדא זימנא\u0004 \u0005[היה צריך לומר לו שיניח להם בפעם הזאת].\u0006","ומסבירים: \u0003והוא,\u0004 רבן יוחנן בן זכאי מדוע לא עשה כן? — \u0003סבר, דלמא כולי האי לא עביד\u0004 \u0005[שמא כל כך לא יעשה\u0006 בשבילו\u0005],\u0006 \u0003והצלה פורתא\u0004 \u0005[מעטה]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא הוי\u0004 \u0005[תהיה],\u0006 ולכן ביקש דבר מועט שלפחות אותו יוכל לקבל.","ושואלים: \u0003אסוותא דמסיין ליה\u0004 \u0005[רופאים שירפאו אותו]\u0006 את \u0003ר' צדוק מאי היא\u0004 \u0005[מה הוא]?\u0006 כיצד ריפאוהו? — \u0003יומא קמא אשקיוה מיא דפארי\u0004 \u0005[יום ראשון השקו אותו מי סובין],\u0006 \u0003ל\u0004יום ה\u0003מחר\u0004 השקוהו \u0003מיא דסיפוקא\u0004 \u0005[מים עם קמח מעורב בסובין],\u0006 \u0003ל\u0004יום ה\u0003מחר\u0004 השקוהו \u0003מיא דקימחא\u0004 \u0005[מים עם קמח],\u0006 \u0003עד דרווח מיעיה פורתא פורתא\u0004 \u0005[שהתרווחו מעיו מעט מעט],\u0006 שאם היה מתחיל לאכול מיד אכילה של ממש, היה מת מכך.","\u0003אזל\u0004 \u0005[הלך]\u0006 אספסיינוס ובמקומו \u0003שדריה\u0004 \u0005[שלח אותו]\u0006 את \u0003טיטוס.\u0004 ומביאים את מה שדרשו על טיטוס: \u0003\"ואמר אי אלהימו צור חסיו בו\"\u0004 (דברים לב, לז) — \u0003זה טיטוס הרשע שחירף וגידף כלפי מעלה.\u0004","\u0003מה עשה\u0004 כשכבש את בית המקדש — \u0003תפש זונה בידו ונכנס\u0004 עימה \u0003לבית קדשי הקדשים, והציע ספר תורה\u0004 תחתיו \u0003ועבר עליה עבירה\u0004 עם הזונה, \u0003ו\u0004אחר כך \u0003נטל סייף\u0004 (חרב) \u0003וגידר\u0004 (דקר) \u0003את הפרוכת, ונעשה נס והיה דם מבצבץ ויוצא, כסבור הרג את עצמו,\u0004 כלומר, חשב שכביכול הרג את הקדוש ברוך הוא, שהרי יוצא דם, שנאמר: \u0003\"שאגו צרריך בקרב מועדיך\u0004 (בית המקדש) \u0003שמו אותתם\u0004 (את סימניהם) \u0003אתות\"\u0004 (תהלים עד, ד), שסימן שעשה טיטוס בדקירת הפרוכת שמצליחים מעשיו, כאילו נתקיים.","\u0003אבא חנן אומר,\u0004 נאמר: \u0003\"מי כמוך חסין יה\"\u0004 (תהלים פט, ט), \u0003מי כמוך חסין\u0004 (חזק) \u0003וקשה, שאתה שומע ניאוצו וגידופו של אותו רשע ושותק. דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 את הפסוק \u0003\"מי כמוכה באלם ה'\"\u0004 (שמות טו, יא) צריך לקרוא: \u0003מי כמוכה באלמים,\u0004 שאתה נוהג כאילם ושותק לגידופך.","\u0003מה\u0004 עוד \u0003עשה\u0004 טיטוס? — \u0003נטל את הפרוכת ועשאו כמין גרגותני\u0004 (סל גדול), \u0003והביא\u0004 את \u0003כל\u0004 ה\u0003כלים שבמקדש והניחן בהן, והושיבן בספינה לילך להשתבח בעירו\u0004 שכבש את ירושלים, \u0003שנאמר: \"ובכן ראיתי רשעים קברים ובאו וממקום קדוש יהלכו וישתכחו בעיר אשר כן עשו\"\u0004 (קהלת ח, י), \u0003אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"קבורים\" אלא \"קבוצים\",\u0004 שמקבצים ואוספים דברים, ומבית המקדש (\"ממקום קדוש\") הולכים, ומשתבחים בעירם על אשר עשו. \u0003אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"וישתכחו\" אלא \"וישתבחו\".\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאין צורך לשנות, אלא \u0003קבורים ממש,\u0004 ש\u0003אפילו מילי דמטמרן איגלייא להון\u0004 \u0005[דברים שטמונים ניגלו להם]\u0006 ומצאו את כל הכלים.","עוד מסופר בטיטוס: כשנסע בים \u0003עמד עליו נחשול\u0004 (גל) \u0003שבים לטובעו, אמר\u0004 טיטוס: \u0003כמדומה אני שאלהיהם של אלו,\u0004 של ישראל, \u0003אין גבורתו אלא במים, בא פרעה\u0004 עליהם — \u0003טבעו במים, בא סיסרא\u0004 — \u0003טבעו במים, אף הוא עומד עלי לטובעני במים. אם גבור הוא יעלה ליבשה ויעשה עמי מלחמה! יצתה בת קול ואמרה לו: רשע בן רשע בן בנו של עשו הרשע,\u0004 שאתה מצאצאיו שנוהג כמותו, \u0003בריה קלה יש לי בעולמי ויתוש שמה,\u0004 ומסבירים:","\u0003אמאי קרי\u0004 \u0005[מדוע קוראים]\u0006 \u0003לה \"בריה קלה\"?\u0004 — \u0003דמעלנא אית\u0004 \u0005[שכניסה,\u0006 לאכול, \u0005יש]\u0006 \u0003לה, ומפקנא לית\u0004 \u0005[והוצאה אין]\u0006 \u0003לה,\u0004 אינה מוציאה רעי.","\u0003עלה ליבשה ותעשה עמה מלחמה. עלה ליבשה, בא יתוש ונכנס בחוטמו, ונקר במוחו שבע שנים\u0004 והיה טיטוס סובל יסורים. \u0003יומא חד הוה קא חליף אבבא דבי נפחא\u0004 \u0005[יום אחד עבר על פתח של בית הנפח],\u0006 \u0003שמע\u0004 היתוש \u0003קל ארזפתא\u0004 \u0005[\u0006את \u0005קול המקבת],\u0006 \u0003אישתיק\u0004 \u0005[השתתק]\u0006 ונח היתוש, \u0003אמר\u0004 טיטוס: \u0003איכא תקנתא\u0004 \u0005[יש תקנה]\u0006 לכאבי. \u0003כל יומא מייתו נפחא ומחו קמיה\u0004 \u0005[כל יום היו מביאים נפח והיו מכים לפניו],\u0006 \u0003ל\u0004נפח \u0003גוי יהיב ליה ארבע זוזי\u0004 \u0005[\u0006היה \u0005נותן לו ארבעה דינרים]\u0006 בשכרו, ו\u0003ל\u0004נפח \u0003ישראל אמר ליה\u0004 \u0005[היה אומר לו]:\u0006 \u0003מיסתייך דקא חזית בסנאך\u0004 \u0005[דייך שאתה רואה בשונאך]\u0006 שהוא מתייסר כך. \u0003עד תלתין יומין עבד הכי\u0004 \u0005[שלושים יום עשה כך]\u0006 והועיל לו, \u0003מכאן ואילך כיון דדש, דש\u0004 \u0005[שהתרגל\u0006 היתוש, \u0005התרגל]\u0006 והמשיך לנקר בו, ולא הועילו עוד ההכאות של הנפחים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' פנחס בן ערובא: אני הייתי בין גדולי רומי\u0004 אותה שעה, \u0003וכשמת\u0004 טיטוס \u0003פצעו\u0004 (פתחו) \u0003את מוחו, ומצאו בו\u0004 שהיתוש גדל והיה \u0003כ\u0004גודל \u0003צפור דרור משקל שני סלעים. במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003כגוזל בן שנה\u0004 שהיה \u0003משקל שני ליטרין\u0004 (ליטרות).","\u0003אמר אביי, נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 ש\u0003פיו\u0004 היה \u0003של נחושת וצפורניו של ברזל. כי הוה קא מיית\u0004 \u0005[כאשר מת]\u0006 טיטוס, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ליקליוה לההוא גברא\u0004 \u0005[שישרפו את האיש הזה,\u0006 אותי\u0005]\u0006 \u0003ולבדרי לקיטמיה אשב ימי\u0004 \u0005[ושיפזרו את אפרו על פני שבעה ימים],\u0006 \u0003דלא לשכחיה אלהא דיהודאי ולוקמיה בדינא\u0004 \u0005[\u0006כדי \u0005שלא ימצא אותו אלוהי היהודים ויעמידנו בדין].\u0006","מסופר: \u0003אונקלוס בר קלוניקוס בר אחתיה\u0004 \u0005[בן אחותו]\u0006 של \u0003טיטוס הוה\u0004 \u0005[היה],\u0006 \u0003בעי לאיגיורי\u0004 \u0005[רצה להתגייר],\u0006 \u0003אזל אסקיה לטיטוס בנגידא\u0004 \u0005[הלך העלה את טיטוס באוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אונקלוס: \u0003מאן חשיב בההוא עלמא\u0004 \u0005[מי חשוב בעולם ההוא]\u0006 שאתה בו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ישראל.\u0004 שאל אותו אונקלוס \u0003: מהו לאידבוקי בהו\u0004 \u0005[האם להידבק בהם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 טיטוס: \u0003מילייהו נפישין\u0004 \u0005[דבריהם,\u0006 מצוותיהם, \u0005מרובים],\u0006 \u0003ולא מצית לקיומינהו\u0004 \u0005[תוכל לקיים אותן],\u0006 מוטב שכך תעשה: \u0003זיל איגרי בהו בההוא עלמא והוית רישא\u0004 \u0005[לך התגרה בהם מלחמה בעולם ההוא,\u0006 עולמנו שלנו, \u0005ותהיה ראש],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"היו צריה\u0004 (של ירושלים) \u0003לראש\"\u0004 (איכה א, ה), לומר: \u0003כל המיצר לישראל נעשה ראש. אמר ליה\u0004 \u0005[לו]\u0006 ושאל אותו אונקלוס עוד: \u0003דיניה דההוא גברא במאי\u0004 \u0005[דינו,\u0006 עונשו \u0005של אותו האיש,\u0006 אותך, \u0005במה\u0006 הוא\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003במאי דפסיק אנפשיה\u0004 \u0005[במה שפסק\u0006 דין הוא \u0005על עצמו],\u0006 וכך עושים: \u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003מכנשי ליה לקיטמיה\u0004 \u0005[אוספים אותו, את אפרו]\u0006 \u0003ודייני ליה\u0004 \u0005[ודנים אותו]\u0006 \u0003וקלו ליה ומבדרו אשב ימי\u0004 \u0005[ושורפים אותו ומפזרים אותו על\u0006 פני \u0005שבעה ימים].\u0006","אחר כך \u0003אזל אסקיה לבלעם בנגידא\u0004 \u0005[הלך\u0006 אונקלוס \u0005העלה את בלעם באוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן חשיב בההוא עלמא\u0004 \u0005[מי חשוב באותו עולם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ישראל.\u0004 שאל אותו: \u0003מהו לאידבוקי בהו\u0004 \u0005[האם להידבק בהם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"לא תדרש שלומם וטובתם כל הימים\"\u0004 (כעין לשון הכתוב דברים כג, ז). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דיניה דההוא גברא במאי\u0004 \u0005[דינו,\u0006 עונשו \u0005של אותו אדם,\u0006 שלך, \u0005במה\u0006 הוא\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בשכבת זרע רותחת\u0004 מבשלים אותו, משום שחטא בזנות וגרם לישראל לזנות.","אחר כך \u0003אזל\u0004 \u0005[הלך]\u0006 אונקלוס \u0003אסקיה בנגידא\u0004 \u0005[העלה באוב]\u0006 את \u0003ישו הנוצרי,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אונקלוס: \u0003מאן חשיב בההוא עלמא\u0004 \u0005[מי חשוב באותו עולם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ישראל.\u0004 שאל אותו \u0003מהו לאידבוקי בהו\u0004 \u0005[האם להידבק בהם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003טובתם דרוש, רעתם לא תדרוש, כל הנוגע בהן כאילו נוגע בבבת עינו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דיניה דההוא גברא במאי\u0004 \u0005[דינו\u0006 עונשו \u0005של אותו אדם,\u0006 שלך, \u0005במה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בצואה רותחת. דאמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל המלעיג על דברי חכמים נידון בצואה רותחת\u0004 וזה היה חטאו, שליגלג על דברי חכמים. ומעירים: \u0003תא חזי\u0004 \u0005[בוא\u0006 ו\u0005ראה]\u0006 \u0003מה בין פושעי ישראל לנביאי אומות העולם?\u0004 שבלעם שהיה נביא כך יעץ, וישו הנוצרי שהיה מפושעי ישראל דיבר בטובתם.","ובסיכום הסיפור שסיפרנו שבגלל קמצא ובר קמצא חרבה ירושלים \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' אלעזר: בא וראה כמה גדולה כחה של בושה, שהרי סייע הקדוש ברוך הוא את בר קמצא\u0004 שביישוהו, \u0003והחריב\u0004 בגלל זה \u0003את ביתו\u0004 שלו, בית המקדש, \u0003ושרף את היכלו.\u0004","אמרנו בתחילה ש\u0003אתרנגולא ואתרנגולתא חריב טור מלכא\u0004 \u0005[על תרנגול ותרנגולת חרב הר המלך].\u0006 ופרטי המעשה כך הם: \u0003דהוו נהיגי\u0004 \u0005[שהיו נוהגים]\u0006 שם \u0003כי הוו מפקי חתנא וכלתא, מפקי קמייהו תרנגולא ותרנגולתא\u0004 \u0005[כאשר היו מוציאים חתן וכלה\u0006 לחתונה, \u0005היו מוציאים לפניהם תרנגול ותרנגולת],\u0006 \u0003כלומר,\u0004 לסימן: \u0003פרו ורבו כתרנגולים.\u0004","\u0003יומא חד הוה קא חליף גונדא דרומאי\u0004 \u0005[יום אחד עבר שם גדוד של רומאים],\u0006 והיה זה בעת חתונה, \u0003שקלינהו\u0004 \u0005[לקחו]\u0006 הרומאים את התרנגולים \u0003מינייהו\u0004 \u0005[מהם],\u0006 \u0003נפלו עלייהו מחונהו\u0004 \u0005[התנפלו עליהם\u0006 בני העיר ו\u0005היכו אותם],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לקיסר: מרדו בך יהודאי\u0004 \u0005[היהודים]!\u0006 \u0003אתא עלייהו\u0004 \u0005[בא עליהם\u0006 במלחמה\u0005].\u0006 \u0003הוה בהו\u0004 \u0005[היה בהם]\u0006 בין יושבי טור מלכא \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 שקראו לו \u0003בר דרומא, דהוה קפיץ מילא וקטיל בהו\u0004 \u0005[שהיה קופץ\u0006 מרחק \u0005מיל והורג בהם\u0006 ברומאים\u0005]\u0006 ולא היו אלה יכולים לעשות דבר נגדו, \u0003שקליה\u0004 \u0005[לקחו]\u0006 ה\u0003קיסר לתאגיה ואותביה אארעא\u0004 \u0005[את כתרו והניח אותו על הקרקע]\u0006 לאות אבל. \u0003אמר: ריבוניה דעלמא כוליה\u0004 \u0005[ריבונו של העולם כולו],\u0006 \u0003אי ניחא לך, לא תמסריה לההוא גברא לדידיה ולמלכותיה בידיה דחד גברא\u0004 \u0005[אם נוח לך, אל תמסור את האיש הזה עצמו,\u0006 אותי, \u0005ואת מלכותו בידי אדם אחד\u0006 בלבד\u0005]!\u0006","ובסופו של דבר \u0003אכשליה פומיה\u0004 \u0005[הכשיל אותו פיו]\u0006 \u0003לבר דרומא, ואמר\u0004 כתוב זה בלשון תרעומת כלפי ה': \u0003\"הלא אתה אלהים זנחתנו ולא תצא אלהים בצבאותינו\"\u0004 (תהלים ס, יב). ותוהים: \u0003דוד נמי אמר הכי\u0004 \u0005[גם כן אמר כך]!\u0006 ומשיבים: \u0003דוד אתמוהי קא מתמה\u0004 \u0005[בתמיהה הוא אומר]\u0006 ובר דרומא אמר זאת כקובע עובדות.","\u0003על\u0004 \u0005[נכנס]\u0006 בר דרומא \u0003לבית הכסא, אתא דרקונא שמטיה לכרכשיה ונח נפשיה\u0004 \u0005[בא נחש שמט את בני מעיו ומת].\u0006 \u0003אמר\u0004 הקיסר: \u0003הואיל ואיתרחיש\u0004 \u0005[והתרחש]\u0006 \u0003לי ניסא\u0004 \u0005[נס]\u0006 שלא מכוחי, \u0003הא זימנא אישבקינהו\u0004 \u0005[בפעם הזו אניח להם].\u0006 \u0003שבקינהו ואזל\u0004 \u0005[הניחם והלך].\u0006 \u0003איזדקור\u0004 \u0005[קפצו]\u0006 \u0003ואכלו ושתו, ואדליקו שרגי\u0004 \u0005[והדליקו נרות]\u0006 לשמחה, \u0003עד דאיתחזי בליונא דגושפנקא ברחוק מילא\u0004 \u0005[שהיתה נראית הדמות שבחותם במרחק מיל]\u0006 מרוב האור. \u0003אמר: מיחדא קא חדו בי יהודאי\u0004 \u0005[שמחים בי היהודים]!\u0006 \u0003הדר אתא עלייהו\u0004 \u0005[חזר\u0006 ו\u0005בא עליהם].\u0006","\u0003אמר רב אסי: תלת מאה אלפי שליפי סייפא עיילו לטור מלכא\u0004 \u0005[שלוש מאות אלף שולפי חרב נכנסו להר המלך],\u0006 \u0003וקטלו בה תלתא יומי ותלתא לילוותא\u0004 \u0005[והרגו בה שלושה ימים ושלושה לילות],\u0006 \u0003ובהך גיסא הלולי וחנגי\u0004 \u0005[ובאותו\u0006 הזמן \u0005בצד\u0006 אחד של הר המלך היו עדיין \u0005חתונות ושמחות],\u0006 \u0003ולא הוו ידעי הני בהני\u0004 \u0005[היו יודעים אלה באלה]\u0006 מרוב גודלו של המקום.","על הכתוב \u0003\"בלע ה' ולא חמל את כל נאות יעקב\"\u0004 (איכה ב, ב) מספרים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אלו ששים רבוא עיירות שהיו לו לינאי המלך בהר המלך.\u0004 ש\u0003אמר רב יהודה אמר רב אסי: ששים רבוא עיירות היו לו לינאי המלך בהר המלך, וכל אחת ואחת היו בה\u0004 תושבים \u0003כיוצאי מצרים, חוץ משלש\u0004 עיירות \u0003שהיו בהן כפלים כיוצאי מצרים.\u0004","ו\u0003אלו הן\u0004 העיירות: \u0003כפר ביש, כפר שיחליים, כפר דכריא.\u0004 ומסבירים את השמות המוזרים הללו: \u0003כפר ביש\u0004 \u0005[רע]\u0006 — ש\u0003לא יהבי ביתא לאושפיזא\u0004 \u0005[היו נותנים בית לאורח].\u0006 \u0003כפר שיחליים\u0004 — משום \u0003שהיתה פרנסתן מן שחליים. כפר דכריא\u0004 \u0005[זכרים]\u0006 — \u0003אמר ר' יוחנן: שהיו נשותיהן יולדות זכרים תחלה, ויולדות נקבה באחרונה ו\u0004אז \u0003פוסקות\u0004 מללדת,","ולכן קראו להם כפר זכרים. \u0003אמר עולא: לדידי חזי לי ההוא אתרא\u0004 \u0005[אני עצמי ראיתי את המקום ההוא],\u0006 \u0003ואפילו שיתין ריבוותא קני\u0004 \u0005[ששים רבוא קנים]\u0006 \u0003לא מחזיק\u0004 (מכיל), וכל שכן מספר כזה של אנשים. \u0003אמר ליה ההוא מינא\u0004 \u0005[אמר לו מין אחד]\u0006 \u0003לר' חנינא: שקורי משקריתו\u0004 \u0005[משקרים אתם]\u0006 שאתם מגזימים כך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"ארץ צבי\"\u0004 (ראה ירמיה ג, יט) \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003בה,\u0004 בארץ ישראל, \u0003מה צבי זה\u0004 — \u0003אין עורו מחזיק את בשרו,\u0004 שלאחר שפושטים אותו העור מתכווץ, \u0003אף ארץ ישראל\u0004 — \u0003בזמן שיושבין עליה רווחא\u0004 \u0005[\u0006היא \u0005מתרווחת],\u0006 \u0003ובזמן שאין יושבין עליה גמדא\u0004 \u0005[\u0006היא \u0005מתכווצת]\u0006 ולכן, אותו מקום שלפני החורבן הכיל מספר כה גדול של תושבים הינו קטן כל כך עכשיו.","מסופר: \u0003רב מניומי בר חלקיה ורב חלקיה בר טוביה ורב הונא בר חייא הוו יתבי גבי הדדי\u0004 \u0005[היו יושבים יחד],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אי איכא דשמיע ליה מילתא\u0004 \u0005[אם יש מישהו ששמע דבר]\u0006 \u0003מכפר סכניא של מצרים\u0004 שהיה באותו איזור, \u0003לימא\u0004 \u0005[שיספר].\u0006","\u0003פתח חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003ואמר: מעשה בארוס וארוסתו שנשבו לבין הגוים ו\u0004הגויים \u0003השיאום זה לזה, אמרה לו\u0004 הארוסה: \u0003\"בבקשה ממך, אל תגע בי, שאין לי כתובה ממך\",\u0004 שאין אנו נשואים עדיין, \u0003ולא נגע בה עד יום מותו.\u0004","\u0003וכשמת, אמרה להן,\u0004 לחכמים: \u0003סיפדו לזה,\u0004 לפי \u0003שפטפט\u0004 (ביזה, ליגלג על) \u0003יצרו יותר מיוסף, שאילו ביוסף לא הוה\u0004 \u0005[היתה]\u0006 \u0003אלא חדא שעתא\u0004 \u0005[שעה אחת]\u0006 שכבש את יצרו בנסיון עם אשת פוטיפר (בראשית ל״ט:י׳), \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003כל יומא ויומא\u0004 \u0005[יום ויום].\u0006 ועוד, \u0003ואילו יוסף לאו\u0004 \u0005[לא]\u0006 היה זה \u0003בחדא מטה\u0004 \u0005[במיטה אחת],\u0006 \u0003והאי בחדא מטה\u0004 \u0005[וזה במיטה אחת].\u0006 ועוד, \u0003ואילו יוסף לאו\u0004 \u0005[לא]\u0006 היתה זאת \u0003אשתו, והא\u0004 \u0005[וזו]\u0006 \u0003אשתו,\u0004 שכבר היתה מקודשת = מאורסת לו.","\u0003פתח אידך\u0004 \u0005[אחר]\u0006 \u0003ואמר: מעשה ועמדו ארבעים מודיות\u0004 (סאים של תבואה) \u0003ב\u0004מחיר \u0003דינר אחד,\u0004 ואחר כך אירע ש\u0003נחסר השער מודיא אחת,\u0004 ומכרו רק שלושים ותשע בדינר, \u0003ובדקו\u0004 מה החטא שגרם לכך, \u0003ומצאו אב ובנו שבאו על נערה מאורסה ביום הכפורים, והביאום לבית דין וסקלום, וחזר השער למקומו.\u0004","\u0003פתח אידך\u0004 \u0005[אחר]\u0006 \u0003ואמר: מעשה באדם אחד שנתן עיניו באשתו לגרשה, ו\u0004אולם \u0003היתה כתובתה מרובה\u0004 ולא רצה לשלם לה. \u0003מה עשה? הלך וזימן את שושביניו\u0004 (ידידיו) \u0003והאכילן והשקן, שיכרן\u0004 (עשאם שיכורים) \u0003והשכיבן\u0004 את השושבינים ואת אשתו \u0003על מיטה אחת, והביא לובן ביצה\u0004 שנראה כשכבת זרע \u0003והטיל ביניהן, והעמיד להן עדים\u0004 שראו אותם כך, \u0003ובא לבית דין\u0004 לומר שזנתה תחתיו.","\u0003היה שם זקן אחד מתלמידי שמאי הזקן ובבא בן בוטא שמו, אמר להן, כך מקובלני משמאי הזקן: לובן ביצה סולד מן האור\u0004 (אש) שהוא מתקשה על ידי חום, \u0003ושכבת זרע דוחה מן האור,\u0004 נכנסת לתוך הבגד על ידי החום. \u0003בדקו ומצאו כדבריו\u0004 שלא היתה זו שכבת זרע אלא לובן ביצה, \u0003והביאוהו\u0004 את האיש \u0003לבית דין והלקוהו והגבוהו\u0004 בסוף את \u0003כתובתה ממנו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: ו\u0004כי \u0003מאחר דהוו\u0004 \u0005[שהיו]\u0006 \u0003צדיקים כולי האי\u0004 \u0005[כל כך]\u0006 \u0003מאי טעמא איענוש\u0004 \u0005[מה טעם נענשו]\u0006 ונחרבו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום שלא איאבול\u0004 \u0005[התאבלו]\u0006 \u0003על ירושלים, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"שמחו את ירושלם וגילו בה כל אוהביה, שישו אתה משוש כל המתאבלים עליה\"\u0004 (ישעיה סו, י), לומר שמי שמתאבל על ירושלים זוכה לשמוח בבניינה, ולהיפך.","ועל מה שאמרנו בתחילה: \u0003אשקא דריספק חריב\u0004 \u0005[על,\u0006 בגלל \u0005יצול של עגלה נחרבה]\u0006 העיר \u0003ביתר,\u0004 מספרים: \u0003דהוו נהיגי כי הוה מתיליד ינוקא\u0004 — \u0003שתלי ארזא\u0004 \u0005[שהיו נוהגים\u0006 בביתר \u0005כאשר נולד תינוק\u0006 — \u0005היו שותלים ארז],\u0006 \u0003ינוקתא\u0004 — \u0003שתלי תורניתא\u0004 \u0005[\u0006כשהיתה נולדת \u0005תינוקת\u0006 — היו \u0005שותלים תורנית],\u0006 \u0003וכי הוו מינסבי קייצי להו ועבדו גננא\u0004 \u0005[וכאשר היו נישאים\u0006 זה עם זה \u0005היו קוצצים\u0006 את העצים הללו \u0005ועושים\u0006 להם מהם \u0005חופה].\u0006 \u0003יומא חד הוה קא חלפא ברתיה\u0004 \u0005[יום אחד עברה\u0006 שם \u0005בתו]\u0006 של ה\u0003קיסר, אתבר שקא דריספק\u0004 \u0005[נשבר יצול העגלה]\u0006 שבה נסעה, \u0003קצו ארזא ועיילו\u0004 \u0005[קצצו\u0006 עבדיה \u0005ארז\u0006 אחד, מאותם ארזים, \u0005והכניסו]\u0006 \u0003לה,\u0004 וכיון שהיה הדבר חשוב בעיני אנשי העיר ביתר \u0003אתו נפול עלייהו מחונהו\u0004 \u0005[באו\u0006 בני ביתר \u0005התנפלו עליהם\u0006 ו\u0005היכו אותם].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 האנשים \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לקיסר: מרדו בך יהודאי\u0004 \u0005[היהודים]!\u0006 \u0003אתא עלייהו\u0004 \u0005[בא עליהם]\u0006 למלחמה.","ועל אותה שעה דרשו, נאמר: \u0003\"גדע בחרי אף כל קרן ישראל\"\u0004 (איכה ב, ג) \u0003אמר ר' זירא אמר ר' אבהו אמר ר' יוחנן: אלו שמונים אלף קרני מלחמה,\u0004 כלומר, מפקדי יחידות צבא שהחזיקו בידם חצוצרות לתקוע בהן, \u0003שנכנסו לכרך ביתר בשעה שלכדוה, והרגו בה אנשים ונשים וטף, עד שהלך דמן\u0004 של כל אלה \u0003ונפל לים הגדול. שמא תאמר קרובה היתה\u0004 לים — \u0003רחוקה היתה מיל.\u0004","וכיוצא בזה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: שני נחלים יש בבקעת ידים\u0004 שבאותו אזור \u0003אחד מושך אילך,\u0004 לצד אחד, \u0003ואחד מושך אילך, ושיערו חכמים\u0004 שלאחר המלחמה היו שם \u0003שני חלקים מים ואחד דם. במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003שבע שנים בצרו גוים את כרמיהן מדמן של ישראל\u0004 שזיבל את השדות \u0003בלא\u0004 שיצטרכו \u0003זבל\u0004 אחר."],["\u0003אמר ר' חייא בר אבין אמר ר' יהושע בן קרחה: סח\u0004 (סיפר) \u0003לי זקן אחד מאנשי ירושלים: בבקעה זו\u0004 שאתה רואה \u0003הרג נבוזראדן רב טבחים\u0004 של נבוכדנאצר מלך בבל \u0003מאתים ואחת עשרה רבוא\u0004 נפש, \u0003ובירושלים\u0004 עצמה \u0003הרג תשעים וארבע רבוא\u0004 נפש \u0003על אבן אחת, עד שהלך דמן\u0004 של ההרוגים \u0003ונגע בדמו של זכריה, לקיים מה שנאמר: \"ודמים בדמים נגעו\"\u0004 (הושע ד, ב).","וכך היה מעשה: \u0003אשכחיה לדמיה\u0004 \u0005[מצא\u0006 נבוזראדן \u0005את דמו]\u0006 של \u0003זכריה דהוה קא מרתח וסליק\u0004 \u0005[שהיה מבעבע ועולה],\u0006 \u0003אמר: מאי האי\u0004 \u0005[מהו זה]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דם זבחים דאשתפוך\u0004 \u0005[שנשפך].\u0006 \u0003אייתי דמי\u0004 \u0005[הביא דמים]\u0006 של בהמות \u0003ולא אידמו\u0004 \u0005[היה דומה]\u0006 לדם זה.","\u0003אמר להו\u0004 \u0005[להם],\u0006 לאנשי ירושלים: \u0003אי אמריתו\u0004 \u0005[אם אומרים אתם]\u0006 \u0003לי\u0004 — \u0003מוטב, ואי לאו\u0004 \u0005[ואם לא]\u0006 — \u0003מסריקנא לבשרייכו במסרקי דפרזלי\u0004 \u0005[מסרק אני את בשרכם במסרקות של ברזל].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003מאי נימא\u0004 \u0005[מה נאמר]\u0006 \u0003לך? נבייא הוה בן דהוה קא מוכח לן במילי דשמיא\u0004 \u0005[נביא היה בנו שהיה מוכיח אותנו בענייני שמים],\u0006 \u0003קמינן עילויה וקטלינן ליה\u0004 \u0005[קמנו עליו והרגנו אותו],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 \u0003כמה שנין\u0004 \u0005[שנים]\u0006 ש\u0003לא קא נייח דמיה\u0004 \u0005[נח דמו].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא מפייסנא ליה\u0004 \u0005[אני אפייס אותו].\u0006 \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003סנהדרי גדולה וסנהדרי קטנה קטל עילויה\u0004 \u0005[הרג עליו]\u0006 ליד הדם הזה \u0003ולא נח\u0004 הדם מרתיחתו. הביא \u0003בחורים ובתולות קטל עילויה\u0004 \u0005[הרג עליו]\u0006 \u0003ולא נח\u0004 הדם. \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003תינוקות של בית רבן קטל עילויה\u0004 \u0005[הרג עליו]\u0006 \u0003ולא נח. אמר ליה\u0004 \u0005[לו]\u0006 נבוזראדן בסוף: \u0003זכריה, זכריה, טובים שבהן איבדתים,\u0004 וכי \u0003ניחא\u0004 \u0005[נוח]\u0006 \u0003לך דאבדינהו לכולהו\u0004 \u0005[שאאבד את כולם]?\u0006 \u0003כדאמר ליה הכי\u0004 \u0005[כאשר אמר לו כך]\u0006 \u0003נח\u0004 הדם.","\u0003בההיא שעתא\u0004 \u0005[באותה שעה]\u0006 \u0003הרהר\u0004 נבוזראדן \u0003תשובה בדעתיה\u0004 \u0005[בדעתו],\u0006 \u0003אמר\u0004 לעצמו: \u0003ומה אם על נפש אחת,\u0004 זכריה — \u0003כך\u0004 נוקם הקדוש ברוך הוא בישראל, \u0003ההוא גברא דקטל כל הני נשמתא\u0004 \u0005[אותו אדם,\u0006 אני, \u0005שהרג כל אותם הנשמות]\u0006 — \u0003על אחת כמה וכמה\u0004 שיהא עונשו מרובה! \u0003ערק אזל שדר שטר פרטתא בביתיה ואגייר\u0004 \u0005[ברח, הלך\u0006 ו\u0005שלח שטר צוואה לביתו והתגייר].\u0006","ובענין זה \u0003תנא\u0004 \u0005[שנה\u0006 חכם בברייתא\u0005]:\u0006 \u0003נעמן,\u0004 שר צבא מלך ארם (ראה מלכים ב ה׳:א׳), \u0003גר תושב היה\u0004 שלא קיבל עליו כל המצוות, ואילו \u0003נבוזראדן גר צדק\u0004 ממש \u0003היה\u0004 וכפי שמתואר לעיל.","ואגב כך מספרים: \u0003מבני בניו של המן למדו תורה בבני ברק. מבני בניו של סיסרא למדו תינוקות בירושלים. מבני בניו של סנחריב\u0004 זכו ו\u0003למדו תורה ברבים. מאן אינון\u0004 \u0005[מי הם\u0006 אלה\u0005]?\u0006 — \u0003שמעיה ואבטליון,\u0004 רבותיו של הלל הזקן.","ולענין המעשה בדמו של זכריה אומרים שהכתוב מרמז על כך, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"\u0004להעלות חמה לנקום נקם \u0003נתתי את דמה על צחיח סלע לבלתי הכסות\"\u0004 (יחזקאל כד, ח).","כיון שמדברים בענייני החורבן וצרות ישראל, מביאים עוד: על הכתוב \u0003\"הקל קול יעקב והידים ידי עשו\"\u0004 (בראשית כז, כב), דרשו: \u0003\"הקל\"\u0004 — \u0003זה אדריינוס קיסר,\u0004 שהביא לבכי וצעקה, \u0003שהרג באלכסנדריא של מצרים ששים רבוא על ששים רבוא, כפלים כיוצאי מצרים. \"קול יעקב\"\u0004 — \u0003זה אספסיינוס קיסר, שהרג בכרך ביתר ארבע מאות רבוא, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003ארבעת אלפים רבוא. \"והידים ידי עשו\"\u0004 — \u0003זו מלכות הרשעה\u0004 רומי, \u0003שהחריבה את בתינו,\u0004 בית המקדש, \u0003ושרפה את היכלנו, והגליתנו מארצנו.\u0004","\u0003דבר אחר: \"הקל קול יעקב\" — אין לך תפלה שמועלת\u0004 (פועלת בעולם) \u0003שאין\u0004 משתתף \u0003בה\u0004 מישהו \u0003מזרעו של יעקב.\u0004 ומצד שני \u0003\"והידים ידי עשו\"\u0004 — \u0003אין לך מלחמה שנוצחת שאין בה\u0004 מישהו \u0003מזרעו של עשו.\u0004","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלעזר: \"בשוט לשון תחבא\"\u0004 (איוב ה, כא) ופירשו: \u0003בחירחורי לשון תחבא,\u0004 כלומר, על ידי מריבה שבאה בגלל הלשון צריכים הכל להיחבא. \u0003אמר רב יהודה אמר רב, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"על נהרות בבל שם ישבנו גם בכינו בזכרנו את ציון\"\u0004 (תהלים קלז, א)? \u0003מלמד, שהראהו הקדוש ברוך הוא לדוד חורבן בית ראשון וחורבן בית שני. חורבן בית ראשון\u0004 — \u0003שנאמר: \"על נהרות בבל שם ישבנו גם בכינו\".\u0004 חורבן \u0003בית שני — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זכר ה' לבני אדום את יום ירושלם האמרים ערו ערו עד היסוד בה\"\u0004 (תהלים קלז, ז), שנחרבה בידי בני רומי (\"בני אדום\").","\u0003אמר רב יהודה אמר שמואל, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אמי\u0004 אמר זאת, \u0003ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים שבברייתא\u0006 היא \u0005שנויה]:\u0006 \u0003מעשה בארבע מאות ילדים וילדות שנשבו לקלון\u0004 (זנות), ו\u0003הרגישו בעצמן למה הן מתבקשים,\u0004 כלומר, לשם מה לוקחים אותם,\u0003 אמרו\u0004 הילדים: \u0003אם אנו טובעין בים\u0004 האם \u0003אנו באין לחיי העולם הבא\u0004 אם נאבד עצמנו לדעת?\u0003 דרש להן הגדול שבהן\u0004: נאמר: \u0003\"אמר ה' מבשן אשיב אשיב ממצלות ים\"\u0004 (תהלים סח, כג), \u0003\"מבשן אשיב\"\u0004 — \u0003מבין שיני אריה, \"אשיב ממצלות ים\"\u0004 — \u0003אלו שטובעין בים\u0004 לשם שמים.","\u0003כיון ששמעו ילדות כך, קפצו כולן ונפלו לתוך הים. נשאו ילדים קל וחומר בעצמן ואמרו: מה הללו שדרכן לכך,\u0004 להיבעל — \u0003כך\u0004 הן עושות כדי שלא לבוא לזנות, \u0003אנו שאין דרכנו לכך\u0004 — \u0003על אחת כמה וכמה! אף הם קפצו לתוך הים. ועליהם הכתוב אומר: \"כי עליך הרגנו כל היום נחשבנו כצאן טבחה\"\u0004 (תהלים מד, כג).","\u0003ורב יהודה אמר:\u0004 פסוק זה נאמר על \u0003אשה ושבעה בניה\u0004 שמתו על קידוש השם. וכך היה מעשה: \u0003אתיוהו קמא לקמיה\u0004 \u0005[הביאו את הראשון\u0006 מבין בניה \u0005לפני]\u0006 ה\u0003קיסר, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה!\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"אנכי ה' אלהיך\"\u0004 (שמות כ, ב). \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו],\u0006","\u0003ואתיוהו לאידך לקמיה\u0004 \u0005[והביאו את\u0006 האח \u0005האחר לפני]\u0006 ה\u0003קיסר, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה!\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"לא יהיה לך אלהים אחרים על פני\"\u0004 (שמות כ, ג). \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו].\u0006 \u0003אתיוהו לאידך\u0004 \u0005[הביאו את האחר],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה!\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"זבח לאלהים יחרם\"\u0004 (שמות כב, יט). \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו].\u0006","\u0003אתיוהו לאידך\u0004 \u0005[הביאו את האחר],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה!\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"לא תשתחוה לאל אחר\"\u0004 (שמות לד, יד). \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו].\u0006 \u0003אתיוהו לאידך\u0004 \u0005[הביאו את האחר],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה!\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"שמע ישראל ה' אלהינו ה' אחד\"\u0004 (דברים ו, ד). \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו].\u0006","\u0003אתיוהו לאידך\u0004 \u0005[הביאו את האחר],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה! אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"וידעת היום והשבת אל לבבך כי ה' הוא האלהים בשמים ממעל ועל הארץ מתחת אין עוד\"\u0004 (דברים ד, לט). \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו].\u0006","\u0003אתיוהו לאידך\u0004 \u0005[הביאו את האחר],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003פלח\u0004 \u0005[עבוד]\u0006 \u0003לעבודה זרה! אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתוב בתורה: \"את ה' האמרת\u0004 היום... \u0003וה' האמירך היום\"\u0004 (שמות כו, יז-יח), \u0003כבר נשבענו להקדוש ברוך הוא שאין אנו מעבירין\u0004 (מחליפים) \u0003אותו באל אחר, ואף הוא נשבע לנו שאין מעביר\u0004 \u0003אותנו באומה אחרת.\u0004","היה זה הקטן שבבנים, ריחם עליו הקיסר ורצה למצוא דרך שלא ייהרג, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר: אישדי\u0004 \u0005[אזרוק]\u0006 \u0003לך גושפנקא\u0004 \u0005[חותמת]\u0006 \u0003וגחין ושקליה\u0004 \u0005[ותתכופף ותרים אותה],\u0006 \u0003כי היכי דלימרו\u0004 \u0005[כדי שיאמרו]:\u0006 \u0003קביל עליה הרמנא דמלכא\u0004 \u0005[קיבל עליו את פקודת המלכות],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בלשון קללה: \u0003חבל עלך קיסר, חבל עלך קיסר,\u0004 אם \u0003על כבוד עצמך כך\u0004 אתה עושה שאעמוד ואקיים את פקודתך ולא תבטל אותה, \u0003על כבוד הקדוש ברוך הוא על אחת כמה וכמה!\u0004","\u0003אפקוהו למיקטליה\u0004 \u0005[הוציאו אותו להיהרג],\u0006 \u0003אמרה להו אימיה\u0004 \u0005[להם אימו]:\u0006 \u0003יהבוהו ניהלי ואינשקיה פורתא\u0004 \u0005[תנו אותו לי ואנשק אותו מעט].\u0006 \u0003אמרה לו: בניי, לכו ואמרו לאברהם אביכם אתה עקדת מזבח אחד ואני עקדתי שבעה מזבחות! אף היא\u0004 לבסוף \u0003עלתה לגג ונפלה ומתה. יצתה\u0004 (יצאה) \u0003בת קול ואמרה: \"אם הבנים שמחה\"\u0004 (תהלים קיג, ט).","\u0003ר' יהושע בן לוי אמר:\u0004 \"כי עליך הורגנו כל היום\" \u0003זו\u0004 ברית \u0003מילה שניתנה ב\u0004יום ה\u0003שמיני,\u0004 שהרי שופכים את דמם לשם ברית עם ה'. \u0003ר' שמעון בן לקיש אמר:\u0004 פסוק זה נאמר ב\u0003אלו תלמידי חכמים שמראין הלכות שחיטה בעצמן,\u0004 שמראים על עצמם איך עושים שחיטה ופעמים נפצעים בכך. ש\u0003אמר רבא: כל מילי ליחזי איניש בנפשיה\u0004 \u0005[כל דבר\u0006 יכול \u0005שיראה\u0006 שידגים \u0005אדם בעצמו],\u0006 \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003משחיטה ודבר אחר\u0004 (תשמיש), שאינו יכול להראות דוגמה בפועל איך עושים זאת.","\u0003רב נחמן בר יצחק אמר:\u0004 \"כי עליך הורגנו כל היום\" \u0003אלו תלמידי חכמים שממיתין עצמן על דברי תורה,\u0004 ו\u0003כ\u0004דברי \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר ר' שמעון בן לקיש: אין דברי תורה מתקיימין אלא במי שממית עצמו עליהם, שנאמר: \"זאת התורה אדם כי ימות באהל\"\u0004 (במדבר יט, יד). \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ארבעים סאה\u0004"],["\u0003קצוצי\u0004 (בתי) \u0003תפילין נמצאו בראשי הרוגי ביתר. ר' ינאי בר' ישמעאל אמר: שלש קופות\u0004 (סלים גדולים) \u0003של ארבעים ארבעים סאה\u0004 של תפילין. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003ארבעים קופות של שלש שלש סאין.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[חלוקים]\u0006 ר' יוחנן ור' ינאי: \u0003הא דרישא, הא דדרעא\u0004 \u0005[זו ב\u0006תפילין \u0005של ראש, זו ב\u0006תפילין \u0005של יד]\u0006 שבגלל ההבדל בדרך עשייתן היו גם נבדלות בגודלן.","\u0003אמר ר' אסי: ארבעה קבין מוח\u0004 של תינוקות שרוצצו את גולגולותיהם \u0003נמצאו על אבן אחת. עולא אמר: תשעת קבין. אמר רב כהנא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003שילא בר מרי: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — \u0003\"בת בבל השדודה אשרי שישלם לך\u0004 את גמולך שגמלת לנו \u0003אשרי שי אחז ונפץ את עלליך אל הסלע\"\u0004 (תהלים קלז, ח-ט).","נאמר: \u0003\"בני ציון היקרים המסלאים בפז\"\u0004 (איכה ד, ב), \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מסלאים בפז\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דהוו מחפי בפיזא\u0004 \u0005[שהיו מחופים\u0006 מכוסים ממש \u0005בפז],\u0006 \u0003והאמרי דבי\u0004 \u0005[והרי אמרו בבית]\u0006 מדרשו של \u0003ר' שילא: תרתי מתקלי איסתירי פיזא נחות בעלמא\u0004 \u0005[שני משקלות איסרי פז ירדו לעולם],\u0006 \u0003חדא ברומי וחדא בכולי עלמא\u0004 \u0005[אחד ברומא ואחד בכל העולם]\u0006 אם כן, בודאי אי אפשר היה לחפות את בני ירושלים בפז, שהרי אין די פז בעולם כולו! \u0003אלא\u0004 הכוונה היא שהיו מהוללים (\"מסולאים\") ביופיים עד \u0003שהיו מגנין\u0004 (משפילים) \u0003את הפז ביופיין.\u0004","ומספרים: \u0003מעיקרא חשיבי דרומאי הוו נקטי בליונא דגושפנקא ומשמשי ערסייהו\u0004 \u0005[מתחילה חשובי הרומאים היו מחזיקים תבליט של חותם והיו משמשים מיטתם]\u0006 כנגד התמונה היפה, כדי שיהיו להם ילדים יפים כיוצא בה, \u0003מכאן ואילך,\u0004 מזמן המלחמה, \u0003מייתו\u0004 \u0005[היו מביאים]\u0006 \u0003בני ישראל ואסרי בכרעי דפורייהו ומשמשי\u0004 \u0005[ואוסרים אותם ברגלי מיטותיהם והיו משמשים מיטתם]\u0006 כנגדם, משום שהיו יפים כל כך.","היה מעשה שעשו כך לשני ילדים, \u0003אמר ליה חד לחבריה\u0004 \u0005[אמר לו אחד לחבירו]:\u0006 \u0003הא, היכא כתיבא\u0004 \u0005[\u0006צרה \u0005זו, היכן\u0006 היא \u0005כתובה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כפי שנאמר: \u0003\"גם כל חלי וכל מכה אשר לא כתוב בספר התורה הזאת\"\u0004 (דברים כח, סא). \u0003אמר: כמה מרחיקנא מדוכתא פלן\u0004 \u0005[כמה אני רחוק מהמקום הזה],\u0006 כלומר, בלימודי שלמדתי, כמה עוד היה לי ללמוד כדי להגיע לשם, לאותו פסוק? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינגד פוסתא ופלגא\u0004 \u0005[אם היית מושך דף וחצי]\u0006 היית מגיע לשם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הילד ששאלו: \u0003אי מטאי לגביה\u0004 \u0005[אם הייתי מגיע אצלו,\u0006 לפסוק \u0005זה]\u0006 \u0003לא איצטריכי לך\u0004 \u0005[הייתי צריך אותך],\u0006 שהייתי יודע מעצמי שעל כך מדובר בכתוב.","\u0003אמר רב יהודה אמר שמואל משום רבן שמעון בן גמליאל, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"עיני עוללה לנפשי מכל בנות עירי\"\u0004 (איכה ג, נא)? \u0003ארבע מאות בתי כנסיות היו בכרך ביתר, ובכל אחת ואחת היו בה ארבע מאות מלמדי תינוקות\u0004 (ילדים), \u0003וכל אחד ואחד\u0004 מהמלמדים הללו \u0003היו לפניו ארבע מאות תינוקות של בית רבן,\u0004","\u0003וכשהיה אויב נכנס לשם היו\u0004 התינוקות \u0003דוקרין אותן בחוטריהן\u0004 (קני הכתיבה שבידם), \u0003וכשגבר אויב ולכדום, כרכום\u0004 את כל התינוקות הללו \u0003בספריהם והציתום באש.\u0004","ועוד בענין ילדי ירושלים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' יהושע בן חנניה שהלך לכרך גדול שברומי, אמרו לו: תינוק\u0004 (ילד) \u0003אחד יש בבית האסורים,\u0004 והוא \u0003יפה עינים וטוב רואי וקווצותיו סדורות לו תלתלים. הלך ועמד על פתח בית האסורים, אמר\u0004 כאילו לעצמו: \u0003\"מי נתן למשסה יעקב וישראל לבוזזים\"\u0004 (ישעיה מב, כד)? \u0003ענה אותו תינוק ואמר\u0004 את המשך הכתוב: \u0003\"הלא ה' זו חטאנו לו ולא אבו בדרכיו הלוך ולא שמעו בתורתו\"\u0004 (ישעיה מב, כד).","\u0003אמר\u0004 ר' יהושע: \u0003מובטחני בו ש\u0004יהיה \u0003מורה הוראה בישראל\u0004 אם יתנו לו את ההזדמנות לכך, שהרי כבר עתה הוא חכם כל כך. ונשבע: \u0003העבודה\u0004 (בעבודת המקדש)! \u0003שאיני זז מכאן עד שאפדנו בכל ממון שפוסקין\u0004 (שקובעים) \u0003עליו. אמרו: לא זז משם עד שפדאו בממון הרבה, ו\u0004אכן, \u0003לא היו ימים מועטין עד שהורה הוראה בישראל. ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005]?\u0006 — \u0003ר' ישמעאל בן אלישע.\u0004","\u0003אמר רב יהודה אמר רב: מעשה בבנו ובבתו של\u0004 הכהן הגדול \u0003ר' ישמעאל בן אלישע שנשבו לשני אדונים\u0004 שונים. \u0003לימים נזדווגו\u0004 (נפגשו) \u0003שניהם במקום אחד,\u0004 אדון \u0003זה אומר: יש לי עבד שאין כיופיו בכל העולם, וזה אומר: יש לי שפחה שאין בכל העולם כולו כיופיה,\u0004","\u0003אמרו\u0004 האדונים: \u0003בוא ונשיאם\u0004 את העבד והשפחה \u0003זה לזה, ונחלק\u0004 בינינו \u0003בוולדות\u0004 שיוולדו להם, שודאי יהיו יפים מאד. \u0003הכניסום לחדר\u0004 להתייחד, \u0003זה\u0004 הבן \u0003ישב בקרן זוית\u0004 (פינה) \u0003זה, וזו\u0004 הבת \u0003ישבה בקרן זוית זה, זה אומר: אני כהן בן כהנים גדולים,\u0004 אני \u0003אשא שפחה? וזאת אומרת: אני כהנת בת כהנים גדולים אנשא לעבד? ובכו כל הלילה.\u0004","\u0003כיון שעלה עמוד השחר, הכירו זה את זה\u0004 שהם אח ואחות, \u0003ונפלו זה על זה וגעו בבכיה עד שיצאה נשמתן\u0004 מרוב צער. \u0003ועליהן קונן ירמיה: \"על אלה אני בוכיה עיני עיני י רדה מים\"\u0004 (איכה א, טו).","\u0003אמר ריש לקיש: מעשה באשה אחת וצפנת בת פניאל שמה,\u0004 ולמה קראו לה כך? \u0003צפנת\u0004 — \u0003ש\u0004היו \u0003הכל צופין ביופיה, בת פניאל\u0004 — שהיתה \u0003בתו של כהן גדול ששימש לפני ולפנים\u0004 בקודש הקדשים בבית המקדש,","\u0003שנתעלל בה\u0004 ואנסה \u0003שבאי\u0004 (שודד) \u0003כל הלילה. למחר הלבישה שבעה חלוקים והוציאה למוכרה. בא אדם אחד שהיה מכוער ביותר, אמר לו\u0004 האיש למוכר: \u0003הראני את יופיה, אמר לו: ריקא! אם אתה רוצה ליקח\u0004 (לקנות) אותה — \u0003קח\u0004 (קנה), \u0003שאין כיופיה בכל העולם כולו.\u0004","\u0003אמר לו: אף על פי כן\u0004 רוצה אני לראות. \u0003הפשיטה ששת חלוקים, ושביעי קרעתה\u0004 היא עצמה \u0003ונתפלשה באפר, אמרה לפניו,\u0004 לפני ה': \u0003רבונו של עולם, אם עלינו לא חסת\u0004 וכך אתה מבזה אותנו, \u0003על קדושת שמך הגבור\u0004 שנקרא עלינו \u0003למה לא תחוס?\u0004","\u0003ועליה קונן ירמיה: \"בת עמי חגרי שק והתפלשי באפר אבל יחיד עשי לך מספד תמרורים כי פתאם יבא השודד עלינו\"\u0004 (ירמיה ו, כו), \u0003\"עליך\" לא נאמר אלא \"עלינו\", כביכול, עלי,\u0004 על הקדוש ברוך הוא, \u0003ועליך בא שודד,\u0004 שגם הקדוש ברוך הוא משתתף בצער זה, ואף שמו מתבזה.","\u0003אמר רב יהודה אמר רב, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ועשקו גבר וביתו ואיש ונחלתו\"\u0004 (מיכה ב, ב)? — \u0003מעשה באדם אחד שנתן עיניו באשת רבו\u0004 (המורה שלו), \u0003ושוליא דנגרי הוה\u0004 \u0005[ושוליית אומנים היה],\u0006 שלמד אצלו מלאכת הנגרות.","\u0003פעם אחת הוצרך (רבו) ללות\u0004 כסף, \u0003אמר לו\u0004 התלמיד שהיה עשיר: \u0003שגר\u0004 (שלח) \u0003אשתך אצלי ואלונה, שיגר אשתו אצלו, שהה\u0004 וזנה \u0003עמה שלשה ימים. קדם\u0004 השוליה \u0003ובא אצלו\u0004 אצל המורה, \u0003אמר לו\u0004 המורה: \u0003אשתי ששיגרתי לך היכן היא? אמר לו: אני פטרתיה לאלתר\u0004 (שלחתי אותה מייד), \u0003ושמעתי שהתינוקות נתעללו בה בדרך\u0004 ואנסוה.","\u0003אמר לו: מה אעשה? אמר לו\u0004 התלמיד: \u0003אם אתה שומע לעצתי גרשה. אמר לו: כתובתה מרובה\u0004 ואין לי כסף. \u0003אמר לו\u0004 התלמיד: \u0003אני אלווך ותן לה כתובתה. עמד זה וגרשה, הלך הוא\u0004 התלמיד \u0003ונשאה.\u0004","\u0003כיון שהגיע זמנו\u0004 של החוב להיפרע \u0003ולא היה לו לפורעו, אמר לו\u0004 התלמיד: \u0003בא ועשה\u0004 (עבוד) \u0003עמי בחובך. והיו הם,\u0004 האיש והאישה, \u0003יושבים ואוכלים ושותין, והוא,\u0004 הבעל הקודם, \u0003היה עומד ומשקה עליהן, והיו דמעות נושרות מעיניו ונופלות בכוסיהן, ועל אותה שעה נתחתם גזר דין\u0004 של ישראל. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהדין נגזר \u0003על שתי פתילות בנר אחד,\u0004 בלשון נקיה: על עוון אשת איש.","ומעתה חוזרים לפירוש המשנה: שנינו \u0003לקח\u0004 (קנה) \u0003מן הסיקריקון\u0004 וחזר וקנה מבעל הבית — אין מיקח זה מועיל. \u0003אמר רב: לא שנו\u0004 שאין זה \u0003אלא\u0004 ש\u0003אמר לו\u0004 בעל הבית הראשון כשהלה קנה ממנו: \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה\u0006 בקנין חזקה\u0005],\u0006 שיכול הוא לומר שלא התכוון למכור לו בכך, \u0003אבל\u0004 אם כתב ומכר לו \u0003בשטר\u0004 — \u0003קנה. ושמואל אמר: אף בשטר נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנה, עד שיכתוב לו\u0004 בעל הבית הראשון \u0003אחריות\u0004 על נכסיו, שבכך הוא מראה שזוהי מכירה אמיתית."],["\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל, ר' שמעון בן אלעזר אומר:\u0004 מי ש\u0003לקח\u0004 (קנה) \u0003מן האשה\u0004 נכס השייך לה, \u0003וחזר ולקח\u0004 אותו נכס \u0003מן האיש\u0004 שהוא המחזיק בו — \u0003מקחו קיים.\u0004 לקח \u0003מן האיש, וחזר ולקח מן האשה\u0004 — \u0003מקחו בטל, עד שתכתוב לו\u0004 האשה \u0003אחריות.\u0004 משמע כדברי שמואל שרק על ידי שבעל הנכס כותב לקונה אחריות הרי זה מראה שהיתה זו מכירה בלב שלם.","ושואלים: \u0003נימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה]\u0006 על \u0003רב\u0004 שאמר שדי בכתיבת שטר על ידי הבעלים? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אחריות\"\u0004 האמורה פה? \u0003נמי\u0004 \u0005[גם כן]\u0006 הכוונה היא ל\u0003שטר.\u0004 שדי שכותבת לו שטר, ואין צורך באחריות נכסים ממש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לקח מן הסיקריקון, ואכלה שלש שנים בפני בעלים וחזר ומכרה לאחר\u0004 — \u0003אין לבעלים על לוקח שני כלום,\u0004 שאינם יכולים לתבוע ממנו דבר.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דקא טעין ואמר \"מינך זבנה\"\u0004 \u0005[אם שטוען\u0006 הלוקח השני \u0005ואומר \"ממך קנה אותה\u0006 הלוקח הראשון \u0005\"]\u0006 שפיצה את הבעלים כדין — \u0003אפילו ראשון נמי\u0004 \u0005[גם כן]\u0006 יהא נאמן אם יטען שקנה מן הבעלים, שהרי יש לו חזקת שלוש שנים המועילה במקרה שכזה! \u0003אי דלא קא טעין ואמר \"מינך זבנה\"\u0004 \u0005[אם שאינו טוען ואומר \"ממך קנה אותה\u0006 הלוקח הראשון \u0005\"],\u0006 \u0003אפילו שני נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תישאר הקרקע ברשותו, שהרי כלל הוא שחזקה שאין עמה טענה — אינה נחשבת חזקה!","\u0003אמר רב ששת: לעולם\u0004 מדובר במקרה \u0003דלא קא טעין ליה\u0004 \u0005[שאינו טוען לו]\u0006 הלוקח השני שהראשון כבר קנאה ממנו, ואף שבדרך כלל חזקה שאין עימה טענה אינה חזקה, במקרה \u0003כגון זה טוענין\u0004 אנו \u0003ליורש, וטוענין\u0004 אנו \u0003ללוקח,\u0004 שטוענים הדיינים עבורו, שהיתה קרקע זו קנויה כדין ולוקח ראשון קנה אותה מן הבעלים, אף שהוא עצמו אינו טוען זאת.","\u0003ו\u0004אילו \u0003אידך\u0004 \u0005[האחר]\u0006 הלוקח הראשון עצמו, \u0003אי טעין\u0004 \u0005[אם\u0006 הוא \u0005טוען]\u0006 ואומר שהוא קנה מן הבעלים — \u0003אין\u0004 \u0005[כן],\u0006 ותישאר הקרקע בידו שהרי יש לו טענה שעימה חזקה, \u0003ואי לא טעין\u0004 \u0005[ואם אינו טוען]\u0006 — \u0003לא\u0004 תישאר הקרקע בידו, אף שיש לו חזקה, כיון שאין אנו טוענים עבורו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 גוי \u0003הבא\u0004 ולוקח קרקע מישראל \u0003מחמת חוב\u0004 שישראל חייב לו \u0003ומחמת אנפרות\u0004 (גזל קרקעות) — \u0003אין בו משום סיקריקון\u0004 ואין דיני סיקריקון שייכים בזה, \u0003ואנפרות עצמה\u0004 — \u0003צריכה שתשהה שנים עשר חדש\u0004 ביד הגוי שגזלה, כדי שהלוקח יזכה בה.","ומקשים: ענין זה של שנים עשר חודש שייך בדין סיקריקון, \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 ש\u0003אין בה משום סיקריקון!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך לפרש: \u0003סיקריקון עצמה\u0004 — \u0003צריכה שתשהה שנים עשר חדש.\u0004","\u0003אמר רב יוסף, נקטינן\u0004 \u0005[מוחזקים אנו],\u0006 מקובל בידינו כלל זה: \u0003אין אנפרות\u0004 (גזל קרקעות) \u0003בבבל.\u0004 ומקשים: \u0003והא קחזינן דאיכא\u0004 \u0005[והרי רואים אנו שיש]!\u0006 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אין דין אנפרות בבבל,\u0004 כלומר, אין דנים דין אנפרות בבבל. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון דאיכא בי דוואר\u0004 \u0005[שיש בית שלטון המחוז]\u0006 \u0003ולא אזיל קביל\u0004 \u0005[הולך לקבול]\u0006 לפניו שגזלו ממנו את הקרקע, \u0003אימא אחולי אחיל\u0004 \u0005[אמור שמחל\u0006 עליה\u0005],\u0006 ושוב אינו יכול לבוא ולתבוע אותה.","מסופר: \u0003גידל בר רעילאי קביל ארעא בטסקא מבני באגא\u0004 \u0005[קיבל קרקע\u0006 עבור תשלום \u0005מס הקרקע מבני בקעה\u0006 מסויימת\u0005],\u0006 שכל בני הביקעה היו משלמים מס הקרקע בשותפות, והלכו חלק מהם, והנשארים נתנו לגידל בר רעילאי את זכות השימוש בקרקעותיהם של הנעדרים בתנאי שישלם גידל את מס הקרקע עבורם. \u0003אקדים ויהיב זוזי דתלת שנין\u0004 \u0005[הקדים ונתן כסף של שלוש שנים\u0006 מיסים\u0005]\u0006 במקום שנה אחת, כפי שהיו רגילים לשלם. \u0003לסוף אתא מרוותא קמאי\u0004 \u0005[באו הבעלים הראשונים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לגידל זה: \u0003שתא קמייתא דיהבת\u0004 \u0005[שנה ראשונה שנתת\u0006 את המיסים\u0005]\u0006 \u0003אכלת\u0004 פירות השדה, \u0003השתא אנן יהבינן אנן אכלינן\u0004 \u0005[עכשיו אנו נותנים\u0006 מיסים ו\u0005אנו אוכלים]\u0006 מן השדות, ואין לך זכות בהם.","\u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003רב פפא, סבר למיכתב ליה טירפא אבני באגא\u0004 \u0005[חשב לכתוב לו\u0006 לגידל \u0005שטר טריפה על בני הבקעה]\u0006 שיחזירו לו את הכסף שהקדים לשלם עבור שתי השנים הנוספות, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: אם כן, עשית\u0004 דבר זה כדין \u0003סיקריקון,\u0004 ואמרנו שאין דין זה נוהג בבבל! \u0003אלא אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 במקרה כזה \u0003הניח מעותיו על קרן הצבי.\u0004 כלומר, איבד את כספו, ומה שפרע עבור אחרים — הרי זה כאילו נתן להם מתנה, אבל אין לו זכות לתבוע מהם את מה שנתן.","שנינו במשנה שזו שאמרו שצריך לקנות את הקרקע תחילה מן הבעלים \u0003זו משנה ראשונה. בית דין של אחריהן אמרו: הלוקח מן הסיקריקון נותן לבעלים רביע\u0004 (רבע). \u0003אמר רב:\u0004 נותן \u0003רביע\u0004 ממה ששילם \u0003בקרקע, או\u0004 שמשלם אותו \u0003רביע במעות,\u0004 כפי שירצה. \u0003ושמואל אמר:\u0004 נותן \u0003רביע ב\u0004ערך \u0003קרקע שהן שליש במעות\u0004 ששילם.","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005הם חלוקים]?\u0006 — \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 שמואל \u0005סבור]:\u0006 \u0003נכי רביע זבין\u0004 \u0005[בפחות רבע\u0006 מערך השדה \u0005מכר]\u0006 הסיקריקון לקונה, ולכן מחזיר הקונה לבעלים סכום זה שהרוויח מחמת שקנה מן הסיקריקון, שהוא שליש מן הכסף ששילם, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב \u0005סבור]:\u0006 \u0003נכי חומשא זבין\u0004 \u0005[בפחות חמישית\u0006 מערך השדה \u0005מכר\u0006 לו הסיקריקון\u0005]\u0006 ולכן צריך הקונה להחזיר לו רק חמישית, שהיא רבע ממה ששילם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003זו משנה ראשונה. בית דין של אחריהן אמרו: הלוקח מן הסיקריקון נותן לבעלים רביע, ויד בעלים על העליונה, רצו בקרקע נוטלין\u0004 את חלקם, \u0003רצו במעות נוטלין. אימתי?\u0004 — \u0003בזמן שאין בידן ליקח\u0004 (לקנות) את הקרקע בעצמם, \u0003אבל\u0004 אם \u0003יש בידן ליקח\u0004 — \u0003הן קודמין לכל אדם.\u0004","\u0003רבי הושיב בית דין ונמנו\u0004 (קבעו), \u0003שאם שהתה בפני סיקריקון שנים עשר חודש\u0004 — \u0003כל הקודם ליקח\u0004 — \u0003זכה, אבל נותן לבעלים רביע בקרקע או רביע במעות\u0004 והרי זה כדברי רב, וקשה על שמואל!","\u0003אמר רב אשי: כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 ברביע מעות, הרי זה רביע של כל הסכום \u0003לאחר שבאו מעות לידו\u0004 של הבעלים הראשונים. כלומר, הרביע הזה במעות אין כוונתו לרבע ממה שנתן הקונה לסיקריקון, אלא הכוונה היא לרבע של ערך השדה, שהוא שליש ממה שנתן הקונה לסיקריקון. \u0003אמר רב:\u0004"],["\u0003אנא הואי במניינא דבי\u0004 \u0005[אני הייתי במנין של בית]\u0006 \u0003רבי\u0004 שבו נמנו על תקנה זו, \u0003ומינאי דידי מנו ברישא\u0004 \u0005[וממני עצמי מנו בתחילה]\u0006 למרות שהיה הקטן שבהם.","ותוהים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003דיני ממונות ו\u0004כן \u0003הטהרות והטומאות מתחילין מן הגדול\u0004 שבדיינים, שהוא משמיע דעתו תחילה מפני כבודו, \u0003ודיני נפשות מתחילין מן הצד,\u0004 כלומר, מן הקטן, שיש לחשוש שמא אם יביע הגדול את דעתו ילכו כל השאר אחריו, ועלול הדבר לגרום לאיבוד נפשות. והרי כאן לא היה זה דין נפשות, ומדוע התחילו מרב שודאי לא היה גדול שבחבורה, והרי רבי היה גדול שבדיינים!","\u0003אמר רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' הילל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' וולס: שאני מנינא דבי\u0004 \u0005[שונה המנין שבבית]\u0006 \u0003רבי, דכולהו מנינייהו\u0004 \u0005[שכל מנייניהם]\u0006 \u0003מן הצד\u0004 \u0003הוו\u0004 \u0005[היו]\u0006 \u0003מתחילין\u0004 משום שרבי היה גדול כל כך בעיני הכל, שאמרו שיש לחשוש שאם הוא יפתח תחילה לא יעז אחר לחלוק עליו.","\u0003ו\u0004באותו ענין \u0003אמר רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' הילל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' וולס: מימות משה ועד רבי לא מצינו\u0004 (מצאנו) שיהא גדול הדור שיהא גדול גם ב\u0003תורה ו\u0004גם ב\u0003גדולה\u0004 (עושר ורוממות מדינית) \u0003במקום אחד.\u0004","ושואלים: \u0003ו\u0004האם \u0003לא\u0004 היה? \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003יהושע!\u0004 ומשיבים: בזמנו \u0003הוה\u0004 \u0005[היה]\u0006 \u0003אלעזר\u0004 שהיה גדול כמותו בתורה. ושואלים: \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003אלעזר,\u0004 שחי אחרי יהושע! ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 בזמנו \u0003פנחס\u0004 שהיה גדול הדור. ומקשים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003פנחס\u0004 אחריו! ומשיבים: \u0003הוו\u0004 \u0005[היו]\u0006 \u0003זקנים\u0004 אחרים שהיו גדולים בתורה כמותו.","ומקשים עוד: \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003שאול\u0004 שהיה גדול בתורה והיה מלך! ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003שמואל.\u0004 ומקשים: \u0003והא נח נפשיה\u0004 \u0005[והרי נפטר]\u0006 שמואל בחיי שאול! ומשיבים: \u0003כולהו שני קאמרינן\u0004 \u0005[כל השנים אנו אומרים],\u0006 כלומר, הכוונה היא שיהא אדם בכל שנות גדולתו הגדול בישראל בתורה ובגדולה כאחת. ושואלים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003דוד!\u0004 ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003עירא היאירי\u0004 שהיה גדול בתורה.","ומקשים: \u0003והא נח נפשיה\u0004 \u0005[והרי נפטר]\u0006 בחיי דוד! ומשיבים: שתהיה התורה והגדולה במקום אחד \u0003כולהו שני בעינן\u0004 \u0005[כל השנים אנו צריכים].\u0006 ושואלים: \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003שלמה\u0004 שהיה החכם מכל האדם! ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003שמעי בן גרא\u0004 שהיה רבו. ושואלים: \u0003והא קטליה\u0004 \u0005[והרי הרג אותו]\u0006 בתחילת מלכותו (מלכים א ב)! ומשיבים: \u0003כולהו שני קאמרינן\u0004 \u0005[כל השנים אנו אומרים]\u0006 ולא היה שלמה יחיד בגדולתו כל ימיו.","ומקשים: \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003חזקיה\u0004 המלך! ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 באותו הדור \u0003שבנא\u0004 שהיה גדול בתורה. ומקשים: \u0003הא איקטיל\u0004 \u0005[הרי נהרג]\u0006 במלחמה עם סנחריב! ומשיבים: \u0003כולהו שני קאמרינן\u0004 \u0005[כל השנים אנו אומרים].\u0006 ושואלים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003עזרא!\u0004 ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003נחמיה בן חכליה\u0004 בדורו שהיה כמותו בגדולה.","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, אף אני אומר: מימות רבי ועד רב אשי לא מצינו תורה וגדולה במקום אחד.\u0004 ושואלים: \u0003ו\u0004האם \u0003לא? והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003הונא בר נתן\u0004 שהיה גם גדול מאד בעושר וגם גדול בתורה, ובחיי רב אשי? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הונא בר נתן, \u0003דמיכף הוה כייף ליה\u0004 \u0005[שהיה כפוף לפני]\u0006 \u0003רב אשי,\u0004 ונמצא שהגדול שבכולם היה רב אשי.","ואף אלה תקנות משום תיקון העולם: \u0003חרש\u0004 \u0003רומז,\u0004 כלומר, יש משמעות ותוקף למה שהוא עושה רמזים בידיו ובשאר איברי גופו בזמן שהוא רוצה לקנות או למכור משהו, והמכר חל ובר תוקף. \u0003ו\u0004כן \u0003נרמז\u0004 שאומרים לו דבר והוא מסמן ברמזים שהוא מסכים, ועל ידי כך חל הקנין. \u0003ובן בתירא אומר:\u0004 אין צורך בכך אלא אפילו אם \u0003קופץ\u0004 את שפתיו לסמן דבר בשפתיו, או \u0003נקפץ,\u0004 שמסמן כך דבר כאשר מציעים לו — חל הקנין. וכל זה לגבי קניינים \u0003במטלטלין.\u0004 וכן \u0003הפעוטות\u0004 — \u0003מקחן מקח\u0004 (קנייתם — קנייה) \u0003וממכרן ממכר\u0004 (מכירתם — מכירה) \u0003במטלטלין.\u0004","\u0003אמר רב נחמן: מחלוקת\u0004 זו בין תנא קמא ובן בתירא — היא דווקא \u0003במטלטלין, אבל בגיטין —\u0004 \u0003דברי הכל\u0004 ואף לדברי בן בתירא דווקא \u0003ברמיזה.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, הלא \u0003\"במטלטלין\" תנן\u0004 \u0005[שנינו]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שהכוונה במשנה היתה לומר \u0003\"אף במטלטלין\"\u0004 ולאו דווקא בהם אלא גם בשאר דברים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב נחמן שבמיטלטלין בלבד אמר בן בתירא בקפיצה, ולא אמר כן בגיטין.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 לא כך, אלא כך \u0003אמר רב נחמן: כמחלוקת במטלטלין כך מחלוקת בגיטין.\u0004 ומקשים: \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"במטלטלין\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא: \u0003\"אף במטלטלין\"\u0004 וכן בדברים אחרים נחלקו.","שנינו במשנה \u0003הפעוטות\u0004 — \u0003מקחן מקח וממכרן ממכר במטלטלין.\u0004 ושואלים: \u0003ועד כמה?\u0004 כלומר, מאיזה גיל יכולים הפעוטות לעסוק במיקח וממכר? \u0003מחוי\u0004 \u0005[היה מראה]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]:\u0006 \u0003כבר שית, כבר שב\u0004\u0005[כבן שש, כבן שבע].\u0006 \u0003רב כהנא אמר: כבר שב, כבר תמני\u0004 \u0005[כבן שבע, כבן שמונה].\u0006 \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003כבר תשע, כבר עשר\u0004 \u0005[כבן תשע, כבן עשר].\u0006","ומעירים: \u0003ולא פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 בסברה, אלא \u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003לפי חורפיה\u0004 \u0005[חריפותו],\u0006 שפעמים שיש ילדים חריפים ומבינים כבר בגיל צעיר, ופעמים צריכים להמתין להם עד שאפשר לסמוך על מעשיהם עד לגיל יותר מאוחר. ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומה טעם]\u0006 תיקנו זאת חכמים לפעוטות? \u0003אמר ר' אבא בר יעקב אמר ר' יוחנן: משום כדי חייו,\u0004 שפעמים שאין לילד מקור אחר לפרנסתו והוא חייב לעסוק במסחר כלשהו, ואם לא יורשה לעשות זאת לא יהיה מי שיחייה אותו.","אגב הזכרת המסורת בשם ר' אבא בר יעקב מביאים את דבריו בענין אחר. נאמר: \u0003\"ויאמר לאשר על המלתחה הוצא לבוש לכל עובדי הבעל\"\u0004 (מלכים ב י, כב), ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מלתחה\"? אמר ר' אבא בר יעקב אמר ר' יוחנן: דבר הנמלל ונמתח,\u0004 סוג מסויים של בגד שהוא מתקפל עד למידה קטנה, ואחר כך נמתח למידה גדולה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל אמר בשם \u0003ר' יוחנן: שיגר לו\u0004 אדם עשיר אחד שנקרא \u0003בוניים בן נוניים מתנה ל\u0004כבודו של \u0003רבי, סיבני וחומס סלסלה ומלמלא,\u0004 שהם מיני פשתן מיוחדים. ומבארים מה טיבם של בדים אלה, ובמה היו מיוחדים כל כך: \u0003סיבני וחומס\u0004 — שהיו מקופלים והיה גודלם \u0003כאמגוזא ופלגיה דאמגוזא\u0004 \u0005[כאגוז וכחצי אגוז].\u0006 \u0003סלסלה ומלמלא\u0004 — \u0003כפיסתקא ופלגי דפיסתקא\u0004 \u0005[כבוטן וחצי בוטן],\u0006 שבדים אלה היו דקים כל כך שהיו יכולים להתקפל לשיעור קטן זה, וכשפשטו אותם היו ראויים לבגד שלם עבור רבי. ועוד מסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מלמלא?\u0004 — \u0003דבר הנמלל ונמתח.\u0004","וחוזרים לענין פעוטות, ושואלים: \u0003וטעותן עד כמה?\u0004 כלומר, בענין מיקח וממכר, כמה נחשב לגביהם שיעור של טעות שאין מתבטל בגללה המיקח? \u0003אמר ר' יונה אמר ר' זירא: עד שתות\u0004 \u0005[שישית],\u0006 כטעותו של איש גדול שאין המיקח מתבטל בגללה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי: מתנתו\u0004 של פעוט, \u0003מאי\u0004 \u0005[מה]\u0006 דינה? \u0003רב יימר אמר: אין מתנתו מתנה, מר בר רב אשי אמר: מתנתו מתנה.\u0004","\u0003אפכוה\u0004 \u0005[הפכו]\u0006 את דברי החולקים הללו \u0003ושדרוה\u0004 \u0005[ושלחו אותה]\u0006 את דברי המחלוקת \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב מרדכי,\u0004 ולפי מה ששלחו לו מר בר רב אשי הוא זה שאמר שאין מתנתו מתנה. \u0003אמר ליה\u0004 \u0005[להם]:\u0006 \u0003זילו\u0004 \u0005[לכו]\u0006 \u0003אמרו ל\u0004מר \u0003בר מר\u0004 \u0005[בן אדוני]\u0006 רב אשי, שהיה רבו של רב מרדכי: \u0003לאו הכי הוה עובדא\u0004 \u0005[האם לא כך היה מעשה],\u0006 \u0003כי הוה קאי מר חד כרעיה אארעא וחד כרעיה אדרגא\u0004 \u0005[כאשר היה עומד האדון,\u0006 רב אשי, \u0005רגלו האחת על הארץ ורגלו האחת על המדרגה],\u0006 \u0003ואמרנא ליה\u0004 \u0005[ואמרנו לו]:\u0006 \u0003מתנתו\u0004 של פעוט \u0003מאי\u0004 \u0005[מה]\u0006 דינה? \u0003ואמר לן\u0004 \u0005[לנו]:\u0006 \u0003מתנתו מתנה, אחת מתנת שכיב מרע\u0004 שמצווה לפני מותו \u0003ואחת מתנת בריא, אחת מתנה מרובה ואחת מתנה מועטת,\u0004 שבכל ענין מתנתו מתנה.","כיון שהזכרנו עד עכשיו תקנות שתיקנו חכמים מפני תיקון העולם בדברים שונים, מביאים עוד: \u0003אלו דברים אמרו\u0004 שתיקנו חכמים וטעמם הוא \u0003מפני דרכי שלום:\u0004 כשקוראים בתורה \u0003כהן קורא ראשון ואחריו\u0004 קורא \u0003לוי ואחריו ישראל,\u0004 ולא לפי גדלותם בדברים אחרים, וכל זה עשו \u0003מפני דרכי שלום\u0004 שלא יבואו לריב מי הגדול שבקהילה. וכן \u0003מערבין\u0004 עירובי חצרות \u0003בבית ישן\u0004 שהיו רגילים להניח בו את העירוב \u0003מפני דרכי שלום\u0004 כאשר יבואר בגמרא."],["\u0003בור שהוא קרוב לאמה\u0004 (תעלת המים), שממנה משקים כמה בורות או שדות, \u0003מתמלא ראשון, מפני דרכי שלום,\u0004 שיהא סדר קבוע בהשקאת השדות, ולא יריבו למי יש זכות קדימה בכך.","\u0003מצודות\u0004 (מלכודות) \u0003חיה ועופות ודגים\u0004 שנתפסו בהן בעלי חיים אף על פי שבעלי המצודות טרם זכו במה שבתוכן \u0003יש בהן משום גזל,\u0004 אם אחר מוציא את הציד מתוכן, \u0003מפני דרכי שלום, ר' יוסי אומר: גזל גמור\u0004 הוא זה.","\u0003מציאת חרש שוטה וקטן\u0004 אף שאינם בני דעת ואינם יכולים לקנות דבר, ואם כן מצד הדין לא קנו את המציאה, \u0003יש בהן משום גזל\u0004 אם לקחו את המציאה מידם, \u0003מפני דרכי שלום, ר' יוסי אומר: גזל גמור\u0004 הוא זה.","\u0003עני המנקף\u0004 (משיר זיתים) \u0003בראש הזית\u0004 והזיתים נופלים למרגלות העץ — \u0003מה שתחתיו גזל, מפני דרכי שלום, ר' יוסי אומר: גזל גמור.\u0004","\u0003אין ממחין\u0004 (מוחים) \u0003ביד עניי גוים\u0004 הבאים גם הם לקחת \u0003בלקט שכחה ופאה,\u0004 למרות שאלה נועדו רק עבור עניי ישראל, \u0003מפני דרכי שלום.\u0004","שנינו במשנה שכהן קורא ראשון ואחריו לוי, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו],\u0006 מה מקורם בתורה? \u0003אמר רב מתנה,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויכתב משה את התורה הזאת ויתנה אל הכהנים בני לוי\"\u0004 (דברים לא, ט), ויש לדקדק: \u0003אטו אנא לא ידענא\u0004 \u0005[וכי אין אני יודע]\u0006 ש\u0003כהנים בני לוי נינהו\u0004 \u0005[הם]\u0006 ומדוע נאמר הדבר? \u0003אלא\u0004 שתחילה ניתנה התורה לכהנים ואחר כך לשאר בני לוי, ומכאן שיהיה \u0003כהן\u0004 קורא \u0003ברישא\u0004 \u0005[בראש,\u0006 בתחילה\u0005]\u0006 \u0003והדר\u0004 \u0005[ואחריו]\u0006 \u0003לוי.\u0004","\u0003ר' יצחק נפחא אמר, מהכא\u0004 \u0005[מכאן]\u0006 אנו למדים, שנאמר: \u0003\"ונגשו הכהנים בני לוי\"\u0004 (דברים כא, ה), ויש לדקדק: \u0003אטו אנן לא ידעינן\u0004 \u0005[וכי אין אנו יודעים]\u0006 ש\u0003כהנים בני לוי נינהו\u0004 \u0005[הם]?\u0006 \u0003אלא\u0004 מלמד הכתוב ש\u0003כהן ברישא\u0004 \u0005[בראש,\u0006 בתחילה\u0005]\u0006 \u0003והדר\u0004 \u0005[ואחריו]\u0006 \u0003לוי.\u0004","\u0003רב אשי אמר\u0004 \u0003מהכא\u0004 \u0005[מכאן]\u0006 אנו למדים זאת, שנאמר: \u0003\"בני עמרם אהרן ומשה ויבדל אהרן להקדישו קדש קדשים\"\u0004 (דברי הימים א כג, יג), הרי שאהרן ובניו הכהנים הוקדשו יותר מאשר שאר שבט לוי, ולכן הם גם קודמים בקריאה בתורה.","\u0003ר' חייא בר אבא אמר מהכא\u0004 \u0005[מכאן]\u0006 אנו למדים, שנאמר לגבי הכהן: \u0003\"וקדשתו\"\u0004 (ויקרא כא, ח) — \u0003לכל דבר שבקדושה.\u0004 ועל פסוק זה \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: \"וקדשתו\" — לכל דבר שבקדושה; לפתוח\u0004 בדברי תורה בישיבה או במסיבה אחרת של קדושה \u0003ראשון, ולברך ראשון, וליטול מנה יפה\u0004 יותר בסעודה \u0003ראשון,\u0004 שנותנים לו לקחת תחילה ויכול לבחור את היפה שבמנות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 לפי זה, מדוע שנינו במשנה שהכהן קורא תחילה \u0003מפני דרכי שלום?\u0004 הלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא\u0004 קדימה זו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אמנם \u0003דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005]\u0006 \u0003ו\u0004טעם הדבר הוא \u0003מפני דרכי שלום.\u0004","חזר אביי והקשה: הלא \u0003כל התורה כולה נמי\u0004 \u0005[גם כן]\u0006 \u0003מפני דרכי שלום היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"דרכיה דרכי נעם וכל נתיבתיה שלום\"\u0004 (משלי ג, יז), ולפי זה אין הלכה זו שונה משאר דברי תורה, שכולם באים להוסיף נועם ושלווה בעולם!","\u0003אלא אמר אביי:\u0004 דברי המשנה שכהן קורא ראשון וכו' מפני דרכי שלום, עניינם \u0003לכדמר\u0004 \u0005[לכפי\u0006 שאמר \u0005אדוני,\u0006 רבה\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שנים\u0004 האוכלים יחד — \u0003ממתינין\u0004 (צריכים להמתין) \u0003זה לזה בקערה. שלשה\u0004 שאכלו — \u0003אין ממתינין. הבוצע\u0004 את הפת \u0003הוא פושט ידו תחלה\u0004 לאכול ממנה, \u0003ואם בא לחלוק כבוד לרבו או למי שגדול ממנו\u0004 — \u0003הרשות בידו.\u0004","\u0003ואמר מר עלה\u0004 \u0005[החכם,\u0006 רבה, \u0005עליה,\u0006 על ברייתא זו\u0005]:\u0006 \u0003לא שנו אלא בסעודה,\u0004 שיכול לכבד את הגדול ממנו, \u0003אבל בבית הכנסת לא,\u0004 משום \u0003דאתו לאינצויי\u0004 \u0005[שיבואו לריב]\u0006 מי הוא הגדול שבכולם, וזהו שאמרה המשנה שמשום דרכי שלום אין משנים כלל את סדר הקרואים, ואין הכהן רשאי לכבד ישראל שיקרא במקומו.","\u0003אמר רב מתנה: הא דאמרת\u0004 \u0005[זה שאתה אומר]\u0006 ש\u0003בבית הכנסת לא\u0004 ניתן לחלוק כבוד לרב מקום כהן בסדר קריאת התורה, \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 רק \u0003בשבתות וימים טובים דשכיחי\u0004 \u0005[שמצויים]\u0006 שם \u0003רבים, אבל בשני ובחמישי\u0004 — \u0003לא,\u0004 שאין רבים מצויים, ומשום כך יכול לכבד את הגדול ממנו, ואין לחשוש לריב.","ושואלים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן היא]?!\u0006 שאין הכהן רשאי להקדים את רבו שיקרא במקומו בתורה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא\u0004 שלא היה כהן \u0003קרי בכהני\u0004 \u0005[היה קורא\u0006 בתורה ראשון, \u0005ב\u0006עליה של \u0005כהנים]\u0006 אף \u0003בשבתות ויום טוב!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב הונא,\u0004 ש\u0003אפילו\u0004 החכמים \u0003ר' אמי ור' אסי כהני חשיבי\u0004 \u0005[הכהנים החשובים]\u0006 של \u0003ארץ ישראל מיכף הוו כייפי ליה\u0004 \u0005[כפופים היו לו]\u0006 ולא היה מקום לריב, שהכל הודו שהוא גדול הדור וראוי לו לקרוא ראשון.","\u0003אמר אביי, נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 בהלכה זו: אם \u0003אין שם\u0004 בבית הכנסת, בקריאת התורה, \u0003כהן\u0004 — \u0003נתפרדה חבילה\u0004 ואין ללוי זכות קדימה לפני ישראלים. \u0003ואמר אביי, נקטינן\u0004 \u0005[מוחזקים אנו]:\u0006 \u0003אין שם לוי\u0004 — \u0003קורא כהן\u0004 במקומו.","ותוהים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: כהן אחר כהן לא יקרא משום פגמו של ראשון,\u0004 שמא יאמרו שמשום שאינו כהן העלו כהן אחריו. \u0003לוי אחר לוי לא יקרא משום פגם שניהם\u0004 שיאמרו שהשני ישראל, או שהראשון ישראל והעלו לוי במקומו! ומשיבים: \u0003כי קאמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 שאם אין לוי קורא כהן במקומו, הרי זה \u0003באותו כהן\u0004 שכבר עלה לתורה, שאז אין מקום לחשש לפגמו של ראשון.","כיון שהובאה הברייתא שואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003לוי אחר לוי\u0004 שנימקה הברייתא את ההלכה שלא יקרא משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 חשש \u0003לפגם שניהם\u0004 — משום \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 אנשים: \u0003חד מינייהו\u0004 \u0005[אחד מהם]\u0006 בוודאי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לוי הוא\u0004 אלא ישראל? הרי מאותה סיבה \u0003כהן אחר כהן נמי אמרי\u0004 \u0005[גם כן אומרים]\u0006 אנשים: \u0003חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כהן הוא\u0004 ויש פגם לשניהם, ולא רק לראשון! ומשיבים: מדובר \u0003כגון\u0004 ש\u0003מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003באבוה דהאי\u0004 \u0005[באביו של זה]\u0006 ה\u0003שני\u0004 ש\u0003כהן הוא.\u0004","ושואלים: אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בלויים, יש לומר שמדובר ש\u0003מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003באבוה דהאי\u0004 \u0005[באביו של זה]\u0006 \u0003שני\u0004 ש\u0003לוי הוא! אלא\u0004 יש לומר: מה טעם מלעיזים אף שיודעים שאדם זה הוא בנו של לוי — \u0003אמרי\u0004 \u0005[אומרים]:\u0006 שמא \u0003ממזרת או נתינה נסיב\u0004 \u0005[נשא]\u0006 \u0003ופסליה לזרעיה\u0004 \u0005[ופסל את זרעו]\u0006 ובניו הם בגדר ישראלים ולא לויים? \u0003הכא נמי אמרי\u0004 \u0005[כאן גם כן אומרים]\u0006 על בנו של כהן שמא \u0003גרושה או חלוצה נסיב\u0004 \u0005[נשא\u0006 האב\u0005],\u0006 \u0003ואחליה לזרעיה\u0004 \u0005[וחילל את זרעו]!\u0006","ומתרצים: \u0003סוף סוף לוי מי קא הוי\u0004 \u0005[האם הוא],\u0006 שהרי החלל יש לו דין ישראל, ולא דין לוי, ואם קראוהו לתורה אחרי הכהן ויודעים שאביו כהן — מובן וברור שאף הוא עצמו כהן הוא, ואין לחשוש אלא לפגמו של הכהן הראשון.","ולעיקר הדבר שואלים: \u0003ולמאן\u0004 \u0005[ולמי]\u0006 אנו חוששים, כלומר, מי הם אלה העשויים לטעות ולחשוב שיש פגם בראשון? \u0003אי\u0004 \u0005[אם]\u0006 תאמר כי חוששים אנו\u0003 ליושבין\u0004 שנשארים עד גמר הקריאה — \u0003הא קא חזו ליה\u0004 \u0005[הרי הם רואים אותו]\u0006 שהוא נמנה במנין הקרואים, ובודאי כשר הוא! \u0003אלא ליוצאין\u0004 לפני גמר הקריאה ואינם יודעים כיצד יתישבו עם מספר הקרואים.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני גלילא\u0004 \u0005[הגליל]\u0006 \u0003לר' חלבו:\u0004 \u0003אחריהן,\u0004 אחרי הכהן והלוי"],["\u0003מי קוראין? לא הוה בידיה\u0004 \u0005[היה בידו]\u0006 מענה. \u0003אתא ושייליה\u0004 \u0005[בא ושאלו]\u0006 את \u0003ר' יצחק נפחא, אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק נפחא: \u0003אחריהן\u0004 \u0003קוראין\u0004 \u0003תלמידי\u0004 \u0003חכמים הממונין\u0004 \u0003פרנסים\u0004 (מנהיגים) \u0003על\u0004 \u0003הצבור, ואחריהן תלמידי חכמים הראויין למנותם פרנסים על הציבור\u0004 אף על פי שלא נתמנו בפועל. שאמרו חכמים שתלמיד חכם ששואלים אותו הלכה בכל מקום ויודע לענות הוא הראוי למנותו פרנס על הציבור. \u0003ואחריהן בני תלמידי חכמים שאבותיהן ממונים פרנסים על הצבור, ואחריהן ראשי כנסיות ו\u0004אחריהם \u0003כל אדם.\u0004","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני גליל לר' חלבו: מהו\u0004 הדין, האם מותר \u0003לקרות\u0004 (לקרוא) \u0003בחומשים בבית הכנסת בציבור,\u0004 או שצריך לקרוא דווקא בספר תורה שלם? \u0003לא הוה בידיה\u0004 \u0005[היה בידו]\u0006 מענה. \u0003אתא שייליה\u0004 \u0005[בא\u0006 ו\u0005שאלו]\u0006 שאלה זו \u0003לר' יצחק נפחא, לא הוה בידיה\u0004 \u0005[היה בידו]\u0006 מענה. \u0003אתא שאיל בי מדרשא\u0004 \u0005[בא\u0006 ו\u0005שאל בבית המדרש],\u0006 \u0003ופשטוה\u0004 \u0005[ופתרוה]\u0006 את השאלה הזו \u0003מהא\u0004 \u0005[מ\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: ספר תורה שחסר יריעה אחת\u0004 — \u0003אין קורין בו,\u0004 משמע שאין קוראים בציבור בדבר חסר.","ודוחים: \u0003ולא היא\u0004 (ואינו כן), אין מכאן ראיה; \u0003התם מחסר במילתיה\u0004 \u0005[שם\u0006 הוא \u0005חסר בעניינו],\u0006 שהרי חסרה בו יריעה, ואולם \u0003הכא לא מחסר במילתיה\u0004 \u0005[כאן אינו חסר בעניינו],\u0006 שהרי הוא חומש שלם. \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין קוראין בחומשין בבית הכנסת משום כבוד הצבור.\u0004","\u0003ורבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003האי ספר אפטרתא\u0004 \u0005[הפטרות]\u0006 שכתובות בו כל ההפטרות — \u0003אסור למקרי ביה\u0004 \u0005[לקרוא בו]\u0006 \u0003בשבת. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ש\u0003לא ניתן\u0004 דבר כזה \u0003ליכתב\u0004 \u0005[להיכתב]\u0006 אלא כותבים ספר מקרא שלם.","\u0003מר בר רב אשי אמר: לטלטולי נמי\u0004 \u0005[לטלטל\u0006 אותו \u0005גם כן]\u0006 \u0003אסור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא חזי למיקרי ביה\u0004 \u0005[אינו ראוי לקרוא בו],\u0006 וכיון שכך הריהו כמוקצה בשבת. ודוחים: \u0003ולא היא\u0004 (ואינו כן), אלא \u0003שרי לטלטולי ושרי למיקרי ביה\u0004 \u0005[מותר לטלטלו ומותר לקרוא בו],\u0006 והראיה לדבר: ש","\u0003ר' יוחנן ור' שמעון בן לקיש מעייני בספרא דאגדתא\u0004 \u0005[היו מעיינים בספר של אגדה]\u0006 שהיו כתובים בו דברי חכמים \u0003בשבתא\u0004 \u0005[בשבת],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא ניתן ליכתב,\u0004 שמעיקר הדין אין כותבים דברי תורה שבעל פה. \u0003אלא כיון\u0004 שלא \u0003אפשר\u0004 בלי כתיבה, אנו כותבים דברי תורה שבעל פה משום \u0003\"עת לעשות לה' הפרו תורתך\"\u0004 (תהלים קיט, קכו), \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בספר הפטרות \u0003כיון\u0004 ש\u0003לא\u0004 \u0003אפשר\u0004 לכתוב תמיד ספרי מקרא שלמים — יש להשתמש באותו נימוק — \u0003\"עת לעשות לה' הפרו תורתך\".\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבה: מהו לכתוב מגילה\u0004 שכתוב בה רק חלק מן התורה \u0003ל\u0004צורך \u0003תינוק\u0004 כדי \u0003להתלמד בה?\u0004 ומעירים: \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 הן \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תורה מגילה מגילה ניתנה\u0004 מתחילתה, שמשה היה אומר לישראל פרשה מסויימת וכותבה, ואחר כך פרשה אחרת, עד שנגמרו כל הפרשיות, וכן \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תורה חתומה ניתנה,\u0004 שלא היתה התורה כתובה קודם חלק אחר חלק, אלא לבסוף כתבה משה כולה כאחת.","ומפרטים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תורה מגילה מגילה ניתנה,\u0004 וצדדי השאלה: מן הצד האחד אפשר לומר \u0003כיון\u0004 ש\u0003מגילה מגילה ניתנה\u0004 גם עתה \u0003כותבין\u0004 מגילה מן התורה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003כיון דאידבק אידבק\u0004 \u0005[שהודבק הודבק],\u0006 שהרי תורה שניתנה לישראל תורה שלימה ניתנה, ולא הותר לכתוב מגילות.","וכן \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תורה חתומה ניתנה.\u0004 וצדדי השאלה: האם נאמר \u0003כיון\u0004 ש\u0003חתומה ניתנה אין כותבין, או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא אפשר\u0004 באופן אחר \u0003כתבינן\u0004 \u0005[כותבים אנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003אין כותבין\u0004 מגילה כזו, \u0003ומה טעם? לפי שאין כותבין,\u0004 כלומר, שלפי שאסור לכתוב דבר שהוא רק חלק מן התורה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי: הרי שנינו, \u0003אף היא\u0004 הילני המלכה \u0003עשתה\u0004 למקדש במתנה \u0003טבלא של זהב שפרשת סוטה כתובה,\u0004 חקוקה, \u0003עליה,\u0004 משמע שאפשר לכתוב חלק מן התורה! \u0003אמר ר' שמעון בן לקיש משום\u0004 (בשם) \u0003ר' ינאי:\u0004 לא היתה טבלה זו כתובה כדרכה אלא \u0003באל\"ף בי\"ת,\u0004 כלומר, רק ראשי תיבות, שלפיהן היה הכהן הכותב את מגילת הסוטה זוכר ויודע מה לכתוב.","\u0003איתיביה\u0004 \u0005[הקשה לו],\u0006 הרי שנינו בברייתא: \u0003כשהוא,\u0004 הכהן, \u0003כותב\u0004 את הכתוב במגילת הסוטה, הריהו \u0003רואה\u0004 בטבלא \u0003וכותב מה שכתוב בטבלא,\u0004 משמע שבטבלא כתובה הפרשה עצמה כפי שהיא! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון: לא \"מה שכתוב\" אלא \u0003\"כמה\u0004 (כמו, כעין מה) \u0003שכתוב בטבלא\".\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו בברייתא במפורש: \u0003כשהוא כותב, רואה בטבלא וכותב מה שכתוב בטבלא, מה הוא כתוב בטבלא? \"אם שכב... אם לא שכב\"\u0004 (ראה במדבר ה, יט)! והשיב לו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בסירוגין,\u0004 שלא היה הדבר כתוב בשלימות אלא בדילוגים.","ומעירים: מחלוקת זו אם מותר לכתוב מגילה לתינוק על מנת להתלמד בה היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו בברייתא: \u0003אין כותבין מגילה לתינוק להתלמד בה, ואם דעתו\u0004 של הכותב \u0003להשלים\u0004 ולהוסיף על המגילה עד שייכתב ספר שלם — \u0003מותר. ר' יהודה אומר: ב\u0004ספר \u0003בראשית\u0004 — כותב מגילה אחת \u0003עד דור המבול. בתורת כהנים\u0004 (ספר ויקרא) — \u0003עד \"ויהי ביום השמיני\"\u0004 (ויקרא ט, א).","ומביאים את המחלוקת שהזכרנו לעיל, \u0003אמר ר' יוחנן משום ר' בנאה: תורה\u0004 — \u0003מגילה מגילה ניתנה, שנאמר: \"אז אמרתי הנה באתי במגלת ספר כתוב עלי\"\u0004 (תהלים מ, ח), שאמר דוד המלך על עצמו שיש פרשה בתורה (\"מגילת ספר\") שנרמז בה עניינו (\"כתוב עלי\"), משמע שכל חלק בתורה הוא מגילה לעצמה. \u0003ר' שמעון בן לקיש אומר: תורה\u0004 — \u0003חתומה\u0004 ובשלימותה \u0003ניתנה, שנאמר: \"לקח את ספר התורה הזאת\"\u0004 (דברים לא, כו), הרי שספר שלם ניתן.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' יוחנן, \u0005גם כן]\u0006 מה יפרש בכתוב זה? \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לקח\",\u0004 לומר שספר תורה שלם ניתן! ומשיבים: הפסוק \u0003ההוא\u0004 מדבר \u0003לבתר דאידבק\u0004 \u0005[\u0006\u0005לאחר\u0006 \u0005ש\u0006הספר \u0005נדבק,\u0006 הושלם\u0005].\u0006","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ריש לקיש, \u0005גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"במגלת ספר כתוב עלי\",\u0004 הרי שמגילה מגילה ניתנה! ומשיבים: הפסוק \u0003ההוא\u0004 בא ללמדנו ש\u0003כל התורה כולה איקרי\u0004 \u0005[נקראת]\u0006 \u0003מגילה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אלי מה אתה רואה ואמר אני ראה מגלה עפה\"\u0004 (זכריה ה, ב).","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003ל\u0004כמו שאמר \u0003ר' לוי,\u0004 ש\u0003אמר ר' לוי: שמנה פרשיות נאמרו ביום שהוקם בו המשכן,\u0004 כלומר, באחד בניסן. \u0003אלו הן: פרשת כהנים\u0004 שבפרשת \"אמור\" (ויקרא כא, א ואילך), \u0003ופרשת לוים\u0004 (במדבר ח, א ואילך), \u0003ופרשת טמאים\u0004 (\"תזריע\" ו\"מצורע\" בויקרא), \u0003ופרשת שילוח טמאים\u0004 (במדבר ה, א – ד), \u0003ופרשת \"אחרי מות\"\u0004 (ויקרא פרק טז),"],["\u0003ופרשת שתויי יין\u0004 (ויקרא י, ח-יא), \u0003ופרשת נרות\u0004 (במדבר ח, א-ז), \u0003ופרשת פרה אדומה\u0004 (במדבר פרק יט), שכל אלו נצרכו לעבודת המשכן כתיקונה.","ועוד מוסיפים דברים בענין כתיבת התורה, \u0003אמר ר' אלעזר: תורה\u0004 — \u0003רוב\u0004 שבה הוא \u0003בכתב ומיעוט\u0004 שבה הוא \u0003על פה, שנאמר: \"אכתב לו רבי תורתי כמו זר נחשבו\"\u0004 (הושע ח, יב), משמע שרוב התורה כתוב. \u0003ור' יוחנן אמר: רוב\u0004 התורה הוא \u0003על פה ומיעוט בכתב, שנאמר\u0004 בנתינת התורה למשה בסיני: \u0003\"כי על פי הדברים האלה\u0004 כרתי אתך ברית ואת ישראל","\u0003\"\u0004(שמות לד, כז). משמע שעיקר הברית היא בדברים שבעל פה (\"על פי\"). ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' יוחנן, \u0005גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אכתב לו רבי תורתי\"!\u0004 ומשיבים: \u0003ההוא,\u0004 דבר זה, לא נאמר כמשפט חיווי אלא כשאלה, \u0003אתמוהי קא מתמה\u0004 \u0005[תמה הוא]:\u0006 וכי \u0003אכתב לו רבי תורתי? הלא \"כמו זר נחשבו\"\u0004 — לא יהא הבדל בינם ובין האומות אם הכל היה כתוב! אלא הרוב צריך להישאר בעל פה.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' אלעזר, \u0005גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"כי על פי הדברים האלה\"!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 ממנו משמע שעיקר הברית הוא על דברים שבעל פה — הרי זה \u0003משום דתקיפי למיגמרינהו\u0004 \u0005[ש\u0006דברים שבעל פה \u0005קשים ללמוד אותם]\u0006 יותר מן התורה שבכתב, ולא משום שהם מרובים יותר.","\u0003דרש ר' יהודה בר נחמני מתורגמניה\u0004 \u0005[מתורגמנו]\u0006 של \u0003ר' שמעון בן לקיש, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כתב לך את הדברים האלה\"\u0004 (שמות לד, כז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק: \u0003\"כי על פי הדברים האלה\"\u0004 (שמות לד, כז), \u0003הא כיצד?\u0004 — לומר: \u0003דברים שבכתב אי\u0004 (אין) \u0003אתה רשאי לאומרן על פה, דברים שבעל פה אי אתה רשאי לאומרן בכתב. דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \u0003\"אלה\"\u0004 בציווי \"כתוב לך את הדברים האלה\" — הרי הוא הדגשה: \u0003אלה,\u0004 דברים אלה של תורה שבכתב, \u0003אתה כותב, ואי אתה כותב הלכות\u0004 (משניות, תורה שבעל פה).","\u0003אמר ר' יוחנן: לא כרת הקדוש ברוך הוא ברית עם ישראל אלא בשביל דברים שבעל פה, שנאמר: \"כי על פי הדברים האלה כרתי אתך ברית ואת ישראל\"\u0004 (שמות לד, כז).","שנינו במשנה ש\u0003מערבין בבית ישן, מפני דרכי שלום.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום כבוד\u0004 שיש בכך לבעליו של אותו הבית, \u0003והא\u0004 \u0005[והרי]\u0006 מסופר מעשה ב\u0003ההוא שיפורא\u0004 \u0005[אותו שופר,\u0006 קופה של צדקה\u0005],\u0006 שאף הוא דבר הנעשה לצורכו של הציבור ומתכבד בו הבית שהוא שם, \u0003דהוה מעיקרא\u0004 \u0005[שהיה מתחילה]\u0006 \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב יהודה, ולבסוף\u0004 (ואחרי כן) העבירוהו ל\u0003בי\u0004 \u0005[בית]\u0006 \u0003רבה, ולבסוף\u0004 העבירוהו ל\u0003בי\u0004 \u0005[בית]\u0006 \u0003רב יוסף, ולבסוף\u0004 העבירוהו ל\u0003בי\u0004 \u0005[בית]\u0006 \u0003אביי, ולבסוף\u0004 עוד העבירוהו ל\u0003בי\u0004 \u0005[בית]\u0006 \u0003רבא!\u0004 משמע שאין זה ענין של כבוד, ונוטלים את הדבר ממקום למקום!","\u0003אלא\u0004 יש לומר שהוא \u0003משום חשדא\u0004 \u0005[חשד],\u0006 שכיון שהם רגילים עד כה לשים את העירוב באותו מקום, אם יוציאו אותו משם ויניחוהו במקום אחר, יאמרו אנשים שחשדו בני המבוי בבעל הבית שהוא גונב ממנו, ולכן הוציאוהו מידו.","שנינו במשנה ש\u0003בור שהוא קרוב לאמה\u0004 מתמלא תחילה מפני דרכי שלום. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הזו: \u0003בני נהרא\u0004 \u0005[הנהר]\u0006 ששדותיהם ליד הנהר ומשקים אותם מתעלות הבאות מן הנהר, מי מהם משקה תחילה את שדותיו? \u0003רב אמר: תתאי שתו מיא ברישא\u0004 \u0005[התחתונים,\u0006 במורד הנהר, \u0005שותים\u0006 את \u0005המים,\u0006 משקים \u0005בתחילה],\u0006 \u0003ושמואל אמר: עילאי שתו מיא ברישא\u0004 \u0005[העליונים שותים מים בתחילה].\u0006","ומסבירים: \u0003בדמיזל כולי עלמא לא פליגי\u0004 \u0005[ב\u0006מצב \u0005ש\u0006בו \u0005המים הולכים\u0006 מעצמם \u0005הכל אינם חלוקים]\u0006 שכל הרוצה להשקות — ישקה כפי שהוא רוצה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003במיסכר ואשקויי\u0004 \u0005[ב\u0006מקום \u0005שצריכים\u0006 \u0005לסכור\u0006 את הנהר \u0005ולהשקות\u0006 בתעלות\u0005];\u0006 \u0003שמואל אמר: עילאי שתו מיא ברישא\u0004 \u0005[העליונים שותים מים בתחילה],\u0006 משום \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים,\u0006 שהם יכולים לטעון\u0005]:\u0006 \u0003אנן מקרבינן טפי\u0004 \u0005[אנו קרובים יותר]\u0006 לראשיתו של הנהר. \u0003ורב אמר: תתאי שתו מיא ברישא\u0004 \u0005[התחתונים שותים מים בתחילה],\u0006 משום \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003נהרא כפשטיה ליזיל\u0004 \u0005[הנהר כדרכו ילך]\u0006 ואתם תסכרו אותו אחרינו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003בור הקרוב לאמה מתמלא ראשון מפני דרכי שלום!\u0004 משמע שהקרוב קודם, כלומר, העליונים, כשיטתו של שמואל, והרי זה קשה לרב. \u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003שמואל אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רב:\u0004 מדובר כאן \u0003באמה\u0004 (תעלה) \u0003המתהלכת על פי בורו,\u0004 שהוא מתמלא מאליו, ואין צריך לעשות בו דבר.","ומשיבים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 בא \u0005לומר]?\u0006 הרי פשוט הוא! ומשיבים: חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003מצי אמרי ליה\u0004 \u0005[יכולים לומר לו]\u0006 שאר בעלי השדות לבעל הבור: \u0003סכר מיסכר\u0004 \u0005[תסכור]\u0006 גם אתה את בורך, שלא יכנסו המים לתוכו, \u0003ואשקי בהינדזא\u0004 \u0005[ותשקה לפי התור],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו צריך לעשות כן, וממילא הוא מתמלא ראשון.","\u0003אמר רב הונא בר תחליפא: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003לא איתמר הלכתא\u0004 \u0005[נאמרה הלכה]\u0006 \u0003לא כמר\u0004 \u0005[כחכם זה]\u0006 \u0003ולא כמר\u0004 \u0005[כחכם זה],\u0006 לא כרב ולא כשמואל, \u0003כל דאלים\u0004 \u0005[שחזק\u0006 יותר\u0005]\u0006 \u0003גבר\u0004 \u0005[גובר]\u0006 ואין אנו מתערבים בענין זה, אלא אנשים יסתדרו ביניהם.","\u0003רב שימי בר אשי אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לותבן מר בעידנא\u0004 \u0005[יושיבני,\u0006 יקבע לי, \u0005אדוני זמן\u0006 ללמוד\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אית לי עידנא לדידי\u0004 \u0005[יש לי זמן\u0006 קבוע \u0005בשבילי]\u0006 ואיני יכול להקדיש אותו עבורך. אמר לו: \u0003ולותבן מר בליליא\u0004 \u0005[ויושיב אותי אדוני בלילה]\u0006 ואז נלמד! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי,\u0004 אני צריך \u0003מיא לאשקויי\u0004 \u0005[מים להשקות]\u0006 את שדותי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא משקינא ליה למר מיא ביממא, ולותבן מר בליליא\u0004 \u0005[אני אשקה לאדוני את המים ביום, ויושיב אותי אדוני בלילה\u0006 ונלמד\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לחיי\u0004 \u0005[לחיים],\u0006 כלומר, בסדר. מה עשה רב שימי בר אשי?","\u0003אזל לעילאי\u0004 \u0005[הלך ל\u0006אלה שהיו \u0005למעלה\u0006 ממנו\u0005]\u0006 במעלה הנהר, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תתאי שתו מיא ברישא\u0004 \u0005[התחתונים שותים מים בתחילה]\u0006 כדברי רב, \u0003אזל לתתאי\u0004 \u0005[הלך ל\u0006אלה שהיו \u0005תחתונים ממנו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003עילאי שתו מיא ברישא\u0004 \u0005[העליונים שותים מים בתחילה]\u0006 כדברי שמואל, \u0003אדהכי\u0004 \u0005[בינתיים]\u0006 עד שדנו בדבר התחתונים והעליונים מי ישקה \u0003סכר מיסכר ואשקי\u0004 \u0005[סכר\u0006 את הנהר \u0005והשקה]\u0006 את שדותיו של אביי. \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא לפני]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כבי תרי עבדת לי\u0004 \u0005[כמו שתי\u0006 שיטות הפוכות \u0005עשית לי]!\u0006 \u0003ולא טעמינהו\u0004 \u0005[טעם אותם]\u0006 \u0003אביי לפירי דההיא שתא\u0004 \u0005[את הפירות של אותה שנה],\u0006 מפני שחשב שהמים הגיעו אליו שלא כדין.","מסופר: \u0003הנהו\u0004 \u0005[\u0006אנשים \u0005מסויימים]\u0006 שהיו \u0003בני\u0004 המקום הנקרא \u0003בי חרמך\u0004 \u0003דאזול\u0004 \u0005[שהלכו]\u0006 ו\u0003כרו\u0004 תעלה \u0003ברישא\u0004 \u0005[בתחילת]\u0006 נהר \u0003שנוותא\u0004 כדי שתקיף את שדותיהם \u0003ואהדרוה ושדיוה בשילהי נהרא\u0004 \u0005[והחזירוה בסוף הנהר].\u0006 \u0003אתו עילאי לקמיה\u0004 \u0005[באו\u0006 אלה שהיו \u0005למעלה\u0006 מהם \u0005לפני]\u0006 \u0003אביי, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003קא מתקיל לנהרין\u0004 \u0005[זה יוצר תקלה,\u0006 עיכוב, \u0005לנהר שלנו]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כרו בהדייהו טפי פורתא\u0004 \u0005[העמיקו יחד איתם קצת יותר]\u0006 ואז יהיה מספיק מים. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003קא יבשי פירין\u0004 \u0005[הבורות שלנו מתייבשים]\u0006 על ידי כך. כיון ששמע כך \u0003אמר להו\u0004 \u0005[להם]\u0006 לבני חרמך: \u0003זילו סליקו נפשייכו מהתם\u0004 \u0005[סלקו את עצמכם משם]\u0006 וסכרו את הדרך החדשה שעשיתם לנהר.","שנינו במשנה: \u0003מצודות חיה ועופות ודגים יש בהן\u0004 משום גזל משום דרכי שלום, ור' יוסי אומר שגזל גמור הוא. ומעירים: \u0003באוזלי ואוהרי\u0004 \u0005[ברשתות ומלכודות]\u0006"],["\u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שכיון שהם כלים שיש להם תוך, והדגים או החיות נכנסו אל תוכם — הריהם שייכים מן הדין לבעל המלכודת, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003בלחי וקוקרי\u0004 \u0005[בחכה\u0006 ושאר \u0005מצודות]\u0006 שאין בהן תוך, והדגים רק נתקלים שם. שמאחר שאין בעל המלכודת זוכה בהם מן הדין, יש מקום לאסור על אחר ליטלם רק מפני דרכי שלום.","עוד שנינו במשנתנו: \u0003מציאת חרש שוטה\u0004 וקטן — גזל מפני דרכי שלום, \u0003ר' יוסי אומר: גזל גמור. אמר רב חסדא:\u0004 הכוונה בדברי ר' יוסי היא שהוא \u0003גזל גמור מדבריהם,\u0004 מדברי סופרים, ולא ממש גזל גמור מדין תורה. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 איזה הבדל יש הלכה למעשה אם הוא גזל גמור מדברי סופרים ולא רק גזל מפני דרכי שלום? ומשיבים: \u0003להוציאו\u0004 את מה שגזל בדיינין, שכיון שהוא גזל גמור, אם עשה אדם כך — יכול הדיין לכפותו להוציא מידו.","ועוד שנינו במשנתנו: \u0003עני המנקף בראש הזית — מה ש\u0004נפל \u0003תחתיו\u0004 שייך לו, מפני דרכי שלום. ואילו לדעת ר' יוסי הנוטל משם הוא גזל גמור. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם ליקט\u0004 העני \u0003ונתן ביד\u0004 תחילה לפני שנפלו הפירות ארצה — \u0003הרי זה גזל גמור,\u0004 לפי שזכה העני משעה שהיה הפרי בידו.","מסופר: \u0003רב כהנא הוה קאזיל\u0004 \u0005[היה הולך]\u0006 לעיר \u0003הוצל,\u0004 \u0003חזייה לההוא גברא דהוה שדי אופיי וקא נתרן תמרי\u0004 \u0005[ראהו לאדם אחד שהיה משליך מקלות\u0006 בדקל \u0005והתמרים היו נופלים],\u0006 \u0003אזל קא מנקיט ואכיל\u0004 \u0005[הלך\u0006 רב כהנא \u0005ליקט\u0006 מהם \u0005ואכל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו האיש: \u0003חזי מר דבידאי שדיתינהו\u0004 \u0005[ראה אדוני שבידי זרקתי אותם],\u0006 כלומר, התמרים היו כבר בידי, ושלי הם מן הדין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003מאתריה\u0004 \u0005[ממקומו]\u0006 של \u0003ר' יאשיה אתה\u0004 שהיה החכם בעיר הוצל, ומשום כך אתה בקי בהלכה. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 על ר' יאשיה: \u0003\"וצדיק יסוד עולם\"\u0004 (משלי י, כה) שאפילו אחרי מותו הניח יסוד לעולם, שיהא מקומו מקום תורה.","עוד שנינו במשנה: \u0003אין ממחין ביד עניי גוים\u0004 שלא יטלו \u0003בלקט בשכחה ובפאה, מפני דרכי שלום.\u0004 כיוצא בזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מפרנסים עניי גוים עם עניי ישראל, ומבקרין חולי גוים עם חולי ישראל, וקוברין מתי גוים עם מתי ישראל,\u0004 וכל אלה עושים \u0003מפני דרכי שלום.\u0004","\u0003משאלת\u0004 (מותרת להשאיל) \u0003אשה לחבירתה החשודה על\u0004 פירות השנה \u0003השביעית\u0004 (שאוכלתם לאחר זמן הביעור, שאז אסורים הם באכילה), כלים כגון: \u0003נפה וכברה וריחים ותנור,\u0004 ואין אומרים שהיא מסייעת בכך לעבירה. \u0003אבל\u0004 היא עצמה \u0003לא תבור\u0004 (תברור) עימה חיטים \u0003ולא תטחן עמה\u0004 חיטים, שלא תעשה בידיים מעשה של סיוע לעבירה.","\u0003אשת חבר,\u0004 המדקדק בהפרשת תרומות ומעשרות ובדיני טומאה וטהרה, \u0003משאלת לאשת עם הארץ\u0004 החשוד על דברים אלו, \u0003נפה וכברה, ו\u0004אף \u0003בוררת\u0004 חיטים עימה, \u0003וטוחנת\u0004 עימה, \u0003ומרקדת\u0004 (מנפה) \u0003עמה, אבל משתטיל\u0004 אשת עם הארץ \u0003את המים\u0004 בעיסה, ומאותה שעה יכולה העיסה להיטמא, \u0003לא תגע עמה, לפי שאין מחזיקין\u0004 (מסייעים) \u0003ידי עוברי עבירה. וכולן,\u0004 כל הדברים שנאמרו במשנתנו להתיר, \u0003לא\u0004 \u0003אמרו\u0004 \u0003אלא מפני דרכי שלום.\u0004","\u0003ומחזיקין ידי גוים\u0004 העובדים \u0003בשביעית, אבל לא\u0004 מחזקים את \u0003ידי ישראל\u0004 העושים כן, \u0003ו\u0004כן \u0003שואלין בשלומן\u0004 של גויים \u0003מפני דרכי שלום.\u0004","ושואלים על ההלכות השנויות במשנה: \u0003מאי שנא\u0004 \u0003רישא\u0004 \u0005[במה שונה תחילת\u0006 המשנה\u0005]\u0006 ששנינו בה לגבי חשודה על שביעית שלא תבור עימה, \u0003ומאי שנא סיפא\u0004 \u0005[ובמה שונה סופה\u0006 של המשנה\u0005]\u0006 ששנינו בה שמותר לאשת חבר לסייע גם בברירה וטחינה לאשת עם הארץ? \u0003אמר אביי: רוב עמי הארץ מעשרין הן,\u0004 ולכן מעיקר הדין אין מקום לאסור לסייע בידם, שהרי מסתבר שאשת עם הארץ מכינה מאכל מותר. ואף שיש בכל זאת מקום לחשוש שאין המאכל מעושר מפני מיעוט שבעמי הארץ שאין מעשרים, הרי מפני דרכי שלום אין מקפידים על כך.","\u0003רבא אמר: הכא\u0004 \u0005[כאן\u0006 במשנתנו\u0005]\u0006 מדובר \u0003בעם הארץ דר'\u0004 \u0003מאיר\u0004 (לשיטת ר' מאיר), \u0003ו\u0004לענין הלכות \u0003טומאה וטהרה דרבנן\u0004 \u0005[מדברי חכמים]\u0006 ולא לענין הפרשת תרומות ומעשרות. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו עם הארץ? כל שאינו אוכל חוליו\u0004 (חולין שלו) \u0003בטהרה,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: כל שאינו מעשר פירותיו.\u0004 וכיון שמדובר בעם הארץ כזה שאנו מניחים שעישר את פירותיו, אלא שאינו אוכל חוליו בטהרה, בענין זה של אכילת חולין בטהרה שהוא מדברי סופרים, לא אסרו חכמים לסייע לאשת עם הארץ שכזה לבור ולטחון, משום דרכי שלום.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנה\u0006 ב\u0005סופה\u0006 של אותה הלכה שבמשנה\u0005]:\u0006 \u0003משתטיל את המים לא תגע עמה,\u0004 ודבר זה הוא משום שעל ידי המים מוכשרת העיסה לקבל טומאה, \u0003מכלל\u0004 הדבר אתה \u0003למד\u0004 \u0003דרישא\u0004 \u0005[שבתחילת\u0006 אותה הלכה שבמשנה\u0005]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ב\u0004דיני \u0003טומאה וטהרה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 אלא בחשש אחר, של מעשרות!","ומשיבים: \u0003רישא וסיפא\u0004 \u0005[תחילתה וסופה]\u0006 של ההלכה קשורים \u0003ב\u0004חשש ל\u0003טומאה וטהרה, ו\u0004אולם \u0003רישא\u0004 \u0005[בתחילה]\u0006 אף שמדובר בתבואה שהוכשרה לקבל טומאה, יש חשש רק \u0003בטומאת חולין,\u0004 וטומאת חולין אינה אסורה מן התורה כלל, אלא החברים הם שנזהרו בכך, \u0003וסיפא\u0004 \u0005[ובסופה]\u0006 מדובר \u0003בטומאת חלה\u0004 שמשעה זו חל חיוב חלה על העיסה, ומפני החלה המעורבת בעיסה יש להיזהר ואסור מן התורה לטמא אותה.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר:"],["\u0003טוחנין ומפקידין\u0004 פירות מעושרים \u0003אצל אוכלי שביעית, ואצל אוכלי פירותיהן\u0004 (של עצמם) \u0003בטומאה,\u0004 שאין חוששים שהם יחליפו פירות אלה בפירות שביעית או בפירות טמאים, או שיגעו בפירות, \u0003אבל לא\u0004 טוחנים \u0003לאוכלי שביעית ולא לאוכלי פירותיהן בטומאה\u0004 את פירותיהם, כדי שלא לסייע בידם. וקשה לפירוש רבא למשנתנו, ולפיו טוחנת אשת חבר עם אשת עם הארץ האוכל חולין בטומאה!","\u0003אמר אביי: התם\u0004 \u0005[שם\u0006 באותה ברייתא\u0005]\u0006 \u0003בכהן החשוד לאכול תרומה בטומאה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דהוה ליה\u0004 \u0005[שהריהו]\u0006 איסור \u0003טומאה דאורייתא\u0004 \u0005[שמן התורה].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בכהן, כיצד \u0003מפקידין\u0004 אצלו פירות מתוקנים? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו: \u0003מפקידין תרומה אצל ישראל עם הארץ,\u0004 שלמרות שהוא אינו נזהר בדיני טהרה, אין לחשוש שיטמא תרומה, \u0003ולא אצל כהן עם הארץ, מפני שלבו גס\u0004 (רגיל ומזלזל) בה בתרומה, ושמא יגע בה ויטמאנה!","\u0003אמר ר' אילעא:\u0004 \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 בברייתא הקודמת \u0005במה אנו עוסקים]\u0006 — באופן שהכניס את פיקדון התרומה \u0003בכלי חרש המוקף צמיד פתיל\u0004 ואין חשש במקרה כזה שמא הכהן החשוד לאכול תרומה בטומאה יטמא אותו במגע.","ושואלים: \u0003וליחוש\u0004 \u0005[ו\u0006עדיין \u0005נחשוש]\u0006 \u0003שמא תסיטנו\u0004 (תזיז אותו) \u0003אשתו\u0004 של אותו כהן \u0003נדה,\u0004 ונדה שיש בה חשש של טומאת זבה, מטמאה מה שבכלי אפילו בהיסט (= בהזזה) גם בלי לנגוע בתוכו, ואין מועיל לו לכלי הצמיד פתיל שמקיפו!","\u0003אלא אמר ר' ירמיה, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאסרו להפקיד, מדובר \u0003בפירות שהוכשרו\u0004 לקבל טומאה, ולכן יש מקום לחשש שיטמאם הכהן. \u0003כאן\u0004 שהתירו להפקיד, מדובר בפירות \u0003שלא הוכשרו\u0004 לקבל טומאה, ולכן אין מקום לחשש טומאה.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003המוליך חטין\u0004 מתוקנות \u0003לטוחן כותי או לטוחן עם הארץ\u0004 — \u0003הרי אלו בחזקתן למעשר ולשביעית\u0004 שלא החליפן, \u0003אבל לא לטומאה\u0004 שאינן עוד בחזקת טהורות, משמע שחוששים שמא יגע בהן!","ושואלים: \u0003האי מאי רומיא\u0004 \u0005[זו מה סתירה\u0006 היא\u0005]?\u0006 \u0003לאו אוקימנא\u0004 \u0005[האם לא העמדנו]\u0006 את מה שאמרה הברייתא שמותר להפקיד \u0003בפירות שלא הוכשרו\u0004 לקבל טומאה ואין מגע הטמא מטמאם? ואילו כאן מדובר בפירות שהוכשרו, ולכן חוששים לטומאה!","ותוהים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[וזה שהקשה\u0006 את הקושיה \u0005הזו מה הקשה אותה]?\u0006 הלא התירוץ כבר נאמר מקודם וברור הוא מעצמו! ומשיבים: אכן, המקשה לא הביא משנה זו אלא \u0003משום דקא בעי למירמי אחריתי עלה\u0004 \u0005[שרצה להשליך,\u0006 להראות סתירה ממשנה \u0005אחרת עליה].\u0006 וקושייתו היא שממה ששנינו במשנה זו \u0003הרי אלו בחזקתן למעשר ולשביעית,\u0004 משמע: \u0003ולחלופי\u0004 \u0005[ולהחלפה],\u0006 שמא החליף את החיטים שקיבל בחיטים משלו שיש בהן צד איסור, \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו: \u0003הנותן\u0004 מזון \u0003לחמותו\u0004 שהיא עם הארץ שתתקינם לו לאכילה, \u0003מעשר את\u0004 כל מה \u0003שהוא נותן לה ואת\u0004 כל מה \u0003שהוא נוטל הימנה, מפני שחשודה\u0004 שהיא \u0003מחלפת\u0004 את האוכל שלו \u0003המתקלקל\u0004 באוכל משלה שלא התקלקל, ושמא לא החזירה לו את האוכל שנתן לה, אלא דבר אחר שאינו מעושר. הרי שחוששים להחלפה!","ומשיבים: \u0003התם כדקתני טעמא\u0004 \u0005[שם כפי ששנה את הטעם]\u0006 שיש טעם מיוחד בדבר, וכפי ששנינו, \u0003אמר ר' יהודה: רוצה היא\u0004 החמות \u0003בתקנת בתה\u0004 שתאכל דבר שאינו מקולקל, \u0003ובושה מחתנה\u0004 לומר לו שנתן לה דבר מקולקל, ומשום כך אינה אומרת לו שהחליפה.","ושואלים: \u0003ולעלמא לא חיישינן\u0004 \u0005[ולסתם\u0006 אנשים \u0005אין אנו חוששים]\u0006 שיחליפו במקרה שכזה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנותן\u0004 מזון \u0003לפונדקית\u0004 שתכין בשבילו אוכל ממנו, \u0003מעשר את שהוא נותן לה ואת שהוא נוטל הימנה, מפני שמחלפת!\u0004 משמע שלא רק בחמותו אנו חוששים! ומשיבים: \u0003התם מוריא ואמרה\u0004 \u0005[שם\u0006 הפונדקית \u0005מורה\u0006 היתר לעצמה לעשות כן \u0005ואומרת]:\u0006 מדוע \u0003בר בי רב ליכול חמימא, ואנא איכול קרירא\u0004 \u0005[בן בית המדרש\u0006 הזה \u0005יאכל\u0006 אוכל \u0005חם ואני אוכל קר]?!\u0006 ולכן חוששים שמא החליפה.","ושואלים: \u0003ואכתי לעלמא לא חיישינן\u0004 \u0005[ועדיין, לסתם\u0006 אדם \u0005אין אנו חוששים]\u0006 להחלפה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אשת חבר טוחנת עם אשת עם הארץ בזמן שהיא\u0004 (אשת החבר) טמאה, כגון שהיא נידה ואז נזהרת מלנגוע באוכל, ואין חשש שתאכל דברים שאינם מעושרים, \u0003אבל לא בזמן שהיא טהורה. ר' שמעון בן אלעזר אומר: אף בזמן שהיא טמאה לא תטחון, מפני שחברתה\u0004 (אשת עם הארץ)"]]};
